INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C1','kor',3,2,'u3',2,'설명하는 글과 일의 차례 — 무엇을 만드는 방법·가는 길·놀이를 하는 차례처럼 일을 알려 주는 글이 설명하는 글이고, 읽는 사람이 그대로 따라 할 수 있게 일의 차례가 드러나야 함(글씨 크기·글 길이가 아님)',ARRAY['[4국02-05][4국03-02]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C2','kor',3,2,'u3',2,'설명할 내용을 알아볼 곳 — 아는 것만으로 모자라면 책·누리집·잘 아는 어른께 여쭈어 확인하고, 그럴듯하게 지어내거나 짐작해 쓰지 않음',ARRAY['[4국02-05]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C3','kor',3,2,'u3',2,'출처의 뜻 — 자료를 만든 곳이나 자료의 이름처럼 가져온 자료가 어디에서 왔는지 알려 주는 것(글을 쓴 사람·신문 이름·쓴 날짜·쪽수는 출처가 아님)',ARRAY['[4국02-05]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C4','kor',3,2,'u3',2,'출처가 나타나는 곳 — 글 속 문장 안(「…에 따르면」), 그림 자료 바로 아래(「■ 출처」), 영상 화면 아래 작은 글씨처럼 자료에 따라 여러 방법으로 밝힘',ARRAY['[4국02-05]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C5','kor',3,2,'u3',2,'출처를 밝히는 까닭 — 읽는 사람이 믿을 만한 자료인지 살펴볼 수 있고, 만든 사람의 것을 내 것처럼 쓰지 않았다는 뜻이 되어 다른 사람이 만든 것을 존중하는 일이 됨',ARRAY['[4국02-05]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C6','kor',3,2,'u3',3,'글쓴이의 의견과 자료·출처 정리 — 주장하는 글에서 글쓴이의 의견과 까닭을 찾고, 글에 쓰인 자료마다 출처를 짝지어 정리하며, 들은 이야기·아래에 아무 글 없는 그림처럼 출처가 없는 자료를 가려냄',ARRAY['[4국02-05]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C7','kor',3,2,'u3',3,'출처를 확인하며 읽으면 좋은 점 — 글에 쓰인 자료가 믿을 만한지 살펴볼 수 있고, 더 알고 싶을 때 어디에 가서 찾아볼지 알 수 있음; 출처가 없으면 찾아갈 곳을 알 수 없음',ARRAY['[4국02-05]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C8','kor',3,2,'u3',3,'출처가 있는 자료를 대하는 태도 — 출처가 붙어 있다고 다 맞는 것도, 다 거짓인 것도 아니므로 어떤 곳에서 가져왔는지 살펴보고 생각하며 읽음(출처는 「믿어라」는 표가 아니라 「살펴볼 수 있다」는 표)',ARRAY['[4국02-05]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C9','kor',3,2,'u3',5,'스스로 출처를 찾으며 글 내용 알기 — 밑줄 같은 표시가 없어도 「…에 따르면」·「■ 출처」처럼 가져온 곳을 밝힌 말을 찾아 자료와 출처를 정리하고, 글이 무엇을 설명하는지와 글에 쓰인 내용을 확인함',ARRAY['[4국02-05]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C10','kor',3,2,'u3',5,'글에 나온 낱말의 뜻 — 가꾸다(잘 자라도록 보살피다)·차례(순서에 따라 돌아오는 것)·마련하다(필요한 것을 준비해 갖추다)를 그 낱말이 든 문장에서 짐작하고 바꾸어 넣어 확인함',ARRAY['[4국02-05]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C11','kor',3,2,'u3',5,'출처가 알맞은지 확인하는 방법 — 적혀 있는 곳에 직접 가 보거나 그 누리집에 들어가 보고, 그곳이 어떤 곳인지 알아봄(이름이 길거나 글씨가 크다고 믿을 만한 것이 아님)',ARRAY['[4국02-05]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C12','kor',3,2,'u3',7,'이어 주는 말의 쓰임 — 그리고(앞과 비슷한 내용이 이어질 때)·그러나(앞과 반대되는 내용이 이어질 때)·그래서(앞이 뒤의 까닭이 될 때)처럼 앞뒤 문장의 관계에 따라 알맞은 말을 고름(때·곳을 나타내는 말은 이어 주는 말이 아님)',ARRAY['[4국04-04][4국03-02]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C13','kor',3,2,'u3',7,'이어 주는 말을 알맞게 쓰기 — 이어 주는 말은 많이 쓸수록 좋은 것이 아니라 앞뒤 뜻이 어떻게 이어지는지에 맞을 때 쓰며, 문장마다 빠짐없이 넣지도 하나도 쓰지 않지도 않음',ARRAY['[4국04-04][4국03-02]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C14','kor',3,2,'u3',9,'쓰기 전에 생각할 것 — 이 글을 읽을 사람·쓰는 목적·꼭 들어가야 할 내용을 먼저 정하면 쓸 내용이 보이고, 글씨 색·글자 수 같은 꾸밈은 나중의 일임',ARRAY['[4국03-02]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C15','kor',3,2,'u3',9,'알기 쉽게 고쳐 쓰기와 차례를 나타내는 말 — 어려운 낱말은 쉬운 말로 풀고, 먼저·다음으로·끝으로(처음에·그다음에·마지막으로, 첫째·둘째·셋째)를 일의 순서에 맞게 넣어 무엇을 먼저 할지 드러냄',ARRAY['[4국03-02]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C16','kor',3,2,'u3',9,'쓸 때 출처 밝히기 — 책이나 안내판에서 알아낸 내용을 썼다면 가져온 곳을 글 끝에 밝히고(빼지도 내 것처럼 쓰지도 않음), 찾아본 곳이 기억나지 않으면 지어 적지 않고 다시 확인해 적거나 그 내용은 쓰지 않으며, 내가 이미 해 본 방법에는 출처가 없어도 됨',ARRAY['[4국03-02]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C17','kor',3,2,'u3',10,'처음·가운데·끝으로 짜기 — 읽을 사람을 먼저 정한 뒤, 처음에는 무엇을 설명할 글인지 밝히고 가운데에는 일의 차례와 방법을 자세히, 끝에는 설명한 내용을 간추림',ARRAY['[4국03-02]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C18','kor',3,2,'u3',10,'쓴 글 점검하기와 서로 다른 방법 — 차례와 방법이 드러났는지·읽는 사람이 궁금해할 내용을 넣었는지·이어 주는 말이 알맞은지·출처를 밝혔는지를 고치려고 살피며, 같은 일도 방법이 달라도 차례와 까닭이 드러나면 둘 다 알맞은 글임',ARRAY['[4국03-02]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C19','kor',3,2,'u3',12,'함께 쓰는 곳의 이용 설명서 — 어떤 곳인지·이용하는 차례·지킬 것으로 문단을 나누어 맡고, 안내판·안내장·누리집 알림 글·사진처럼 자료의 종류가 달라도 가져온 곳을 똑같이 적으며, 하나로 모을 때 이어 주는 말로 잇고 빠진 차례를 살핌',ARRAY['[4국03-02][4국04-04]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C20','kor',3,2,'u3',12,'‘-데’와 ‘-대’ — 내가 직접 겪어 안 것을 말할 때는 ‘-데’, 남의 말을 전할 때(…다고 해)는 ‘-대’를 씀; ‘보니’가 붙었는지가 아니라 내가 겪었는지 남에게 들었는지가 가름(기초 다지기)',ARRAY['[4국04-04]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C21','kor',3,2,'u3',12,'낱말 그물 — 한 낱말에서 그곳에 있는 것·그곳에서 하는 일·그곳에서 지킬 것처럼 떠오르는 말이 여러 갈래로 뻗고, 떠오른 까닭은 저마다 다름(기초 다지기)',ARRAY['[4국04-04]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X01','kor',3,'u3',ARRAY['K3-2-u3-C1','K3-2-u3-C15']::text[],'설명하는 글을 따라 하기 어려운 까닭을 글씨 크기·글 길이에서 찾고, 일의 차례가 드러나야 한다는 것을 놓친다','읽는 사람이 무엇을 먼저 해야 하는지 알까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X02','kor',3,'u3',ARRAY['K3-2-u3-C2','K3-2-u3-C19']::text[],'설명할 내용이 모자라면 그럴듯하게 지어내거나 짐작해서 쓴다','내가 확인할 수 있는 곳인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X03','kor',3,'u3',ARRAY['K3-2-u3-C3','K3-2-u3-C9']::text[],'출처를 글쓴이 이름·신문 이름·쓴 날짜·쪽수와 헷갈린다','가져온 자료가 온 곳은 어디?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X04','kor',3,'u3',ARRAY['K3-2-u3-C4']::text[],'출처는 자료 아래 「■ 출처」로만 적는다고 여겨 글 속 「…에 따르면」을 놓치거나, 출처를 밝힌 곳을 엇갈리게 안다','글 속 문장 안에도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X05','kor',3,'u3',ARRAY['K3-2-u3-C5']::text[],'출처를 밝히는 까닭을 글을 길어 보이게·어려워 보이게 하려고라고 여긴다','읽는 사람은 출처로 무엇을 할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X06','kor',3,'u3',ARRAY['K3-2-u3-C5','K3-2-u3-C16']::text[],'다른 사람이 만든 자료를 가져와 내가 생각해 낸 것처럼 쓴다','그 자료를 만든 사람은 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X07','kor',3,'u3',ARRAY['K3-2-u3-C16']::text[],'찾아본 자료는 출처를 밝히면 쓸 수 있는데도 아예 빼야 한다고 여긴다','가져온 곳을 밝히면 쓸 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X08','kor',3,'u3',ARRAY['K3-2-u3-C6','K3-2-u3-C9']::text[],'글쓴이의 의견이나 글에 쓰인 내용을 잘못 읽는다','그 내용이 적힌 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X09','kor',3,'u3',ARRAY['K3-2-u3-C6','K3-2-u3-C9']::text[],'출처가 적혀 있지 않은 자료(들은 이야기·아래에 아무 글 없는 그림)도 출처가 있다고 여기거나, 자료와 출처를 엇갈리게 잇는다','그 자료 바로 옆·아래에 가져온 곳이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X10','kor',3,'u3',ARRAY['K3-2-u3-C7']::text[],'출처를 확인하며 읽으면 글을 더 빨리 읽거나 읽지 않아도 내용을 알 수 있다고 여긴다','출처를 보면 무엇을 더 할 수 있게 되나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X11','kor',3,'u3',ARRAY['K3-2-u3-C7']::text[],'출처가 없는 자료의 아쉬움(더 알고 싶어도 찾아갈 곳이 없음)을 모르고 글 길이·낱말 탓을 한다','「어떤 형에게 들었다」면 어디로 가나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X12','kor',3,'u3',ARRAY['K3-2-u3-C8']::text[],'출처가 적혀 있으면 무엇이든 그대로 믿는다','이름만 적어 놓은 것일 수도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X13','kor',3,'u3',ARRAY['K3-2-u3-C8']::text[],'출처가 있어도 거짓일 수 있다며 글에 쓰인 자료를 무조건 믿지 않는다','살펴보고 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X14','kor',3,'u3',ARRAY['K3-2-u3-C11']::text[],'출처의 이름이 길거나 글씨가 크면 믿을 만하다고 여겨, 직접 가 보거나 누리집에 들어가 보는 확인을 하지 않는다','내가 직접 해 볼 수 있는 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X15','kor',3,'u3',ARRAY['K3-2-u3-C10']::text[],'낱말 뜻을 앞뒤 문장을 보지 않고 짐작해 다른 낱말의 뜻과 섞는다','그 낱말이 든 문장에 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X16','kor',3,'u3',ARRAY['K3-2-u3-C12','K3-2-u3-C19']::text[],'그리고·그러나·그래서의 쓰임(비슷한 내용·반대되는 내용·까닭)을 엇갈리게 안다','앞과 뒤가 비슷한가, 반대인가, 까닭인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X17','kor',3,'u3',ARRAY['K3-2-u3-C12']::text[],'때나 곳을 나타내는 말(목요일·체육관에서)을 이어 주는 말로 여긴다','앞 문장과 뒤 문장을 이어 주나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X18','kor',3,'u3',ARRAY['K3-2-u3-C13']::text[],'이어 주는 말은 문장마다 빠짐없이 넣을수록 좋다고 여긴다','개수가 아니라 앞뒤 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X19','kor',3,'u3',ARRAY['K3-2-u3-C13']::text[],'이어 주는 말을 하나도 쓰지 않아 앞뒤 문장이 왜 붙어 있는지 드러나지 않는다','두 문장이 왜 붙어 있지?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X20','kor',3,'u3',ARRAY['K3-2-u3-C14','K3-2-u3-C17']::text[],'글을 쓰기 전에 글씨 색·글자 수·제목 꾸미기부터 정한다','쓰기 전에 정할 것과 다 쓴 뒤 꾸밀 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X21','kor',3,'u3',ARRAY['K3-2-u3-C14','K3-2-u3-C15','K3-2-u3-C17']::text[],'읽을 사람과 목적을 생각하지 않고 쓸 내용을 정하거나, 어려운 낱말을 많이 써야 좋은 설명하는 글이라고 여긴다','누가 읽나? 그 사람이 알아들을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X22','kor',3,'u3',ARRAY['K3-2-u3-C15','K3-2-u3-C18']::text[],'차례를 나타내는 말을 일의 순서와 맞지 않게 쓰거나 꾸밈말로 여겨 아무 차례로 쓴다','먼저 → 다음으로 → 끝으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X23','kor',3,'u3',ARRAY['K3-2-u3-C16','K3-2-u3-C19']::text[],'찾아본 곳이 기억나지 않으면 그럴듯한 이름을 지어 적거나 출처 칸을 아무 말로 채운다','그 이름을 믿고 찾아간 친구는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X24','kor',3,'u3',ARRAY['K3-2-u3-C16']::text[],'내가 직접 해 본 방법에도 출처를 꼭 붙여야 한다고 여긴다','내가 해 본 일인가, 찾아본 것인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X25','kor',3,'u3',ARRAY['K3-2-u3-C17','K3-2-u3-C19']::text[],'처음·가운데·끝(첫째·둘째·셋째 문단)에 들어갈 내용을 엇갈리게 놓는다','처음 읽는 사람이 무엇부터 알아야 할까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X26','kor',3,'u3',ARRAY['K3-2-u3-C18']::text[],'쓴 글을 점검하는 일을 칸을 채우거나 점수를 매기는 일로 여긴다','고치려고 보는 거예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X27','kor',3,'u3',ARRAY['K3-2-u3-C18']::text[],'같은 일을 다른 방법으로 설명하면 하나는 틀린 글이라고 여긴다','차례와 까닭이 드러났나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X28','kor',3,'u3',ARRAY['K3-2-u3-C19']::text[],'사진·안내장처럼 자료의 종류가 다르면 가져온 곳을 적지 않아도 된다고 여긴다','종류가 달라도 가져온 곳은') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X29','kor',3,'u3',ARRAY['K3-2-u3-C20']::text[],'‘-데’와 ‘-대’를 ‘보니’가 붙었는지로 가르거나 바꾸어 쓴다','내가 겪었나, 남에게 들었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X30','kor',3,'u3',ARRAY['K3-2-u3-C21']::text[],'낱말 그물에서 떠오른 말과 떠오른 까닭을 엇갈리게 잇거나, 한 낱말에서 한 갈래로만 떠올려야 한다고 여긴다','그 말이 무엇을 가리키나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X31','kor',3,'u3',ARRAY['K3-2-u3-C1','K3-2-u3-C14']::text[],'설명하는 글을 읽는 사람이 따라 할 수 있게 알려 주는 글이 아니라 내 느낌이나 꾸민 이야기를 쓰는 글로 여긴다','읽는 사람이 따라 할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X32','kor',3,'u3',ARRAY['K3-2-u3-C6','K3-2-u3-C9']::text[],'「한 기관의 조사에 따르면」·「많은 사람이 그렇게 말한다」처럼 어느 곳인지 이름을 밝히지 않은 말도 출처가 있는 자료라고 여긴다','그 말을 보고 찾아갈 곳의 이름이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X33','kor',3,'u3',ARRAY['K3-2-u3-C6','K3-2-u3-C9']::text[],'사진·그림처럼 눈에 띄는 것만 활용한 자료로 여겨, 글 속에 인용된 조사 결과·규정 같은 자료와 그 출처는 찾지 않는다','「…에 따르면」으로 가져온 글 속 내용도 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X34','kor',3,'u3',ARRAY['K3-2-u3-C9','K3-2-u3-C7']::text[],'출처를 찾는 데만 매달려 글이 무엇을 설명하는지, 글의 주제와 내용은 살피지 않는다','이 글은 무엇을 설명하는 글이지?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X35','kor',3,'u3',ARRAY['K3-2-u3-C15','K3-2-u3-C18']::text[],'일의 순서나 방법을 설명할 때 중요한 단계를 빠뜨려도 읽는 사람이 알아서 할 수 있다고 여긴다','이 글만 보고 처음 해 보는 친구가 따라 할 수 있을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_basic#1','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C3',1,'blank','auto','『국어』 111쪽에 나온 말이에요. 「자료를 만든 사람이나 기관, 자료의 이름과 같은 내용이 쓰인 정보를 (     )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X03']::text[],false,'{"seq":1,"concept":"K3-2-u3-C3","difficulty":1,"kind":"blank","stem":"『국어』 111쪽에 나온 말이에요. 「자료를 만든 사람이나 기관, 자료의 이름과 같은 내용이 쓰인 정보를 (     )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"출처","correct":true},{"t":"제목","mis":"K3-2-u3-X03"},{"t":"글쓴이","mis":"K3-2-u3-X03"},{"t":"날짜","mis":"K3-2-u3-X03"}],"explanation":["자료가 어디에서 왔는지 알려 주는 정보를 출처라고 해요.","자료를 만든 사람이나 기관, 자료의 이름이 출처에 들어가요.","다른 사람이 만든 자료를 사용할 때에는 출처를 밝혀야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_basic#2','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C3',1,'mc','auto','「올바른 손 씻기」를 읽고 답해요. 매년 10월 15일은 어떤 일의 중요성을 알리는 날인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":2,"concept":"K3-2-u3-C3","difficulty":1,"kind":"mc","stem":"「올바른 손 씻기」를 읽고 답해요. 매년 10월 15일은 어떤 일의 중요성을 알리는 날인가요?","options":[{"t":"올바른 손 씻기","correct":true},{"t":"감기 예방 주사 맞기","mis":"K3-2-u3-X08"},{"t":"학급 신문 만들기","mis":"K3-2-u3-X08"},{"t":"비누 아껴 쓰기","mis":"K3-2-u3-X08"}],"explanation":["국제연합에서 10월 15일을 ‘세계 손 씻기의 날’로 정했어요.","이날은 올바른 손 씻기의 중요성을 알리는 날이에요.","감염병으로부터 어린이들을 보호하려고 만들었어요."],"asset":{"type":"passage","lines":["국제연합에서는 2008년에 10월 15일을 ‘세계 손 씻기의 날’로 정했습니다.","(간추림) 올바른 손 씻기의 중요성을 알리고 감염병으로부터 어린이를 보호하려는 날이다.","2023년 질병관리청의 ‘올바른 손 씻기’ 안내 자료에 따르면,","흐르는 물에 비누를 사용해 30초 이상 꼼꼼하게 손을 씻어야 한다고 합니다.","(간추림) 손을 제대로 씻으려면 여섯 단계를 거쳐야 한다.","[그림] 올바른 손 씻기 6단계 — 손바닥부터 손톱 밑까지 차례대로 그린 그림","■ 출처: 「올바른 손 씻기 6단계」, 질병관리청 누리집.","[글쓴이] 김이도 어린이 기자"],"title":"「올바른 손 씻기」 — 학급 신문, 『국어』 110~111쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_basic#3','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C4',1,'mc','auto','「올바른 손 씻기」에서 그림 자료 「올바른 손 씻기 6단계」의 출처는 어디에 나타나 있나요?',ARRAY['K3-2-u3-X04','K3-2-u3-X03']::text[],false,'{"seq":3,"concept":"K3-2-u3-C4","difficulty":1,"kind":"mc","stem":"「올바른 손 씻기」에서 그림 자료 「올바른 손 씻기 6단계」의 출처는 어디에 나타나 있나요?","options":[{"t":"그림 자료 바로 아래(■ 출처)","correct":true},{"t":"글의 제목 옆","mis":"K3-2-u3-X04"},{"t":"글쓴이 이름 뒤","mis":"K3-2-u3-X03"},{"t":"글의 맨 첫 문장","mis":"K3-2-u3-X04"}],"explanation":["그림 자료 아래에 「■ 출처: 「올바른 손 씻기 6단계」, 질병관리청 누리집.」이 있어요.","이처럼 자료 아래에 출처를 쓸 수 있어요.","김이도 어린이 기자는 글을 쓴 사람이지 출처가 아니에요."],"asset":{"type":"passage","lines":["국제연합에서는 2008년에 10월 15일을 ‘세계 손 씻기의 날’로 정했습니다.","(간추림) 올바른 손 씻기의 중요성을 알리고 감염병으로부터 어린이를 보호하려는 날이다.","2023년 질병관리청의 ‘올바른 손 씻기’ 안내 자료에 따르면,","흐르는 물에 비누를 사용해 30초 이상 꼼꼼하게 손을 씻어야 한다고 합니다.","(간추림) 손을 제대로 씻으려면 여섯 단계를 거쳐야 한다.","[그림] 올바른 손 씻기 6단계 — 손바닥부터 손톱 밑까지 차례대로 그린 그림","■ 출처: 「올바른 손 씻기 6단계」, 질병관리청 누리집.","[글쓴이] 김이도 어린이 기자"],"title":"「올바른 손 씻기」 — 학급 신문, 『국어』 110~111쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_basic#4','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C4',1,'sa','auto','「올바른 손 씻기」에서 「흐르는 물에 비누를 사용해 30초 이상 꼼꼼하게 손을 씻어야 한다」는 내용은 어느 기관의 안내 자료에서 가져왔나요? 기관 이름을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u3-C4","difficulty":1,"kind":"sa","stem":"「올바른 손 씻기」에서 「흐르는 물에 비누를 사용해 30초 이상 꼼꼼하게 손을 씻어야 한다」는 내용은 어느 기관의 안내 자료에서 가져왔나요? 기관 이름을 쓰세요.","answer":["질병관리청"],"explanation":["그 내용 바로 앞을 다시 읽어요.","「2023년 질병관리청의 ‘올바른 손 씻기’ 안내 자료에 따르면,」이라고 했어요.","본문 속에서 글로 출처를 밝힌 거예요."],"asset":{"type":"passage","lines":["국제연합에서는 2008년에 10월 15일을 ‘세계 손 씻기의 날’로 정했습니다.","(간추림) 올바른 손 씻기의 중요성을 알리고 감염병으로부터 어린이를 보호하려는 날이다.","2023년 질병관리청의 ‘올바른 손 씻기’ 안내 자료에 따르면,","흐르는 물에 비누를 사용해 30초 이상 꼼꼼하게 손을 씻어야 한다고 합니다.","(간추림) 손을 제대로 씻으려면 여섯 단계를 거쳐야 한다.","[그림] 올바른 손 씻기 6단계 — 손바닥부터 손톱 밑까지 차례대로 그린 그림","■ 출처: 「올바른 손 씻기 6단계」, 질병관리청 누리집.","[글쓴이] 김이도 어린이 기자"],"title":"「올바른 손 씻기」 — 학급 신문, 『국어』 110~111쪽"},"mis":"K3-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_basic#5','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C1',2,'mc','auto','『국어』 108쪽 여자아이의 글을 읽고 남자아이가 「‘그래서’가 어색한 것 같아.」라고 했어요. 왜 어색할까요?',ARRAY['K3-2-u3-X01','K3-2-u3-X16']::text[],false,'{"seq":5,"concept":"K3-2-u3-C1","difficulty":2,"kind":"mc","stem":"『국어』 108쪽 여자아이의 글을 읽고 남자아이가 「‘그래서’가 어색한 것 같아.」라고 했어요. 왜 어색할까요?","options":[{"t":"앞 문장이 뒤 문장의 까닭이 아니라 다음 차례를 잇는 자리이기 때문","correct":true},{"t":"문장이 너무 짧기 때문","mis":"K3-2-u3-X01"},{"t":"‘그래서’는 글의 맨 처음에만 쓰는 말이기 때문","mis":"K3-2-u3-X16"},{"t":"글씨를 작게 썼기 때문","mis":"K3-2-u3-X01"}],"explanation":["「색종이를 반으로 접었다 펼쳐 봐.」는 다음 문장의 까닭이 아니에요.","접는 차례가 이어지는 자리라서 ‘그다음에’ 같은 말이 어울려요.","설명하는 글은 일의 차례가 잘 드러나야 해요."],"asset":{"type":"passage","lines":["종이비행기 만드는 방법을 설명해 줄게.","먼저, 색종이를 반으로 접었다 펼쳐 봐.","그래서 접은 선을 따라 양쪽 날개를 똑같이 접어 봐. ……","마지막으로, 책에 나오지 않는 나만의 비법은","양쪽 날개를 점선을 따라 바깥쪽으로 접어서 날개 끝을 하늘로 향하게 하는 거야."],"title":"여자아이가 쓴 글 — 『국어』 108쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_basic#6','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C2',2,'mc','auto','『국어』 109쪽 2번이에요. 남자아이가 궁금해하는 것을 해결하려면 여자아이는 어떻게 해야 할까요?',ARRAY['K3-2-u3-X23','K3-2-u3-X07','K3-2-u3-X06']::text[],false,'{"seq":6,"concept":"K3-2-u3-C2","difficulty":2,"kind":"mc","stem":"『국어』 109쪽 2번이에요. 남자아이가 궁금해하는 것을 해결하려면 여자아이는 어떻게 해야 할까요?","options":[{"t":"보았던 책을 다시 찾아 확인하고, 어떤 책인지 밝힌다","correct":true},{"t":"기억나는 대로 그럴듯한 책 이름을 지어 적는다","mis":"K3-2-u3-X23"},{"t":"책에서 본 내용은 모두 빼고 쓴다","mis":"K3-2-u3-X07"},{"t":"모두 내가 생각해 낸 방법이라고 말한다","mis":"K3-2-u3-X06"}],"explanation":["남자아이는 어떤 책을 보고 쓴 글인지 궁금해해요.","기억이 안 나면 지어내지 말고 다시 찾아 확인해야 해요.","확인한 책을 밝히면 읽는 사람도 그 책을 찾아볼 수 있어요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"어떤 책을 보고 쓴 글이야?"},{"who":"여자아이","text":"기억이 잘 안 나는데……."},{"who":"남자아이","text":"종이비행기 접는 순서나 방법을 이해하기 어려워."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_basic#7','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C4',2,'match','auto','「올바른 손 씻기」에 나온 말이에요. 무엇인지 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u3-C4","difficulty":2,"kind":"match","stem":"「올바른 손 씻기」에 나온 말이에요. 무엇인지 알맞게 이으세요.","pairs":[{"l":"2023년 질병관리청의 ‘올바른 손 씻기’ 안내 자료에 따르면,","r":"본문에서 글로 출처를 밝혔다."},{"l":"■ 출처: 「올바른 손 씻기 6단계」, 질병관리청 누리집.","r":"자료 아래에 출처를 썼다."},{"l":"김이도 어린이 기자","r":"글을 쓴 사람이다."}],"mis":"K3-2-u3-X03","explanation":["「…에 따르면」은 본문 속에서 글로 출처를 밝힌 말이에요.","「■ 출처」는 그림 같은 자료 아래에 쓴 출처예요.","글을 쓴 사람은 출처가 아니에요."],"asset":{"type":"passage","lines":["국제연합에서는 2008년에 10월 15일을 ‘세계 손 씻기의 날’로 정했습니다.","(간추림) 올바른 손 씻기의 중요성을 알리고 감염병으로부터 어린이를 보호하려는 날이다.","2023년 질병관리청의 ‘올바른 손 씻기’ 안내 자료에 따르면,","흐르는 물에 비누를 사용해 30초 이상 꼼꼼하게 손을 씻어야 한다고 합니다.","(간추림) 손을 제대로 씻으려면 여섯 단계를 거쳐야 한다.","[그림] 올바른 손 씻기 6단계 — 손바닥부터 손톱 밑까지 차례대로 그린 그림","■ 출처: 「올바른 손 씻기 6단계」, 질병관리청 누리집.","[글쓴이] 김이도 어린이 기자"],"title":"「올바른 손 씻기」 — 학급 신문, 『국어』 110~111쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_basic#8','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C5',2,'mc','auto','『국어』 111쪽에 「다른 사람이 만든 자료를 사용할 때에는 출처를 밝혀야 해요.」라고 했어요. 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X05','K3-2-u3-X06','K3-2-u3-X10']::text[],false,'{"seq":8,"concept":"K3-2-u3-C5","difficulty":2,"kind":"mc","stem":"『국어』 111쪽에 「다른 사람이 만든 자료를 사용할 때에는 출처를 밝혀야 해요.」라고 했어요. 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"읽는 사람이 자료를 가져온 곳을 확인할 수 있고, 만든 사람의 것을 존중하는 일이 되기 때문","correct":true},{"t":"글을 길고 어려워 보이게 하려고","mis":"K3-2-u3-X05"},{"t":"내가 만든 자료처럼 보이게 하려고","mis":"K3-2-u3-X06"},{"t":"출처를 쓰면 글을 읽지 않아도 내용을 알 수 있어서","mis":"K3-2-u3-X10"}],"explanation":["출처가 있으면 읽는 사람이 그 자료를 직접 찾아 확인할 수 있어요.","출처를 밝히는 것은 자료를 만든 사람의 것을 존중하는 일이에요.","그래서 글을 더 믿을 수 있게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_basic#9','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C4',2,'mc','auto','「올바른 손 씻기」의 그림 자료를 보고 답해요. 질병관리청에서 제시한 손 씻기의 마지막 단계는 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":9,"concept":"K3-2-u3-C4","difficulty":2,"kind":"mc","stem":"「올바른 손 씻기」의 그림 자료를 보고 답해요. 질병관리청에서 제시한 손 씻기의 마지막 단계는 무엇인가요?","options":[{"t":"손톱 밑을 손바닥에 문지르며 마무리하기","correct":true},{"t":"손바닥을 마주 대고 문지르기","mis":"K3-2-u3-X08"},{"t":"엄지손가락을 돌리며 닦기","mis":"K3-2-u3-X08"},{"t":"손깍지를 끼고 손가락 사이 닦기","mis":"K3-2-u3-X08"}],"explanation":["그림 자료는 여섯 단계를 차례대로 보여 줘요.","여섯째 단계가 「손톱 밑을 손바닥에 문지르며 마무리」예요.","이 그림 자료의 출처는 질병관리청 누리집이에요."],"asset":{"type":"passage","lines":["① 손바닥 — 손바닥을 마주 대고 문지르기","② 손등 — 손등과 손바닥을 대고 문지르기","③ 손가락 사이 — 손깍지를 끼고 손가락 사이 닦기","④ 두 손 모아 — 손가락을 마주 잡고 비비기","⑤ 엄지손가락 — 엄지손가락을 돌리며 닦기","⑥ 손톱 밑 — 손톱 밑을 손바닥에 문지르며 마무리","■ 출처: 「올바른 손 씻기 6단계」, 질병관리청 누리집."],"title":"그림 자료 「올바른 손 씻기 6단계」를 글로 — 『국어』 111쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_basic#10','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C5',3,'mc','auto','두 글을 읽고 답해요. 어느 글이 더 믿음이 가고, 그 까닭은 무엇인가요?',ARRAY['K3-2-u3-X32','K3-2-u3-X08','K3-2-u3-X11']::text[],false,'{"seq":10,"concept":"K3-2-u3-C5","difficulty":3,"kind":"mc","stem":"두 글을 읽고 답해요. 어느 글이 더 믿음이 가고, 그 까닭은 무엇인가요?","options":[{"t":"㉯ — 세계보건기구라는 출처가 분명해서 내용을 확인해 볼 수 있다","correct":true},{"t":"㉮ — 요즘 많은 사람이 그렇게 말한다고 했으니까","mis":"K3-2-u3-X32"},{"t":"㉮ — 「모든 병이 낫는다」고 더 힘주어 말하니까","mis":"K3-2-u3-X08"},{"t":"둘 다 같다 — 출처는 글을 믿는 것과 상관없다","mis":"K3-2-u3-X11"}],"explanation":["㉮는 출처 없이 주장만 드러내서 내용을 모두 믿을 수 없어요.","「많은 사람이 말한다」는 어디인지 밝힌 출처가 아니에요.","㉯는 출처가 분명해서 믿음이 가는 글이에요."],"asset":{"type":"passage","lines":["㉮ 하루에 30분만 걸어도 모든 병이 낫고 기분이 좋아진다고 한다.","요즘 많은 사람이 걷기만 해도 건강해졌다는 말을 많이 한다.","걷는 것은 최고의 치료법이다.","㉯ 세계보건기구에 따르면, 하루 30분 이상 걷기 운동을 하면","심혈관 건강 개선에 효과가 있으며 고혈압 예방에도 도움이 된다고 한다."],"title":"같은 걷기 이야기, 두 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_challenge#1','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C2',2,'mc','auto','설명하는 글을 정확하게 쓰려면 다양한 자료가 필요해요. 자료를 얻는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X02','K3-2-u3-X06']::text[],false,'{"seq":1,"concept":"K3-2-u3-C2","difficulty":2,"kind":"mc","stem":"설명하는 글을 정확하게 쓰려면 다양한 자료가 필요해요. 자료를 얻는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"인터넷에서 찾기, 책에서 찾기, 잘 아는 사람에게 묻기","correct":true},{"t":"모르는 부분은 그럴듯하게 짐작해서 채우기","mis":"K3-2-u3-X02"},{"t":"친구가 쓴 글을 내 글처럼 옮겨 쓰기","mis":"K3-2-u3-X06"}],"explanation":["인터넷이나 그림책에서 정보를 얻을 수 있어요.","잘 아는 사람과 면담을 하면서 자료를 얻을 수도 있어요.","이렇게 자료의 출처는 여러 가지일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_challenge#2','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C3',2,'sa','auto','글 「우리나라의 섬들」에서 활용한 자료는 어느 기관의 자료인가요? 기관 이름을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u3-C3","difficulty":2,"kind":"sa","stem":"글 「우리나라의 섬들」에서 활용한 자료는 어느 기관의 자료인가요? 기관 이름을 쓰세요.","answer":["한국섬진흥원"],"explanation":["「한국섬진흥원 자료에 따르면」이라고 했어요.","그래프 아래에도 「■ 출처: 「2024년 국내 섬 현황」, 한국섬진흥원 누리집.」이 있어요.","자료를 만든 기관이 출처에 들어가요."],"asset":{"type":"passage","lines":["섬이란 사면이 물로 둘러싸인 육지예요.","한국섬진흥원 자료에 따르면 우리나라 섬의 개수는 3390개나 된다고 해요.","[그래프] 사람이 살고 있는 섬(유인섬) 480개 · 사람이 살지 않는 섬(무인섬) 2910개","[그래프 아래] 2024년 12월 기준","■ 출처: 「2024년 국내 섬 현황」, 한국섬진흥원 누리집."],"title":"글 「우리나라의 섬들」"},"mis":"K3-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_challenge#3','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C4',3,'mc','auto','글 「우리나라의 섬들」은 활용한 자료의 출처를 어느 곳에 나타내고 있나요?',ARRAY['K3-2-u3-X04','K3-2-u3-X09']::text[],false,'{"seq":3,"concept":"K3-2-u3-C4","difficulty":3,"kind":"mc","stem":"글 「우리나라의 섬들」은 활용한 자료의 출처를 어느 곳에 나타내고 있나요?","options":[{"t":"본문 속 글과 그래프 아래, 두 곳 모두","correct":true},{"t":"그래프 아래 한 곳뿐","mis":"K3-2-u3-X04"},{"t":"글의 제목 안","mis":"K3-2-u3-X04"},{"t":"출처를 밝히지 않았다","mis":"K3-2-u3-X09"}],"explanation":["본문에서 「한국섬진흥원 자료에 따르면」이라고 글로 밝혔어요.","그래프 아래에도 「■ 출처」로 밝혔어요.","출처는 본문 속에도, 자료 아래에도 나타낼 수 있어요."],"asset":{"type":"passage","lines":["섬이란 사면이 물로 둘러싸인 육지예요.","한국섬진흥원 자료에 따르면 우리나라 섬의 개수는 3390개나 된다고 해요.","[그래프] 사람이 살고 있는 섬(유인섬) 480개 · 사람이 살지 않는 섬(무인섬) 2910개","[그래프 아래] 2024년 12월 기준","■ 출처: 「2024년 국내 섬 현황」, 한국섬진흥원 누리집."],"title":"글 「우리나라의 섬들」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_challenge#4','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C3',3,'mc','auto','「올바른 손 씻기」에 나온 것 가운데 출처가 아닌 것은 무엇인가요?',ARRAY['K3-2-u3-X03']::text[],false,'{"seq":4,"concept":"K3-2-u3-C3","difficulty":3,"kind":"mc","stem":"「올바른 손 씻기」에 나온 것 가운데 출처가 아닌 것은 무엇인가요?","options":[{"t":"김이도 어린이 기자","correct":true},{"t":"질병관리청 누리집","mis":"K3-2-u3-X03"},{"t":"「올바른 손 씻기 6단계」","mis":"K3-2-u3-X03"},{"t":"2023년 질병관리청의 ‘올바른 손 씻기’ 안내 자료","mis":"K3-2-u3-X03"}],"explanation":["출처는 가져온 자료를 만든 곳이나 자료의 이름이에요.","질병관리청 안내 자료, 「올바른 손 씻기 6단계」, 질병관리청 누리집이 출처예요.","김이도 어린이 기자는 이 글을 쓴 사람이에요."],"asset":{"type":"passage","lines":["국제연합에서는 2008년에 10월 15일을 ‘세계 손 씻기의 날’로 정했습니다.","(간추림) 올바른 손 씻기의 중요성을 알리고 감염병으로부터 어린이를 보호하려는 날이다.","2023년 질병관리청의 ‘올바른 손 씻기’ 안내 자료에 따르면,","흐르는 물에 비누를 사용해 30초 이상 꼼꼼하게 손을 씻어야 한다고 합니다.","(간추림) 손을 제대로 씻으려면 여섯 단계를 거쳐야 한다.","[그림] 올바른 손 씻기 6단계 — 손바닥부터 손톱 밑까지 차례대로 그린 그림","■ 출처: 「올바른 손 씻기 6단계」, 질병관리청 누리집.","[글쓴이] 김이도 어린이 기자"],"title":"「올바른 손 씻기」 — 학급 신문, 『국어』 110~111쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_challenge#5','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C5',3,'error','auto','친구들이 출처를 밝히는 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X05','K3-2-u3-X13','K3-2-u3-X06']::text[],false,'{"seq":5,"concept":"K3-2-u3-C5","difficulty":3,"kind":"error","stem":"친구들이 출처를 밝히는 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"민호: 출처를 쓰면 글이 길어 보여서 더 잘 쓴 글 같아.","correct":true,"mis_target":"K3-2-u3-X05"},{"t":"서아: 읽는 사람이 믿을 만한 자료인지 살펴볼 수 있어.","mis":"K3-2-u3-X13"},{"t":"지후: 다른 사람이 만든 것을 존중하는 일이야.","mis":"K3-2-u3-X06"}],"explanation":["출처는 글을 길어 보이게 하려고 쓰는 것이 아니에요.","읽는 사람이 자료를 살펴볼 수 있게 해 줘요.","자료를 만든 사람을 존중하는 일이기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_challenge#6','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C1',3,'mc','auto','『국어』 109쪽 2번에서 남자아이가 「종이비행기 접는 순서나 방법을 이해하기 어려워.」라고 했어요. 여자아이가 글을 고칠 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X01','K3-2-u3-X31','K3-2-u3-X21']::text[],false,'{"seq":6,"concept":"K3-2-u3-C1","difficulty":3,"kind":"mc","stem":"『국어』 109쪽 2번에서 남자아이가 「종이비행기 접는 순서나 방법을 이해하기 어려워.」라고 했어요. 여자아이가 글을 고칠 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"글 앞부분에 준비물을 먼저 쓰고, 접는 차례를 한 단계씩 나누어 쓴다","correct":true},{"t":"글씨를 더 크게 쓴다","mis":"K3-2-u3-X01"},{"t":"비행기를 날렸던 느낌을 자세히 덧붙인다","mis":"K3-2-u3-X31"},{"t":"어려운 낱말을 더 넣어 멋있게 쓴다","mis":"K3-2-u3-X21"}],"explanation":["문장이 너무 길면 이해하기 어려워요.","글 앞부분에 준비물을 먼저 써 주면 알기 쉬워요.","읽는 사람이 따라 할 수 있게 차례를 나누어 써요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"어떤 책을 보고 쓴 글이야?"},{"who":"여자아이","text":"기억이 잘 안 나는데……."},{"who":"남자아이","text":"종이비행기 접는 순서나 방법을 이해하기 어려워."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_challenge#7','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C3',3,'mc','auto','『국어』 113쪽 신문 기사를 보고 답해요. 이 기사에서 학교 수 자료를 가져온 곳은 어디인가요?',ARRAY['K3-2-u3-X03']::text[],false,'{"seq":7,"concept":"K3-2-u3-C3","difficulty":3,"kind":"mc","stem":"『국어』 113쪽 신문 기사를 보고 답해요. 이 기사에서 학교 수 자료를 가져온 곳은 어디인가요?","options":[{"t":"교육부","correct":true},{"t":"기사를 실은 신문","mis":"K3-2-u3-X03"},{"t":"기사를 쓴 기자","mis":"K3-2-u3-X03"},{"t":"2025년","mis":"K3-2-u3-X03"}],"explanation":["「교육부의 ‘교육 기본 통계 조사’ 자료에 따르면」이라고 했어요.","자료를 만든 곳은 교육부예요.","신문 이름, 기자, 날짜는 자료를 가져온 곳이 아니에요."],"asset":{"type":"passage","lines":["[과학 잡지] 하늘다람쥐는 산림 파괴로 멸종 위기에 처해 있습니다.","■ 출처: 국립생태원 「하늘다람쥐」, 누리집.","[그래프] 우리나라의 섬 3390개 — 유인섬 480개, 무인섬 2910개","■ 출처: 「2024년 국내 섬 현황」, 한국섬진흥원 누리집.","[신문 기사] 2025년에 발표된 교육부의 ‘교육 기본 통계 조사’ 자료에 따르면,","전국에는 초등학교 6192개교, 중학교 3292개교 등이 있습니다."],"title":"출처를 본 경험 — 『국어』 113쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_challenge#8','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C5',4,'essay','teacher','글 ㉮를 읽은 사람이 내용을 모두 믿기 어려운 까닭을 쓰고, ㉮를 믿음이 가는 글로 고치려면 어떻게 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u3-C5","difficulty":4,"kind":"essay","stem":"글 ㉮를 읽은 사람이 내용을 모두 믿기 어려운 까닭을 쓰고, ㉮를 믿음이 가는 글로 고치려면 어떻게 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: ㉮는 「많은 사람이 말한다」고만 하고 어디에서 가져온 내용인지 출처가 없어서 믿기 어렵다. 걷기의 효과를 알려 주는 기관의 자료를 찾아 「…에 따르면」처럼 출처를 밝히고, 「모든 병이 낫는다」처럼 지나친 말은 확인한 내용으로 고친다.","scoring_points":["㉮에 출처가 없다는 점을 썼는가","출처를 밝혀 고치는 방법을 썼는가","확인한 내용으로 고쳐야 함을 썼는가"]},"explanation":["출처 없이 주장만 있는 글은 모두 믿기 어려워요.","자료를 가져온 곳을 밝히면 읽는 사람이 확인할 수 있어요.","㉯처럼 출처를 분명히 쓰면 믿음이 가는 글이 돼요."],"asset":{"type":"passage","lines":["㉮ 하루에 30분만 걸어도 모든 병이 낫고 기분이 좋아진다고 한다.","요즘 많은 사람이 걷기만 해도 건강해졌다는 말을 많이 한다.","걷는 것은 최고의 치료법이다.","㉯ 세계보건기구에 따르면, 하루 30분 이상 걷기 운동을 하면","심혈관 건강 개선에 효과가 있으며 고혈압 예방에도 도움이 된다고 한다."],"title":"같은 걷기 이야기, 두 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_challenge#9','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C4',4,'essay','teacher','『국어』 113쪽 4번처럼 평소에 출처를 본 경험을 떠올려 쓰세요. 어디에서 보았는지, 자료의 어느 곳에 있었는지, 어떤 모양으로 적혀 있었는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C4","difficulty":4,"kind":"essay","stem":"『국어』 113쪽 4번처럼 평소에 출처를 본 경험을 떠올려 쓰세요. 어디에서 보았는지, 자료의 어느 곳에 있었는지, 어떤 모양으로 적혀 있었는지 쓰세요.","answer_guide":{"answer":"예: 어린이 과학 잡지에서 동물 사진을 보았는데, 사진 아래쪽에 작은 글씨로 「■ 출처: ○○ 누리집.」이라고 적혀 있었다. 동영상에서도 화면 아래에 자료를 가져온 곳이 나온 적이 있다.","scoring_points":["출처를 본 곳(책·잡지·신문·동영상 등)을 썼는가","자료의 어느 곳에 있었는지 썼는가","어떤 모양으로 적혀 있었는지 썼는가"]},"explanation":["출처는 신문, 잡지, 책뿐 아니라 동영상에도 있어요.","자료 아래에 있기도 하고 본문 속 글에 있기도 해요.","자료의 형식에 상관없이 출처를 찾아볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L02_challenge#10','kor',3,2,'u3','L02','tb_g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C2',4,'essay','teacher','『국어』 108쪽 여자아이에게 조언하는 글을 쓰세요. 책에서 본 접는 방법과 「나만의 비법」을 어떻게 나누어 쓰면 좋을지, 책에서 본 내용의 출처는 어떻게 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C2","difficulty":4,"kind":"essay","stem":"『국어』 108쪽 여자아이에게 조언하는 글을 쓰세요. 책에서 본 접는 방법과 「나만의 비법」을 어떻게 나누어 쓰면 좋을지, 책에서 본 내용의 출처는 어떻게 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 책에서 본 접는 방법은 그 책을 다시 찾아 확인한 뒤 책 이름을 출처로 밝혀 줘. 나만의 비법은 네가 직접 해 본 방법이라고 따로 써 주면 읽는 사람이 무엇을 어디에서 가져왔는지 알 수 있어.","scoring_points":["책에서 본 내용은 확인해서 출처를 밝히라고 했는가","직접 해 본 방법은 따로 쓰라고 했는가","그렇게 하면 좋은 점을 썼는가"]},"explanation":["다른 사람이 만든 자료를 가져왔다면 출처를 밝혀요.","기억이 나지 않으면 지어내지 말고 다시 찾아 확인해요.","내가 직접 해 본 방법은 나의 방법이라고 밝히면 돼요."],"asset":{"type":"passage","lines":["종이비행기 만드는 방법을 설명해 줄게.","먼저, 색종이를 반으로 접었다 펼쳐 봐.","그래서 접은 선을 따라 양쪽 날개를 똑같이 접어 봐. ……","마지막으로, 책에 나오지 않는 나만의 비법은","양쪽 날개를 점선을 따라 바깥쪽으로 접어서 날개 끝을 하늘로 향하게 하는 거야."],"title":"여자아이가 쓴 글 — 『국어』 108쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_basic#1','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',1,'mc','auto','「자전거 안전모를 써요」에서 글쓴이의 의견으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":1,"concept":"K3-2-u3-C6","difficulty":1,"kind":"mc","stem":"「자전거 안전모를 써요」에서 글쓴이의 의견으로 알맞은 것은 무엇인가요?","options":[{"t":"우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타자","correct":true},{"t":"자전거는 위험하니 타지 말자","mis":"K3-2-u3-X08"},{"t":"자전거 경주를 하는 방법을 알려 주자","mis":"K3-2-u3-X08"},{"t":"안전모는 비 오는 날에만 쓰자","mis":"K3-2-u3-X08"}],"explanation":["이 글은 글쓴이의 의견이 드러난 주장하는 글이에요.","글의 끝에서 「안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다.」라고 했어요.","글쓴이는 자전거를 탈 때 꼭 안전모를 쓰자고 주장해요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_basic#2','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',1,'sa','auto','「자전거 안전모를 써요」에서 자료 ㉰의 출처를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u3-C6","difficulty":1,"kind":"sa","stem":"「자전거 안전모를 써요」에서 자료 ㉰의 출처를 쓰세요.","answer":["질병관리청"],"explanation":["㉰는 「2023년 질병관리청의 자료에 따르면」으로 시작해요.","자료를 가져온 곳은 질병관리청이에요.","본문 속 글로 출처를 밝힌 거예요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"},"mis":"K3-2-u3-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_basic#3','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',1,'ox','auto','자료 ㉮에 「한 기관의 조사에 따르면」이라고 했으니 ㉮는 출처가 있는 자료예요.',ARRAY['K3-2-u3-X32']::text[],false,'{"seq":3,"concept":"K3-2-u3-C6","difficulty":1,"kind":"ox","stem":"자료 ㉮에 「한 기관의 조사에 따르면」이라고 했으니 ㉮는 출처가 있는 자료예요.","answer":"X","reason_options":[{"t":"어느 기관인지 이름을 밝히지 않았으니 출처가 없는 자료예요.","correct":true},{"t":"「…에 따르면」이라는 말만 있으면 출처가 있는 거예요.","mis":"K3-2-u3-X32"}],"mis":"K3-2-u3-X32","explanation":["출처는 자료를 가져온 곳을 확인할 수 있게 해 주는 정보예요.","「한 기관」은 어디인지 알 수 없어요.","그래서 『국어』 117쪽 표에서 ㉮의 출처는 「없음」이에요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_basic#4','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',1,'mc','auto','「자전거 안전모를 써요」에서 자료 ㉯ 사진의 출처는 무엇인가요?',ARRAY['K3-2-u3-X09','K3-2-u3-X03']::text[],false,'{"seq":4,"concept":"K3-2-u3-C6","difficulty":1,"kind":"mc","stem":"「자전거 안전모를 써요」에서 자료 ㉯ 사진의 출처는 무엇인가요?","options":[{"t":"출처가 적혀 있지 않다","correct":true},{"t":"질병관리청","mis":"K3-2-u3-X09"},{"t":"서울특별시 자전거 누리 소통망","mis":"K3-2-u3-X09"},{"t":"사진에 나온 어린이","mis":"K3-2-u3-X03"}],"explanation":["㉯ 사진 아래에는 아무 글이 없어요.","자료가 있다고 해서 모두 출처가 있는 것은 아니에요.","사진이나 그림 자료도 출처가 있는지 꼭 확인해요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_basic#5','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',2,'match','auto','『국어』 116쪽 2번이에요. 「자전거 안전모를 써요」를 읽고 삼각기둥책에 정리한 내용을 알맞은 면과 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u3-C6","difficulty":2,"kind":"match","stem":"『국어』 116쪽 2번이에요. 「자전거 안전모를 써요」를 읽고 삼각기둥책에 정리한 내용을 알맞은 면과 이으세요.","pairs":[{"l":"우리 모두 안전모를 착용하는 습관을 들이자.","r":"글쓴이의 의견"},{"l":"안전모를 쓰면 두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다.","r":"새롭게 안 내용"},{"l":"자전거 안전모는 어떤 재료로 만들어질까?","r":"알고 싶은 내용"}],"mis":"K3-2-u3-X08","explanation":["글쓴이가 주장하는 것은 「글쓴이의 의견」이에요.","글을 읽고 처음 알게 된 사실은 「새롭게 안 내용」이에요.","더 찾아보고 싶은 것은 「알고 싶은 내용」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_basic#6','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C7',2,'mc','auto','『국어』 117쪽 3번 (2)예요. 「자료 (     )는 출처가 있기 때문에 글에서 활용한 자료가 믿을 만한지 확인할 수 있어.」 빈칸에 알맞은 것을 모두 고른 것은 무엇인가요?',ARRAY['K3-2-u3-X09','K3-2-u3-X32','K3-2-u3-X33']::text[],false,'{"seq":6,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"『국어』 117쪽 3번 (2)예요. 「자료 (     )는 출처가 있기 때문에 글에서 활용한 자료가 믿을 만한지 확인할 수 있어.」 빈칸에 알맞은 것을 모두 고른 것은 무엇인가요?","options":[{"t":"㉰, ㉱","correct":true},{"t":"㉮, ㉯","mis":"K3-2-u3-X09"},{"t":"㉮, ㉰","mis":"K3-2-u3-X32"},{"t":"㉯, ㉱","mis":"K3-2-u3-X33"}],"explanation":["㉰는 질병관리청, ㉱는 서울특별시 자전거 누리 소통망이 출처예요.","㉮는 「한 기관」이라 출처가 없고, ㉯ 사진도 출처가 없어요.","출처가 있으면 자료가 믿을 만한지 확인할 수 있어요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_basic#7','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C7',2,'blank','auto','『국어』 117쪽 3번 (2)예요. 「자료 ㉮, ㉯는 출처가 없기 때문에 자료를 가져온 곳에서 주제와 관련 있는 정보를 더 (     ).」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X10','K3-2-u3-X11']::text[],false,'{"seq":7,"concept":"K3-2-u3-C7","difficulty":2,"kind":"blank","stem":"『국어』 117쪽 3번 (2)예요. 「자료 ㉮, ㉯는 출처가 없기 때문에 자료를 가져온 곳에서 주제와 관련 있는 정보를 더 (     ).」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"찾아볼 수 없어","correct":true},{"t":"빨리 읽을 수 있어","mis":"K3-2-u3-X10"},{"t":"찾아볼 수 있어","mis":"K3-2-u3-X11"},{"t":"외울 수 있어","mis":"K3-2-u3-X10"}],"explanation":["출처가 있으면 그곳에 가서 정보를 더 찾아볼 수 있어요.","출처가 없으면 어디로 가야 할지 알 수 없어요.","이것이 출처가 없는 자료의 아쉬운 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_basic#8','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C8',2,'mc','auto','『국어』 117쪽 활용 질문처럼 「자료의 출처인 ‘질병관리청’은 어떤 곳일까요?」 하고 생각해 보았어요. 출처를 보고 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X14']::text[],false,'{"seq":8,"concept":"K3-2-u3-C8","difficulty":2,"kind":"mc","stem":"『국어』 117쪽 활용 질문처럼 「자료의 출처인 ‘질병관리청’은 어떤 곳일까요?」 하고 생각해 보았어요. 출처를 보고 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"출처가 어떤 곳인지 살펴보고, 알고 있던 것과 다른 내용은 없는지 생각하며 읽는다","correct":true},{"t":"출처가 있으니 더 생각하지 않고 그대로 믿는다","mis":"K3-2-u3-X12"},{"t":"출처가 있어도 거짓일 수 있으니 하나도 믿지 않는다","mis":"K3-2-u3-X13"},{"t":"출처의 이름이 길수록 더 믿을 만하다고 여긴다","mis":"K3-2-u3-X14"}],"explanation":["출처가 있다고 다 맞는 것도, 다 거짓인 것도 아니에요.","출처가 어떤 곳인지 살펴보며 읽어요.","알고 있던 것과 다른 내용이 있는지도 생각해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_basic#9','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C7',2,'mc','auto','「안전모의 부상 예방 효과에 대해 더 자세히 알아보려면 어떻게 해야 할까요?」에 알맞은 답은 무엇인가요?',ARRAY['K3-2-u3-X03','K3-2-u3-X33','K3-2-u3-X32']::text[],false,'{"seq":9,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"「안전모의 부상 예방 효과에 대해 더 자세히 알아보려면 어떻게 해야 할까요?」에 알맞은 답은 무엇인가요?","options":[{"t":"출처인 질병관리청의 자료를 찾아본다","correct":true},{"t":"글쓴이의 이름을 다시 읽는다","mis":"K3-2-u3-X03"},{"t":"㉯ 사진을 오래 들여다본다","mis":"K3-2-u3-X33"},{"t":"「한 기관」 누리집을 찾아간다","mis":"K3-2-u3-X32"}],"explanation":["부상 예방 효과는 ㉰ 자료에 나와요.","㉰의 출처는 질병관리청이에요.","출처에 가면 주제와 관련 있는 정보를 더 찾아볼 수 있어요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_basic#10','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',3,'error','auto','『국어』 117쪽 3번 (1) 표를 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K3-2-u3-X09','K3-2-u3-X32']::text[],false,'{"seq":10,"concept":"K3-2-u3-C6","difficulty":3,"kind":"error","stem":"『국어』 117쪽 3번 (1) 표를 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"나은: ㉱ 2-4-1 법칙 — 출처 없음","correct":true,"mis_target":"K3-2-u3-X09"},{"t":"도현: ㉮ 한 기관의 조사 — 출처 없음","mis":"K3-2-u3-X32"},{"t":"채원: ㉰ 질병관리청의 자료 — 질병관리청","mis":"K3-2-u3-X09"}],"explanation":["㉱ 그림 아래에 「■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.」이 있어요.","㉮는 어느 기관인지 밝히지 않아 출처가 없어요.","㉰의 출처는 질병관리청이에요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_challenge#1','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C6',2,'sa','auto','「자전거 안전모를 써요」의 2-4-1 법칙에서 「1 법칙」은 무엇을 손가락 한 개가 들어갈 만큼만 여유를 두고 조이는 것인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u3-C6","difficulty":2,"kind":"sa","stem":"「자전거 안전모를 써요」의 2-4-1 법칙에서 「1 법칙」은 무엇을 손가락 한 개가 들어갈 만큼만 여유를 두고 조이는 것인가요? 두 글자로 쓰세요.","answer":["턱 끈","턱끈"],"explanation":["2 법칙은 눈썹 위, 4 법칙은 귀 아래 끈이에요.","1 법칙은 「턱 끈은 손가락 한 개가 들어갈 만큼만 여유를 두고 조입니다.」예요.","안전모는 올바르게 쓰는 것이 중요해요."],"asset":{"type":"passage","lines":["(간추림) 넘어지면 바닥에 머리를 먼저 부딪치는 일이 많아 머리를 다치기 쉽다.","(간추림) 비나 눈이 오는 날, 흙길처럼 미끄러운 길에서는 효과가 더 크다.","(간추림) 2 법칙 — 눈썹 위에 손가락 두 개가 들어갈 만큼 여유, 이마가 덮이게","(간추림) 4 법칙 — 귀 아래 양쪽 손가락 두 개씩을 펼쳐 끈이 그 사이에","(간추림) 1 법칙 — 턱 끈은 손가락 한 개가 들어갈 만큼만 여유를 두고 조인다.","(간추림) 어린이는 어른보다 머리가 더 약해 안전모 착용이 더욱 중요하다."],"title":"「자전거 안전모를 써요」 가운데 — 『국어』 115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_challenge#2','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C7',2,'mc','auto','출처를 확인하며 글을 읽으면 좋은 점 두 가지를 바르게 묶은 것은 무엇인가요?',ARRAY['K3-2-u3-X10','K3-2-u3-X12']::text[],false,'{"seq":2,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"출처를 확인하며 글을 읽으면 좋은 점 두 가지를 바르게 묶은 것은 무엇인가요?","options":[{"t":"자료가 믿을 만한지 확인할 수 있고, 주제와 관련 있는 정보를 더 찾아볼 수 있다","correct":true},{"t":"글을 읽지 않아도 내용을 알 수 있고, 빨리 읽을 수 있다","mis":"K3-2-u3-X10"},{"t":"출처가 있는 자료는 모두 맞다고 믿을 수 있다","mis":"K3-2-u3-X12"}],"explanation":["출처를 보면 자료가 믿을 만한지 확인할 수 있어요.","자료를 가져온 곳에서 정보를 더 찾아볼 수 있어요.","출처가 있다고 무조건 믿거나 글을 안 읽어도 되는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_challenge#3','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C6',3,'mc','auto','한 친구가 「이 글에서 활용한 자료는 ㉯ 사진과 ㉱ 그림 두 개뿐이야.」라고 했어요. 이 친구가 놓친 것은 무엇인가요?',ARRAY['K3-2-u3-X09','K3-2-u3-X08','K3-2-u3-X32']::text[],false,'{"seq":3,"concept":"K3-2-u3-C6","difficulty":3,"kind":"mc","stem":"한 친구가 「이 글에서 활용한 자료는 ㉯ 사진과 ㉱ 그림 두 개뿐이야.」라고 했어요. 이 친구가 놓친 것은 무엇인가요?","options":[{"t":"「…에 따르면」으로 글 속에 가져온 ㉮와 ㉰도 활용한 자료라는 것","correct":true},{"t":"사진과 그림은 자료가 아니라는 것","mis":"K3-2-u3-X09"},{"t":"글쓴이의 의견도 자료라는 것","mis":"K3-2-u3-X08"},{"t":"출처가 없는 자료는 자료가 아니라는 것","mis":"K3-2-u3-X32"}],"explanation":["사진이나 그림처럼 눈에 띄는 것만 자료가 아니에요.","글 속에 인용한 조사 결과도 활용한 자료예요.","그래서 『국어』 117쪽 표에는 ㉮~㉱ 네 가지가 있어요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_challenge#4','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C8',3,'mc','auto','친구 둘이 말했어요. 「질병관리청 자료니까 하나도 생각해 볼 필요 없어.」 「출처가 있어도 다 거짓일 수 있으니 아무것도 믿지 말자.」 출처가 있는 자료를 읽는 태도로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X11']::text[],false,'{"seq":4,"concept":"K3-2-u3-C8","difficulty":3,"kind":"mc","stem":"친구 둘이 말했어요. 「질병관리청 자료니까 하나도 생각해 볼 필요 없어.」 「출처가 있어도 다 거짓일 수 있으니 아무것도 믿지 말자.」 출처가 있는 자료를 읽는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"출처가 어떤 곳인지 살펴보고, 내가 알던 것과 견주며 생각하며 읽는다","correct":true},{"t":"앞 친구의 말이 맞다","mis":"K3-2-u3-X12"},{"t":"뒤 친구의 말이 맞다","mis":"K3-2-u3-X13"},{"t":"출처는 보지 않고 글쓴이의 의견만 읽는다","mis":"K3-2-u3-X11"}],"explanation":["출처는 「무조건 믿어라」는 표가 아니에요.","그렇다고 출처가 있는 자료를 무조건 의심하는 것도 아니에요.","어떤 곳인지 살펴보고 생각하며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_challenge#5','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C7',3,'mc','auto','「㉮의 자료를 더 알아보고 싶은데 어떻게 할 수 있을까?」에 알맞은 답은 무엇인가요?',ARRAY['K3-2-u3-X32','K3-2-u3-X12','K3-2-u3-X33']::text[],false,'{"seq":5,"concept":"K3-2-u3-C7","difficulty":3,"kind":"mc","stem":"「㉮의 자료를 더 알아보고 싶은데 어떻게 할 수 있을까?」에 알맞은 답은 무엇인가요?","options":[{"t":"어느 기관인지 밝히지 않아서 찾아갈 곳을 알 수 없다","correct":true},{"t":"「한 기관」 누리집에 들어가 본다","mis":"K3-2-u3-X32"},{"t":"㉮에 숫자가 있으니 출처가 없어도 그대로 믿는다","mis":"K3-2-u3-X12"},{"t":"㉯ 사진을 보면 알 수 있다","mis":"K3-2-u3-X33"}],"explanation":["㉮는 「한 기관의 조사에 따르면」이라고만 했어요.","어느 기관인지 모르니 더 찾아볼 곳이 없어요.","출처가 없는 자료는 이런 아쉬움이 있어요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_challenge#6','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C6',3,'error','auto','『국어』 116쪽 2번 (2)처럼 묻고 답하기를 했어요. 「어린이에게 안전모 착용이 특히 더 중요한 까닭은 무엇일까?」에 답을 잘못한 친구는 누구인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":6,"concept":"K3-2-u3-C6","difficulty":3,"kind":"error","stem":"『국어』 116쪽 2번 (2)처럼 묻고 답하기를 했어요. 「어린이에게 안전모 착용이 특히 더 중요한 까닭은 무엇일까?」에 답을 잘못한 친구는 누구인가요?","options":[{"t":"서진: 어린이는 자전거를 더 빨리 타기 때문이야.","correct":true,"mis_target":"K3-2-u3-X08"},{"t":"유나: 어린이는 어른보다 머리가 더 약하기 때문이야.","mis":"K3-2-u3-X08"},{"t":"준우: 넘어지면 바닥에 머리를 먼저 부딪치는 일이 많아서 머리를 다치기 쉽기 때문이야.","mis":"K3-2-u3-X08"}],"explanation":["글에서 「어린이는 어른보다 머리가 더 약하기 때문에」라고 했어요.","넘어지면 머리를 먼저 부딪치는 일이 많다고도 했어요.","글에 없는 내용으로 답하지 않아요."],"asset":{"type":"passage","lines":["(간추림) 넘어지면 바닥에 머리를 먼저 부딪치는 일이 많아 머리를 다치기 쉽다.","(간추림) 비나 눈이 오는 날, 흙길처럼 미끄러운 길에서는 효과가 더 크다.","(간추림) 2 법칙 — 눈썹 위에 손가락 두 개가 들어갈 만큼 여유, 이마가 덮이게","(간추림) 4 법칙 — 귀 아래 양쪽 손가락 두 개씩을 펼쳐 끈이 그 사이에","(간추림) 1 법칙 — 턱 끈은 손가락 한 개가 들어갈 만큼만 여유를 두고 조인다.","(간추림) 어린이는 어른보다 머리가 더 약해 안전모 착용이 더욱 중요하다."],"title":"「자전거 안전모를 써요」 가운데 — 『국어』 115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_challenge#7','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C6',3,'mc','auto','㉰와 ㉱는 출처를 밝힌 방법이 어떻게 다른가요?',ARRAY['K3-2-u3-X04','K3-2-u3-X09']::text[],false,'{"seq":7,"concept":"K3-2-u3-C6","difficulty":3,"kind":"mc","stem":"㉰와 ㉱는 출처를 밝힌 방법이 어떻게 다른가요?","options":[{"t":"㉰는 문장 안에 「…에 따르면」으로, ㉱는 그림 아래에 「■ 출처」로 밝혔다","correct":true},{"t":"둘 다 그림 아래에 밝혔다","mis":"K3-2-u3-X04"},{"t":"㉰만 출처가 있고 ㉱는 없다","mis":"K3-2-u3-X09"},{"t":"㉰는 그림 아래에, ㉱는 문장 안에 밝혔다","mis":"K3-2-u3-X04"}],"explanation":["㉰는 「2023년 질병관리청의 자료에 따르면」이라고 문장 속에 썼어요.","㉱는 2-4-1 법칙 그림 아래에 「■ 출처」를 썼어요.","출처는 자료에 따라 여러 방법으로 밝혀요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_challenge#8','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C6',4,'essay','teacher','「자전거 안전모를 써요」를 읽고 삼각기둥책의 세 면(글쓴이의 의견 · 새롭게 안 내용 · 알고 싶은 내용)을 채워 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u3-C6","difficulty":4,"kind":"essay","stem":"「자전거 안전모를 써요」를 읽고 삼각기둥책의 세 면(글쓴이의 의견 · 새롭게 안 내용 · 알고 싶은 내용)을 채워 쓰세요.","answer_guide":{"answer":"예: 글쓴이의 의견 — 우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 탈 수 있도록 노력하자. 새롭게 안 내용 — 안전모를 올바르게 쓰는 ‘2-4-1 법칙’이 있다. 알고 싶은 내용 — 자전거를 탈 때 조심해야 할 점은 또 무엇이 있을까?","scoring_points":["글쓴이의 의견을 바르게 찾았는가","글에서 새롭게 안 내용을 썼는가","더 알고 싶은 내용을 질문으로 썼는가"]},"explanation":["삼각기둥책은 세 면에 나누어 정리해요.","의견은 글쓴이가 주장하는 것, 새롭게 안 내용은 글에서 처음 안 사실이에요.","알고 싶은 내용은 출처를 찾아가 더 알아볼 수 있어요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_challenge#9','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C7',4,'essay','teacher','자료 ㉮를 출처가 있는 자료로 고치려면 어떻게 해야 하는지 쓰고, 그렇게 고치면 읽는 사람에게 어떤 점이 좋은지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C7","difficulty":4,"kind":"essay","stem":"자료 ㉮를 출처가 있는 자료로 고치려면 어떻게 해야 하는지 쓰고, 그렇게 고치면 읽는 사람에게 어떤 점이 좋은지 쓰세요.","answer_guide":{"answer":"예: 「한 기관」이라고 쓰지 말고 조사를 한 기관의 이름을 밝혀 「○○의 조사에 따르면」이라고 쓴다. 그러면 읽는 사람이 그 자료가 믿을 만한지 확인할 수 있고, 그 기관에서 안전모에 대한 정보를 더 찾아볼 수 있다.","scoring_points":["조사한 기관의 이름을 밝혀야 한다고 썼는가","믿을 만한지 확인할 수 있다는 점을 썼는가","정보를 더 찾아볼 수 있다는 점을 썼는가"]},"explanation":["출처는 어디에서 가져왔는지 이름이 있어야 해요.","이름이 있으면 그 자료를 확인할 수 있어요.","그곳에서 더 많은 정보를 찾아볼 수도 있어요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L03_challenge#10','kor',3,2,'u3','L03','tb_g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C8',4,'essay','teacher','㉱의 출처 「서울특별시 자전거 누리 소통망」을 보고 더 알아보는 계획을 쓰세요. 무엇이 궁금한지, 어디에서 어떻게 찾아볼지, 찾은 내용을 읽을 때 무엇을 생각할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C8","difficulty":4,"kind":"essay","stem":"㉱의 출처 「서울특별시 자전거 누리 소통망」을 보고 더 알아보는 계획을 쓰세요. 무엇이 궁금한지, 어디에서 어떻게 찾아볼지, 찾은 내용을 읽을 때 무엇을 생각할지 쓰세요.","answer_guide":{"answer":"예: 안전모를 쓰는 방법을 영상으로 더 보고 싶다. 서울특별시 자전거 누리 소통망에 들어가 안전모 영상이나 사진을 찾아본다. 찾은 내용이 글의 내용과 같은지, 내가 알던 것과 다른 점은 없는지 생각하며 읽는다.","scoring_points":["궁금한 점을 썼는가","출처를 활용해 찾아볼 방법을 썼는가","생각하며 읽는 태도를 썼는가"]},"explanation":["출처를 보면 주제와 관련 있는 정보를 더 찾아볼 곳을 알 수 있어요.","찾은 자료도 그대로 믿기보다 살펴보며 읽어요.","알고 있던 것과 견주어 보면 더 깊이 이해할 수 있어요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_basic#1','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',1,'sa','auto','「손끝으로 읽는 여섯 개의 점」을 읽고 답해요. 한글 점자의 날은 언제인가요?','{}'::text[],false,'{"seq":1,"concept":"K3-2-u3-C9","difficulty":1,"kind":"sa","stem":"「손끝으로 읽는 여섯 개의 점」을 읽고 답해요. 한글 점자의 날은 언제인가요?","answer":["11월 4일","11월4일","11월 4일입니다"],"explanation":["「그렇다면 11월 4일은 무슨 날일까요?」 하고 물었어요.","1926년 11월 4일에 한글 점자를 만들어 반포했어요.","그래서 11월 4일이 한글 점자의 날이에요."],"asset":{"type":"passage","lines":["10월 9일은 한글날입니다.","그렇다면 11월 4일은 무슨 날일까요?","11월 4일은 바로 한글 점자의 날입니다.","(간추림) 1926년 11월 4일, 송암 박두성 선생이 한글 점자를 만들어 반포했다.","(간추림) 시각 장애인을 위한 이 점자는 훈민정음의 원리를 따라 만들었다.","(간추림) 그래서 시각 장애인을 뜻하는 한자를 넣어 ‘훈맹정음’이라고도 부른다.","[그림] 훈맹정음 책","■ 출처: 「훈맹정음」, 국립한글박물관 누리집."],"title":"「손끝으로 읽는 여섯 개의 점」 앞부분 — 『국어』 119쪽"},"mis":"K3-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_basic#2','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',1,'mc','auto','훈맹정음을 만든 사람은 누구인가요?',ARRAY['K3-2-u3-X08','K3-2-u3-X03']::text[],false,'{"seq":2,"concept":"K3-2-u3-C9","difficulty":1,"kind":"mc","stem":"훈맹정음을 만든 사람은 누구인가요?","options":[{"t":"송암 박두성 선생","correct":true},{"t":"세종 대왕","mis":"K3-2-u3-X08"},{"t":"국립한글박물관","mis":"K3-2-u3-X03"},{"t":"문화체육관광부","mis":"K3-2-u3-X03"}],"explanation":["「송암 박두성 선생이 시각 장애인을 위한 한글 점자를 만들어」라고 했어요.","세종 대왕은 훈민정음을 만들었어요.","국립한글박물관은 그림 자료의 출처예요."],"asset":{"type":"passage","lines":["10월 9일은 한글날입니다.","그렇다면 11월 4일은 무슨 날일까요?","11월 4일은 바로 한글 점자의 날입니다.","(간추림) 1926년 11월 4일, 송암 박두성 선생이 한글 점자를 만들어 반포했다.","(간추림) 시각 장애인을 위한 이 점자는 훈민정음의 원리를 따라 만들었다.","(간추림) 그래서 시각 장애인을 뜻하는 한자를 넣어 ‘훈맹정음’이라고도 부른다.","[그림] 훈맹정음 책","■ 출처: 「훈맹정음」, 국립한글박물관 누리집."],"title":"「손끝으로 읽는 여섯 개의 점」 앞부분 — 『국어』 119쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_basic#3','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C10',1,'blank','auto','『국어』 121쪽 낱말 알기예요. 「성질이나 종류에 따라 갈라놓음.」에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u3-X15']::text[],false,'{"seq":3,"concept":"K3-2-u3-C10","difficulty":1,"kind":"blank","stem":"『국어』 121쪽 낱말 알기예요. 「성질이나 종류에 따라 갈라놓음.」에 알맞은 낱말은 무엇인가요?","options":[{"t":"구별","correct":true},{"t":"동일","mis":"K3-2-u3-X15"},{"t":"구성","mis":"K3-2-u3-X15"}],"explanation":["점의 개수와 위치로 어떤 글자인지 갈라놓을 수 있어요.","이렇게 갈라놓는 것을 「구별」이라고 해요.","낱말이 쓰인 문장에 넣어 보면 뜻을 확인할 수 있어요."],"asset":{"type":"passage","lines":["보기: 구별 · 동일 · 구성","㉠ 성질이나 종류에 따라 갈라놓음.","㉡ 몇 가지 부분을 모아서 일정한 전체를 짜 이룸.","㉢ 어떤 것과 비교하여 똑같음."],"title":"낱말 알기 — 『국어』 121쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_basic#4','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',1,'mc','auto','점자는 보통 몇 개의 점으로 이루어져 있나요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":4,"concept":"K3-2-u3-C9","difficulty":1,"kind":"mc","stem":"점자는 보통 몇 개의 점으로 이루어져 있나요?","options":[{"t":"세로로 세 개, 가로로 두 개, 모두 여섯 개","correct":true},{"t":"세로로 두 개, 가로로 두 개, 모두 네 개","mis":"K3-2-u3-X08"},{"t":"가로로 세 개, 세로로 세 개, 모두 아홉 개","mis":"K3-2-u3-X08"},{"t":"점의 개수는 글자마다 정해져 있지 않다","mis":"K3-2-u3-X08"}],"explanation":["글의 제목도 「손끝으로 읽는 여섯 개의 점」이에요.","세로로 세 개, 가로로 두 개예요.","점의 개수와 위치로 글자를 구별해요."],"asset":{"type":"passage","lines":["점자는 손가락으로 만져서 읽는 글자입니다.","(간추림) 세로로 세 개, 가로로 두 개, 모두 여섯 개의 점으로 이루어진다.","(간추림) 왼쪽 위에서 아래로 1·2·3점, 오른쪽 위에서 아래로 4·5·6점이다.","(간추림) 승강기 층 버튼에 있는 작은 점들이 바로 숫자 점자다.","문화체육관광부의 『한국 점자 규정』에 따르면, 숫자를 점자로 쓸 때에는","숫자가 시작된다는 표시인 ‘수표’를 먼저 써야 합니다.","[그림] 점자 일람표 — 수표와 숫자 1~0","■ 출처: 「점자 일람표」, 문화체육관광부 누리집."],"title":"「손끝으로 읽는 여섯 개의 점」 가운데 — 『국어』 120쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_basic#5','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',2,'mc','auto','숫자를 점자로 쓸 때 먼저 써야 하는 기호와 그 내용의 출처를 바르게 묶은 것은 무엇인가요?',ARRAY['K3-2-u3-X09','K3-2-u3-X08']::text[],false,'{"seq":5,"concept":"K3-2-u3-C9","difficulty":2,"kind":"mc","stem":"숫자를 점자로 쓸 때 먼저 써야 하는 기호와 그 내용의 출처를 바르게 묶은 것은 무엇인가요?","options":[{"t":"수표 — 문화체육관광부의 『한국 점자 규정』","correct":true},{"t":"수표 — 국립한글박물관 누리집","mis":"K3-2-u3-X09"},{"t":"1점 — 문화체육관광부의 『한국 점자 규정』","mis":"K3-2-u3-X08"},{"t":"6점 — 출처 없이 글쓴이가 정한 것","mis":"K3-2-u3-X09"}],"explanation":["숫자가 시작된다는 표시인 ‘수표’를 먼저 써요.","「문화체육관광부의 『한국 점자 규정』에 따르면」이라고 했어요.","내용과 출처를 함께 확인하며 읽어요."],"asset":{"type":"passage","lines":["점자는 손가락으로 만져서 읽는 글자입니다.","(간추림) 세로로 세 개, 가로로 두 개, 모두 여섯 개의 점으로 이루어진다.","(간추림) 왼쪽 위에서 아래로 1·2·3점, 오른쪽 위에서 아래로 4·5·6점이다.","(간추림) 승강기 층 버튼에 있는 작은 점들이 바로 숫자 점자다.","문화체육관광부의 『한국 점자 규정』에 따르면, 숫자를 점자로 쓸 때에는","숫자가 시작된다는 표시인 ‘수표’를 먼저 써야 합니다.","[그림] 점자 일람표 — 수표와 숫자 1~0","■ 출처: 「점자 일람표」, 문화체육관광부 누리집."],"title":"「손끝으로 읽는 여섯 개의 점」 가운데 — 『국어』 120쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_basic#6','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',2,'match','auto','『국어』 122쪽 (1)이에요. 「손끝으로 읽는 여섯 개의 점」에서 활용한 자료나 내용과 그 출처를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u3-C9","difficulty":2,"kind":"match","stem":"『국어』 122쪽 (1)이에요. 「손끝으로 읽는 여섯 개의 점」에서 활용한 자료나 내용과 그 출처를 알맞게 이으세요.","pairs":[{"l":"훈맹정음 그림 자료","r":"「훈맹정음」, 국립한글박물관 누리집"},{"l":"숫자를 점자로 쓸 때 수표를 먼저 쓴다는 내용","r":"문화체육관광부의 『한국 점자 규정』"},{"l":"점자 일람표","r":"「점자 일람표」, 문화체육관광부 누리집"}],"mis":"K3-2-u3-X09","explanation":["그림 자료 아래 「■ 출처」를 찾아요.","본문 속 「…에 따르면」 앞에 있는 말도 출처예요.","밑줄 같은 표시가 없어도 스스로 출처를 찾아 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_basic#7','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C11',2,'mc','auto','『국어』 122쪽 (2)예요. 「손끝으로 읽는 여섯 개의 점」에서 활용한 자료의 출처가 적절한지 확인하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X14','K3-2-u3-X12','K3-2-u3-X13']::text[],false,'{"seq":7,"concept":"K3-2-u3-C11","difficulty":2,"kind":"mc","stem":"『국어』 122쪽 (2)예요. 「손끝으로 읽는 여섯 개의 점」에서 활용한 자료의 출처가 적절한지 확인하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"문화체육관광부 누리집에 직접 들어가서 그 자료가 있는지 확인한다","correct":true},{"t":"출처의 이름이 길고 어려우면 믿을 만하다고 여긴다","mis":"K3-2-u3-X14"},{"t":"출처가 적혀 있으니 확인하지 않고 그대로 믿는다","mis":"K3-2-u3-X12"},{"t":"출처가 적혀 있으니 거짓이라고 여긴다","mis":"K3-2-u3-X13"}],"explanation":["출처의 누리집에 직접 들어가 볼 수 있어요.","국립한글박물관과 문화체육관광부가 어떤 기관인지 확인할 수도 있어요.","이름이 길다고 믿을 만한 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_basic#8','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C10',2,'blank','auto','「나라마다 사용하는 점자는 조금씩 다르지만 숫자 점자는 거의 (     )합니다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u3-X15']::text[],false,'{"seq":8,"concept":"K3-2-u3-C10","difficulty":2,"kind":"blank","stem":"「나라마다 사용하는 점자는 조금씩 다르지만 숫자 점자는 거의 (     )합니다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"동일","correct":true},{"t":"구별","mis":"K3-2-u3-X15"},{"t":"구성","mis":"K3-2-u3-X15"}],"explanation":["「동일」은 어떤 것과 비교하여 똑같음이라는 뜻이에요.","나라마다 숫자 점자는 거의 똑같다는 말이에요.","문장에 넣어 읽어 보면 어울리는 낱말을 알 수 있어요."],"asset":{"type":"passage","lines":["보기: 구별 · 동일 · 구성","㉠ 성질이나 종류에 따라 갈라놓음.","㉡ 몇 가지 부분을 모아서 일정한 전체를 짜 이룸.","㉢ 어떤 것과 비교하여 똑같음."],"title":"낱말 알기 — 『국어』 121쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_basic#9','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',2,'ox','auto','「손끝으로 읽는 여섯 개의 점」은 점자에 대한 지식이나 정보를 전달하려고 쓴 설명하는 글이에요.',ARRAY['K3-2-u3-X34']::text[],false,'{"seq":9,"concept":"K3-2-u3-C9","difficulty":2,"kind":"ox","stem":"「손끝으로 읽는 여섯 개의 점」은 점자에 대한 지식이나 정보를 전달하려고 쓴 설명하는 글이에요.","answer":"O","reason_options":[{"t":"점자에 대한 정보를 처음-가운데-끝으로 짜서 전하는 설명하는 글이에요.","correct":true},{"t":"출처가 많이 나오니 출처를 알려 주려고 쓴 글이에요.","mis":"K3-2-u3-X34"}],"mis":"K3-2-u3-X34","explanation":["설명하는 글은 지식이나 정보를 전달하려고 써요.","이 글은 한글 점자의 날, 점자의 짜임, 숫자 점자를 설명해요.","출처를 확인하면서 글의 내용도 함께 이해해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_basic#10','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',3,'mc','auto','『국어』 121쪽 (3)이에요. 생활 속 우리 주변에서 점자가 필요한 까닭은 무엇인가요?',ARRAY['K3-2-u3-X08','K3-2-u3-X34']::text[],false,'{"seq":10,"concept":"K3-2-u3-C9","difficulty":3,"kind":"mc","stem":"『국어』 121쪽 (3)이에요. 생활 속 우리 주변에서 점자가 필요한 까닭은 무엇인가요?","options":[{"t":"점자는 시각 장애인과 세상을 이어 주는 소중한 문자이기 때문","correct":true},{"t":"점자는 모양이 예뻐서 꾸밈으로 쓰기 좋기 때문","mis":"K3-2-u3-X08"},{"t":"출처가 분명한 문자이기 때문","mis":"K3-2-u3-X34"},{"t":"숫자 점자는 나라마다 모두 다르기 때문","mis":"K3-2-u3-X08"}],"explanation":["글의 끝부분을 다시 읽어요.","「시각 장애인과 세상을 이어 주는 소중한 문자입니다.」라고 했어요.","그래서 점자가 없는 곳을 찾아보자고 했어요."],"asset":{"type":"passage","lines":["우리가 평소에 그냥 지나쳤던 작은 점자는","시각 장애인과 세상을 이어 주는 소중한 문자입니다.","(간추림) 꼭 필요해 보이지만 아직도 점자가 없는 곳이 있는지 찾아보자."],"title":"「손끝으로 읽는 여섯 개의 점」 끝부분 — 『국어』 120쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_challenge#1','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C10',2,'blank','auto','「점자는 여섯 개의 점으로 (     )되어 있습니다.」 「몇 가지 부분을 모아서 일정한 전체를 짜 이룸.」이라는 뜻의 낱말을 빈칸에 넣으세요.',ARRAY['K3-2-u3-X15']::text[],false,'{"seq":1,"concept":"K3-2-u3-C10","difficulty":2,"kind":"blank","stem":"「점자는 여섯 개의 점으로 (     )되어 있습니다.」 「몇 가지 부분을 모아서 일정한 전체를 짜 이룸.」이라는 뜻의 낱말을 빈칸에 넣으세요.","options":[{"t":"구성","correct":true},{"t":"구별","mis":"K3-2-u3-X15"},{"t":"동일","mis":"K3-2-u3-X15"}],"explanation":["여섯 개의 점이 모여 한 칸을 짜 이루어요.","이렇게 짜 이루는 것을 「구성」이라고 해요.","낱말의 뜻과 문장이 어울리는지 확인해요."],"asset":{"type":"passage","lines":["보기: 구별 · 동일 · 구성","㉠ 성질이나 종류에 따라 갈라놓음.","㉡ 몇 가지 부분을 모아서 일정한 전체를 짜 이룸.","㉢ 어떤 것과 비교하여 똑같음."],"title":"낱말 알기 — 『국어』 121쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_challenge#2','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C9',2,'sa','auto','한글 점자를 ‘훈맹정음’이라고도 부르는 까닭을 생각해요. ‘훈민정음’에 시각 장애인을 뜻하는 한자 하나를 넣었어요. 그 한자는 무엇인가요?','{}'::text[],false,'{"seq":2,"concept":"K3-2-u3-C9","difficulty":2,"kind":"sa","stem":"한글 점자를 ‘훈맹정음’이라고도 부르는 까닭을 생각해요. ‘훈민정음’에 시각 장애인을 뜻하는 한자 하나를 넣었어요. 그 한자는 무엇인가요?","answer":["맹","‘맹’"],"explanation":["훈맹정음은 훈민정음의 원리를 따라 만들었어요.","‘훈민정음’에 시각 장애인을 뜻하는 한자 ‘맹’을 넣었어요.","그래서 ‘훈맹정음’이라고도 불러요."],"asset":{"type":"passage","lines":["10월 9일은 한글날입니다.","그렇다면 11월 4일은 무슨 날일까요?","11월 4일은 바로 한글 점자의 날입니다.","(간추림) 1926년 11월 4일, 송암 박두성 선생이 한글 점자를 만들어 반포했다.","(간추림) 시각 장애인을 위한 이 점자는 훈민정음의 원리를 따라 만들었다.","(간추림) 그래서 시각 장애인을 뜻하는 한자를 넣어 ‘훈맹정음’이라고도 부른다.","[그림] 훈맹정음 책","■ 출처: 「훈맹정음」, 국립한글박물관 누리집."],"title":"「손끝으로 읽는 여섯 개의 점」 앞부분 — 『국어』 119쪽"},"mis":"K3-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_challenge#3','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C9',3,'mc','auto','숫자 점자에서 수표는 어떤 역할을 하나요?',ARRAY['K3-2-u3-X08','K3-2-u3-X03']::text[],false,'{"seq":3,"concept":"K3-2-u3-C9","difficulty":3,"kind":"mc","stem":"숫자 점자에서 수표는 어떤 역할을 하나요?","options":[{"t":"뒤에 오는 글자들을 숫자로 읽으라고 알려 준다","correct":true},{"t":"문장이 끝났다는 것을 알려 준다","mis":"K3-2-u3-X08"},{"t":"자료의 출처를 밝혀 준다","mis":"K3-2-u3-X03"},{"t":"점자 한 칸을 둘로 나누어 준다","mis":"K3-2-u3-X08"}],"explanation":["수표는 숫자가 시작된다는 표시예요.","「수표가 있으면 그 뒤의 글자들은 숫자로 읽으면 됩니다.」라고 했어요.","승강기 층 버튼의 숫자 점자에도 쓰여요."],"asset":{"type":"passage","lines":["점자는 손가락으로 만져서 읽는 글자입니다.","(간추림) 세로로 세 개, 가로로 두 개, 모두 여섯 개의 점으로 이루어진다.","(간추림) 왼쪽 위에서 아래로 1·2·3점, 오른쪽 위에서 아래로 4·5·6점이다.","(간추림) 승강기 층 버튼에 있는 작은 점들이 바로 숫자 점자다.","문화체육관광부의 『한국 점자 규정』에 따르면, 숫자를 점자로 쓸 때에는","숫자가 시작된다는 표시인 ‘수표’를 먼저 써야 합니다.","[그림] 점자 일람표 — 수표와 숫자 1~0","■ 출처: 「점자 일람표」, 문화체육관광부 누리집."],"title":"「손끝으로 읽는 여섯 개의 점」 가운데 — 『국어』 120쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_challenge#4','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C11',3,'error','auto','『국어』 123쪽처럼 출처가 적절한지 확인하는 방법을 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X14','K3-2-u3-X12']::text[],false,'{"seq":4,"concept":"K3-2-u3-C11","difficulty":3,"kind":"error","stem":"『국어』 123쪽처럼 출처가 적절한지 확인하는 방법을 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태오: 문화체육관광부는 이름이 길고 멋있으니 확인하지 않아도 돼.","correct":true,"mis_target":"K3-2-u3-X14"},{"t":"지아: 국립한글박물관과 문화체육관광부가 어떤 기관인지 확인해야 해.","mis":"K3-2-u3-X14"},{"t":"로운: 누리집에 직접 들어가서 자료가 있는지 확인해 볼 수 있어.","mis":"K3-2-u3-X12"}],"explanation":["이름이 길거나 멋있다고 믿을 만한 것은 아니에요.","어떤 기관인지 알아보고, 누리집에 직접 들어가 확인해요.","자료를 함부로 믿지 않고 생각해 보는 자세가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_challenge#5','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C9',3,'mc','auto','한 친구가 출처에만 밑줄을 그으며 다 읽었는데, 「이 글은 무엇을 설명하는 글인가요?」라는 물음에 답하지 못했어요. 이 친구에게 필요한 것은 무엇인가요?',ARRAY['K3-2-u3-X34','K3-2-u3-X14','K3-2-u3-X33']::text[],false,'{"seq":5,"concept":"K3-2-u3-C9","difficulty":3,"kind":"mc","stem":"한 친구가 출처에만 밑줄을 그으며 다 읽었는데, 「이 글은 무엇을 설명하는 글인가요?」라는 물음에 답하지 못했어요. 이 친구에게 필요한 것은 무엇인가요?","options":[{"t":"출처를 찾는 것과 함께 글이 설명하는 대상과 내용도 이해하며 읽기","correct":true},{"t":"출처에 밑줄을 한 번 더 긋기","mis":"K3-2-u3-X34"},{"t":"출처 기관의 이름이 긴 순서대로 줄 세우기","mis":"K3-2-u3-X14"},{"t":"글은 읽지 않고 그림 자료만 보기","mis":"K3-2-u3-X33"}],"explanation":["출처를 확인하며 읽는 데만 집중하면 내용을 놓칠 수 있어요.","글의 주제와 목적, 내용을 충분히 이해하는 것도 중요해요.","출처를 표시한 뒤에는 내용을 다시 파악해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_challenge#6','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C9',3,'mc','auto','『국어』 123쪽 세상과 연결하기예요. 점자가 필요한 곳과 그 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":6,"concept":"K3-2-u3-C9","difficulty":3,"kind":"mc","stem":"『국어』 123쪽 세상과 연결하기예요. 점자가 필요한 곳과 그 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"식당 차림표 — 시각 장애인이 스스로 음식을 골라 주문할 수 있게","correct":true},{"t":"텔레비전 화면 속 글자 — 눈으로 더 잘 보이게","mis":"K3-2-u3-X08"},{"t":"그림책의 그림 — 그림을 더 크게 보이게","mis":"K3-2-u3-X08"},{"t":"공책 표지 — 공책을 예쁘게 꾸미려고","mis":"K3-2-u3-X08"}],"explanation":["점자는 손가락으로 만져서 읽는 글자예요.","차림표에 점자가 있으면 시각 장애인도 혼자 주문할 수 있어요.","꼭 필요한데 아직 점자가 없는 곳을 찾아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_challenge#7','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C11',3,'mc','auto','「국립한글박물관에서 훈맹정음에 대한 자세한 정보를 얻을 수 있어.」 이 말은 출처를 어떻게 활용한 것인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X10']::text[],false,'{"seq":7,"concept":"K3-2-u3-C11","difficulty":3,"kind":"mc","stem":"「국립한글박물관에서 훈맹정음에 대한 자세한 정보를 얻을 수 있어.」 이 말은 출처를 어떻게 활용한 것인가요?","options":[{"t":"출처에 가서 더 자세하고 다양한 내용을 찾아보려는 것","correct":true},{"t":"출처의 이름이 유명하니 무조건 믿으려는 것","mis":"K3-2-u3-X12"},{"t":"출처가 있으니 글을 다시 읽지 않아도 된다는 것","mis":"K3-2-u3-X10"}],"explanation":["출처는 자료를 가져온 곳이에요.","그곳에 가면 더 자세하고 다양한 내용을 찾아볼 수 있어요.","이렇게 출처를 활용하면 능동적으로 글을 읽게 돼요."],"asset":{"type":"passage","lines":["10월 9일은 한글날입니다.","그렇다면 11월 4일은 무슨 날일까요?","11월 4일은 바로 한글 점자의 날입니다.","(간추림) 1926년 11월 4일, 송암 박두성 선생이 한글 점자를 만들어 반포했다.","(간추림) 시각 장애인을 위한 이 점자는 훈민정음의 원리를 따라 만들었다.","(간추림) 그래서 시각 장애인을 뜻하는 한자를 넣어 ‘훈맹정음’이라고도 부른다.","[그림] 훈맹정음 책","■ 출처: 「훈맹정음」, 국립한글박물관 누리집."],"title":"「손끝으로 읽는 여섯 개의 점」 앞부분 — 『국어』 119쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_challenge#8','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C9',4,'essay','teacher','「손끝으로 읽는 여섯 개의 점」에서 활용한 자료나 내용과 그 출처를 두 가지 이상 표처럼 정리하고, 그 가운데 하나를 골라 출처가 적절한지 확인하는 방법을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u3-C9","difficulty":4,"kind":"essay","stem":"「손끝으로 읽는 여섯 개의 점」에서 활용한 자료나 내용과 그 출처를 두 가지 이상 표처럼 정리하고, 그 가운데 하나를 골라 출처가 적절한지 확인하는 방법을 쓰세요.","answer_guide":{"answer":"예: 훈맹정음 그림 — 「훈맹정음」, 국립한글박물관 누리집 / 수표를 먼저 쓴다는 내용 — 문화체육관광부의 『한국 점자 규정』 / 점자 일람표 — 「점자 일람표」, 문화체육관광부 누리집. 문화체육관광부 누리집에 직접 들어가서 점자 일람표가 있는지 확인해 본다.","scoring_points":["자료나 내용을 두 가지 이상 찾았는가","각 자료의 출처를 바르게 짝지었는가","출처를 확인하는 방법을 썼는가"]},"explanation":["그림 아래 「■ 출처」와 본문 속 「…에 따르면」을 모두 찾아요.","찾은 자료와 출처를 짝지어 정리해요.","출처의 누리집에 들어가 보거나 어떤 기관인지 알아봐요."],"asset":{"type":"passage","lines":["점자는 손가락으로 만져서 읽는 글자입니다.","(간추림) 세로로 세 개, 가로로 두 개, 모두 여섯 개의 점으로 이루어진다.","(간추림) 왼쪽 위에서 아래로 1·2·3점, 오른쪽 위에서 아래로 4·5·6점이다.","(간추림) 승강기 층 버튼에 있는 작은 점들이 바로 숫자 점자다.","문화체육관광부의 『한국 점자 규정』에 따르면, 숫자를 점자로 쓸 때에는","숫자가 시작된다는 표시인 ‘수표’를 먼저 써야 합니다.","[그림] 점자 일람표 — 수표와 숫자 1~0","■ 출처: 「점자 일람표」, 문화체육관광부 누리집."],"title":"「손끝으로 읽는 여섯 개의 점」 가운데 — 『국어』 120쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_challenge#9','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C11',4,'essay','teacher','친구가 「출처가 있으니까 확인하지 않아도 돼.」라고 말했어요. 이 친구에게 출처를 확인하며 읽어야 하는 까닭과 확인하는 방법을 알려 주는 글을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C11","difficulty":4,"kind":"essay","stem":"친구가 「출처가 있으니까 확인하지 않아도 돼.」라고 말했어요. 이 친구에게 출처를 확인하며 읽어야 하는 까닭과 확인하는 방법을 알려 주는 글을 쓰세요.","answer_guide":{"answer":"예: 출처가 적혀 있어도 글에 나온 자료를 함부로 믿지 말고 생각해 보아야 해. 출처가 어떤 기관인지 알아보고, 그 누리집에 직접 들어가서 자료가 정말 있는지 확인해 봐. 그러면 더 자세한 정보도 얻을 수 있어.","scoring_points":["함부로 믿지 않고 생각해야 하는 까닭을 썼는가","어떤 기관인지 알아보는 방법을 썼는가","직접 찾아 확인하는 방법을 썼는가"]},"explanation":["출처가 있어도 그대로 믿기보다 살펴보며 읽어요.","어떤 곳인지 알아보고 직접 찾아가 확인할 수 있어요.","확인하다 보면 더 자세한 정보도 얻을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L05_challenge#10','kor',3,2,'u3','L05','tb_g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C10',4,'essay','teacher','『국어』 121쪽 낱말 「구별」, 「동일」, 「구성」 가운데 두 낱말을 골라 점자나 생활과 관련된 문장을 하나씩 만드세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C10","difficulty":4,"kind":"essay","stem":"『국어』 121쪽 낱말 「구별」, 「동일」, 「구성」 가운데 두 낱말을 골라 점자나 생활과 관련된 문장을 하나씩 만드세요.","answer_guide":{"answer":"예: 구별 — 점자는 점의 개수와 위치로 글자를 구별한다. 동일 — 나와 짝은 동일한 색의 필통을 가지고 있다.","scoring_points":["두 낱말을 골랐는가","낱말의 뜻에 맞게 문장을 만들었는가","문장이 바르고 자연스러운가"]},"explanation":["구별은 성질이나 종류에 따라 갈라놓음이에요.","동일은 똑같음, 구성은 부분을 모아 전체를 짜 이룸이에요.","뜻에 맞는 상황을 떠올려 문장을 만들어요."],"asset":{"type":"passage","lines":["보기: 구별 · 동일 · 구성","㉠ 성질이나 종류에 따라 갈라놓음.","㉡ 몇 가지 부분을 모아서 일정한 전체를 짜 이룸.","㉢ 어떤 것과 비교하여 똑같음."],"title":"낱말 알기 — 『국어』 121쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_basic#1','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',1,'blank','auto','『국어』 125쪽에 나온 말이에요. 「‘그러나’, ‘그래서’, ‘그리고’와 같이 앞뒤 내용을 연결해 주는 말을 (     )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X17']::text[],false,'{"seq":1,"concept":"K3-2-u3-C12","difficulty":1,"kind":"blank","stem":"『국어』 125쪽에 나온 말이에요. 「‘그러나’, ‘그래서’, ‘그리고’와 같이 앞뒤 내용을 연결해 주는 말을 (     )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"이어 주는 말","correct":true},{"t":"때를 나타내는 말","mis":"K3-2-u3-X17"},{"t":"곳을 나타내는 말","mis":"K3-2-u3-X17"}],"explanation":["그러나, 그래서, 그리고는 앞 문장과 뒤 문장을 이어 줘요.","이런 말을 이어 주는 말이라고 해요.","‘토요일’, ‘병원에’처럼 때나 곳을 나타내는 말과는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_basic#2','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',1,'mc','auto','「감기 걸린 날」을 읽고 답해요. 토요일 아침에 연우의 몸 상태는 어땠나요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":2,"concept":"K3-2-u3-C12","difficulty":1,"kind":"mc","stem":"「감기 걸린 날」을 읽고 답해요. 토요일 아침에 연우의 몸 상태는 어땠나요?","options":[{"t":"머리가 아프고 재채기가 나왔다","correct":true},{"t":"배가 아프고 열이 많이 났다","mis":"K3-2-u3-X08"},{"t":"다리를 다쳐 걷지 못했다","mis":"K3-2-u3-X08"},{"t":"목소리가 전혀 나오지 않았다","mis":"K3-2-u3-X08"}],"explanation":["「연우는 잠에서 깨자마자 머리가 아프고 재채기가 나왔습니다.」라고 했어요.","몸도 으슬으슬해서 감기에 걸린 것 같았어요.","목소리는 나오지 않을까 봐 걱정한 것이에요."],"asset":{"type":"passage","lines":["토요일 아침이었습니다.","(간추림) 연우는 머리가 아프고 재채기가 나와 감기에 걸린 것 같았다.","(간추림) 어머니께서는 병원에 다녀오면 괜찮아질 거라며 걱정하지 말라고 하셨다.","그러나 연우는 마음이 놓이지 않았습니다.","(간추림) 다음 주 금요일 연극 공연에서 목소리가 안 나올까 봐 걱정되었다.","그래서 연우는 어머니와 함께 병원에 갔습니다.","(간추림) 의사 선생님께서 이틀 동안 먹을 약을 처방해 주셨다.","그리고 따뜻한 물을 자주 마시고 푹 쉬어야 한다고 알려 주셨습니다."],"title":"「감기 걸린 날」 — 『국어』 124쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_basic#3','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',1,'match','auto','『국어』 125쪽 3번이에요. 이어 주는 말과 그 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u3-C12","difficulty":1,"kind":"match","stem":"『국어』 125쪽 3번이에요. 이어 주는 말과 그 쓰임을 알맞게 이으세요.","pairs":[{"l":"그리고","r":"앞의 내용과 비슷한 내용이 연결될 때 써요."},{"l":"그러나","r":"앞의 내용과 반대되는 내용이 연결될 때 써요."},{"l":"그래서","r":"앞의 내용이 뒤의 내용의 이유가 될 때 써요."}],"mis":"K3-2-u3-X16","explanation":["「약을 처방해 주셨습니다. 그리고 물을 자주 마시라고」는 비슷한 내용이 이어져요.","「걱정하지 말라고 하셨습니다. 그러나 마음이 놓이지 않았습니다.」는 반대예요.","「걱정되었습니다. 그래서 병원에 갔습니다.」는 앞이 뒤의 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_basic#4','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',1,'blank','auto','『국어』 126쪽 4번이에요. 「슬기는 책 읽기를 좋아합니다. (     ) 슬기는 글쓰기도 좋아합니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":4,"concept":"K3-2-u3-C12","difficulty":1,"kind":"blank","stem":"『국어』 126쪽 4번이에요. 「슬기는 책 읽기를 좋아합니다. (     ) 슬기는 글쓰기도 좋아합니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그리고","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그래서","mis":"K3-2-u3-X16"}],"explanation":["책 읽기를 좋아한다는 내용 뒤에 글쓰기도 좋아한다는 내용이 이어져요.","앞과 비슷한 내용이 연결되니 ‘그리고’를 써요.","‘도’라는 말도 비슷한 내용이 더해진다는 단서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_basic#5','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',2,'blank','auto','『국어』 126쪽 4번이에요. 「재환이는 도화지에 그림을 그리고 싶었습니다. (     ) 도화지가 보이지 않았습니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":5,"concept":"K3-2-u3-C12","difficulty":2,"kind":"blank","stem":"『국어』 126쪽 4번이에요. 「재환이는 도화지에 그림을 그리고 싶었습니다. (     ) 도화지가 보이지 않았습니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그러나","correct":true},{"t":"그래서","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["그림을 그리고 싶었는데 도화지가 없었어요.","앞의 내용과 반대되는 내용이 이어져요.","그래서 ‘그러나’를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_basic#6','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',2,'blank','auto','『국어』 126쪽 4번이에요. 「여진이는 운동을 좋아합니다. (     ) 늘 운동 시간을 기다립니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":6,"concept":"K3-2-u3-C12","difficulty":2,"kind":"blank","stem":"『국어』 126쪽 4번이에요. 「여진이는 운동을 좋아합니다. (     ) 늘 운동 시간을 기다립니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그래서","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["운동을 좋아하는 것이 운동 시간을 기다리는 이유예요.","앞의 내용이 뒤의 내용의 이유가 될 때 ‘그래서’를 써요.","앞뒤를 ‘왜?’로 이어 보면 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_basic#7','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',2,'mc','auto','「감기 걸린 날」의 「그래서 연우는 어머니와 함께 병원에 갔습니다.」에서 ‘그래서’는 앞뒤 내용을 어떻게 이어 주나요?',ARRAY['K3-2-u3-X16','K3-2-u3-X19']::text[],false,'{"seq":7,"concept":"K3-2-u3-C12","difficulty":2,"kind":"mc","stem":"「감기 걸린 날」의 「그래서 연우는 어머니와 함께 병원에 갔습니다.」에서 ‘그래서’는 앞뒤 내용을 어떻게 이어 주나요?","options":[{"t":"목소리가 안 나올까 봐 걱정한 것이 병원에 간 이유가 된다","correct":true},{"t":"병원에 간 것이 걱정한 이유가 된다","mis":"K3-2-u3-X16"},{"t":"앞뒤 내용이 서로 반대된다","mis":"K3-2-u3-X16"},{"t":"앞뒤 내용은 서로 상관이 없다","mis":"K3-2-u3-X19"}],"explanation":["‘그래서’ 앞에는 연극 공연에서 목소리가 안 나올까 봐 걱정한 내용이 있어요.","그 걱정 때문에 병원에 갔어요.","앞의 내용이 뒤의 내용의 이유가 될 때 ‘그래서’를 써요."],"asset":{"type":"passage","lines":["토요일 아침이었습니다.","(간추림) 연우는 머리가 아프고 재채기가 나와 감기에 걸린 것 같았다.","(간추림) 어머니께서는 병원에 다녀오면 괜찮아질 거라며 걱정하지 말라고 하셨다.","그러나 연우는 마음이 놓이지 않았습니다.","(간추림) 다음 주 금요일 연극 공연에서 목소리가 안 나올까 봐 걱정되었다.","그래서 연우는 어머니와 함께 병원에 갔습니다.","(간추림) 의사 선생님께서 이틀 동안 먹을 약을 처방해 주셨다.","그리고 따뜻한 물을 자주 마시고 푹 쉬어야 한다고 알려 주셨습니다."],"title":"「감기 걸린 날」 — 『국어』 124쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_basic#8','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',2,'error','auto','「감기 걸린 날」을 다시 읽고 이어 주는 말을 찾았어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X17','K3-2-u3-X16']::text[],false,'{"seq":8,"concept":"K3-2-u3-C12","difficulty":2,"kind":"error","stem":"「감기 걸린 날」을 다시 읽고 이어 주는 말을 찾았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준: 「토요일 아침이었습니다.」의 ‘토요일’도 앞뒤 문장을 이어 주는 말이야.","correct":true,"mis_target":"K3-2-u3-X17"},{"t":"소윤: ‘그러나’는 앞과 반대되는 내용을 이어 줘.","mis":"K3-2-u3-X16"},{"t":"지민: ‘그리고’는 앞과 비슷한 내용을 이어 줘.","mis":"K3-2-u3-X16"}],"explanation":["‘토요일’은 때를 나타내는 말이에요.","앞 문장과 뒤 문장을 이어 주는 말이 아니에요.","「감기 걸린 날」의 이어 주는 말은 그러나, 그래서, 그리고예요."],"asset":{"type":"passage","lines":["토요일 아침이었습니다.","(간추림) 연우는 머리가 아프고 재채기가 나와 감기에 걸린 것 같았다.","(간추림) 어머니께서는 병원에 다녀오면 괜찮아질 거라며 걱정하지 말라고 하셨다.","그러나 연우는 마음이 놓이지 않았습니다.","(간추림) 다음 주 금요일 연극 공연에서 목소리가 안 나올까 봐 걱정되었다.","그래서 연우는 어머니와 함께 병원에 갔습니다.","(간추림) 의사 선생님께서 이틀 동안 먹을 약을 처방해 주셨다.","그리고 따뜻한 물을 자주 마시고 푹 쉬어야 한다고 알려 주셨습니다."],"title":"「감기 걸린 날」 — 『국어』 124쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_basic#9','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C13',2,'mc','auto','이어 주는 말을 사용하면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X18','K3-2-u3-X19','K3-2-u3-X17']::text[],false,'{"seq":9,"concept":"K3-2-u3-C13","difficulty":2,"kind":"mc","stem":"이어 주는 말을 사용하면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"일어난 일을 순서대로 정리해 말하기 좋고, 설명하는 글을 이해하기 쉽게 쓸 수 있다","correct":true},{"t":"문장마다 넣을수록 글이 더 좋아진다","mis":"K3-2-u3-X18"},{"t":"없어도 뜻은 통하니 하나도 쓰지 않는 것이 더 좋다","mis":"K3-2-u3-X19"},{"t":"때와 곳을 알려 준다","mis":"K3-2-u3-X17"}],"explanation":["이어 주는 말은 문장 사이를 자연스럽게 이어 줘요.","일어난 일의 차례를 이해하기 쉽게 정리할 수 있어요.","많이 쓰는 것이 아니라 알맞게 쓰는 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_basic#10','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',3,'mc','auto','두 문장의 빈칸에 들어갈 이어 주는 말을 차례대로 고르세요. 「누나는 피아노를 잘 칩니다. (  ㉠  ) 나는 피아노를 잘 못 칩니다.」 「나는 우리 반 친구들을 참 좋아합니다. (  ㉡  ) 학교에 오는 일이 무척 즐겁습니다.」',ARRAY['K3-2-u3-X16','K3-2-u3-X18']::text[],false,'{"seq":10,"concept":"K3-2-u3-C12","difficulty":3,"kind":"mc","stem":"두 문장의 빈칸에 들어갈 이어 주는 말을 차례대로 고르세요. 「누나는 피아노를 잘 칩니다. (  ㉠  ) 나는 피아노를 잘 못 칩니다.」 「나는 우리 반 친구들을 참 좋아합니다. (  ㉡  ) 학교에 오는 일이 무척 즐겁습니다.」","options":[{"t":"㉠ 그러나 · ㉡ 그래서","correct":true},{"t":"㉠ 그래서 · ㉡ 그러나","mis":"K3-2-u3-X16"},{"t":"㉠ 그리고 · ㉡ 그리고","mis":"K3-2-u3-X18"},{"t":"㉠ 그러나 · ㉡ 그러나","mis":"K3-2-u3-X16"}],"explanation":["누나는 잘 치고 나는 잘 못 쳐요 — 반대되는 내용이라 ‘그러나’예요.","친구들을 좋아하는 것이 학교 오는 일이 즐거운 이유예요 — ‘그래서’예요.","앞뒤 관계를 먼저 따지고 이어 주는 말을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_challenge#1','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',2,'blank','auto','『국어활동』 45쪽이에요. 「동생이 감기에 걸려서 엄마와 병원에 갔어. (     ) 약국에 가서 약을 받았어.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":1,"concept":"K3-2-u3-C12","difficulty":2,"kind":"blank","stem":"『국어활동』 45쪽이에요. 「동생이 감기에 걸려서 엄마와 병원에 갔어. (     ) 약국에 가서 약을 받았어.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그리고","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그래서","mis":"K3-2-u3-X16"}],"explanation":["병원에 간 일 다음에 약국에 간 일이 이어져요.","앞과 비슷한 내용, 이어서 한 일을 더할 때 ‘그리고’를 써요.","일어난 차례대로 자연스럽게 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_challenge#2','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',2,'blank','auto','『국어활동』 45쪽이에요. 「나는 도서관에서 빌린 책을 깜빡하고 반납하지 못했어. (     ) 그만 연체되고 말았어.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":2,"concept":"K3-2-u3-C12","difficulty":2,"kind":"blank","stem":"『국어활동』 45쪽이에요. 「나는 도서관에서 빌린 책을 깜빡하고 반납하지 못했어. (     ) 그만 연체되고 말았어.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그래서","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["책을 반납하지 못한 것이 연체된 이유예요.","앞의 내용이 뒤의 내용의 이유가 되니 ‘그래서’를 써요.","‘그만 …고 말았어’도 앞 일의 결과라는 단서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_challenge#3','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',3,'blank','auto','『국어활동』 45쪽이에요. 「나는 해달과 수달을 구분할 수 있어. 조개를 들고 있으면 해달이야. (     ) 수달은 조개를 먹지 않기 때문이야.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":3,"concept":"K3-2-u3-C12","difficulty":3,"kind":"blank","stem":"『국어활동』 45쪽이에요. 「나는 해달과 수달을 구분할 수 있어. 조개를 들고 있으면 해달이야. (     ) 수달은 조개를 먹지 않기 때문이야.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"왜냐하면","correct":true},{"t":"그래서","mis":"K3-2-u3-X16"},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["뒤 문장이 「…때문이야」로 끝나요.","뒤에 앞 내용의 까닭이 올 때 ‘왜냐하면’을 써요.","‘그래서’는 반대로 앞이 까닭이고 뒤가 결과일 때 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_challenge#4','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C13',3,'mc','auto','「감기 걸린 날」의 내용을 이어 주는 말을 바르게 사용해 간추린 것은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X18','K3-2-u3-X19']::text[],false,'{"seq":4,"concept":"K3-2-u3-C13","difficulty":3,"kind":"mc","stem":"「감기 걸린 날」의 내용을 이어 주는 말을 바르게 사용해 간추린 것은 무엇인가요?","options":[{"t":"어머니께서는 걱정하지 말라고 하셨습니다. 그러나 연우는 무척 걱정되었습니다. 그래서 어머니와 함께 병원에 갔습니다.","correct":true},{"t":"어머니께서는 걱정하지 말라고 하셨습니다. 그래서 연우는 무척 걱정되었습니다. 그러나 어머니와 함께 병원에 갔습니다.","mis":"K3-2-u3-X16"},{"t":"그리고 어머니께서는 걱정하지 말라고 하셨습니다. 그리고 연우는 무척 걱정되었습니다. 그리고 어머니와 함께 병원에 갔습니다.","mis":"K3-2-u3-X18"},{"t":"어머니께서는 걱정하지 말라고 하셨습니다. 연우는 무척 걱정되었습니다. 어머니와 함께 병원에 갔습니다.","mis":"K3-2-u3-X19"}],"explanation":["걱정하지 말라는 말과 걱정되었다는 마음은 반대라서 ‘그러나’예요.","걱정되어서 병원에 갔으니 ‘그래서’예요.","문장마다 넣거나 하나도 안 쓰면 앞뒤 관계가 드러나지 않아요."],"asset":{"type":"passage","lines":["토요일 아침이었습니다.","(간추림) 연우는 머리가 아프고 재채기가 나와 감기에 걸린 것 같았다.","(간추림) 어머니께서는 병원에 다녀오면 괜찮아질 거라며 걱정하지 말라고 하셨다.","그러나 연우는 마음이 놓이지 않았습니다.","(간추림) 다음 주 금요일 연극 공연에서 목소리가 안 나올까 봐 걱정되었다.","그래서 연우는 어머니와 함께 병원에 갔습니다.","(간추림) 의사 선생님께서 이틀 동안 먹을 약을 처방해 주셨다.","그리고 따뜻한 물을 자주 마시고 푹 쉬어야 한다고 알려 주셨습니다."],"title":"「감기 걸린 날」 — 『국어』 124쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_challenge#5','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',3,'error','auto','『국어』 127쪽 문장 완성하기 놀이에서 문장 카드에 이어 주는 말 카드를 놓았어요. 잘못 놓은 카드는 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":5,"concept":"K3-2-u3-C12","difficulty":3,"kind":"error","stem":"『국어』 127쪽 문장 완성하기 놀이에서 문장 카드에 이어 주는 말 카드를 놓았어요. 잘못 놓은 카드는 무엇인가요?","options":[{"t":"「나는 오늘 아침에 늦잠을 잤다. (그러나) 나는 지각했다.」","correct":true,"mis_target":"K3-2-u3-X16"},{"t":"「윤석이는 어머니를 도와드리려고 설거지를 했다. (그리고) 방 청소도 했다.」","mis":"K3-2-u3-X16"},{"t":"「가을이 되어서 날씨가 쌀쌀해졌다. (그래서) 지윤이는 두꺼운 외투를 입었다.」","mis":"K3-2-u3-X16"}],"explanation":["늦잠을 잔 것이 지각한 이유예요.","앞이 뒤의 이유가 되니 ‘그러나’가 아니라 ‘그래서’를 놓아야 해요.","설거지와 방 청소는 비슷한 일이 이어지고, 쌀쌀해진 날씨는 외투를 입은 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_challenge#6','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',3,'mc','auto','문장 이어 가기 놀이를 하고 있어요. ⑤에 이어 갈 문장으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X17','K3-2-u3-X08']::text[],false,'{"seq":6,"concept":"K3-2-u3-C12","difficulty":3,"kind":"mc","stem":"문장 이어 가기 놀이를 하고 있어요. ⑤에 이어 갈 문장으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그래서 식당에 들어가려면 한 시간 넘게 줄을 서야 했다.","correct":true},{"t":"그러나 식당에 들어가려면 한 시간 넘게 줄을 서야 했다.","mis":"K3-2-u3-X16"},{"t":"목요일에는 식당에 들어가려면 줄을 서야 했다.","mis":"K3-2-u3-X17"},{"t":"그리고 우리 동네에는 식당이 하나도 없었다.","mis":"K3-2-u3-X08"}],"explanation":["두 시간만 문을 열고, 특별한 음식을 판다는 소문까지 났어요.","그래서 사람이 많이 몰렸다는 결과가 이어지는 것이 자연스러워요.","앞 사람이 정한 문장의 내용에 어울리게 이어 가요."],"asset":{"type":"passage","lines":["① 우리 동네에 새 식당이 생겼다.","② 사람들은 음식 맛이 궁금해서 가 보고 싶어 했다.","③ 그런데 이 식당은 하루에 두 시간만 문을 연다.","④ 그리고 식당에서는 특별한 음식을 판다는 소문이 났다.","⑤ (          )"],"title":"문장 이어 가기 놀이 — 모둠 친구들이 이어 간 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_challenge#7','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C13',3,'mc','auto','긴 문장 「나는 달리기 연습을 매일 꾸준히 해서 달리기 실력이 많이 좋아졌습니다.」를 짧은 두 문장으로 나누어 이어 주는 말로 이었어요. 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X18','K3-2-u3-X19']::text[],false,'{"seq":7,"concept":"K3-2-u3-C13","difficulty":3,"kind":"mc","stem":"긴 문장 「나는 달리기 연습을 매일 꾸준히 해서 달리기 실력이 많이 좋아졌습니다.」를 짧은 두 문장으로 나누어 이어 주는 말로 이었어요. 알맞은 것은 무엇인가요?","options":[{"t":"나는 달리기 연습을 매일 꾸준히 했습니다. 그래서 달리기 실력이 많이 좋아졌습니다.","correct":true},{"t":"나는 달리기 연습을 매일 꾸준히 했습니다. 그러나 달리기 실력이 많이 좋아졌습니다.","mis":"K3-2-u3-X16"},{"t":"나는 달리기 연습을 매일 꾸준히 했습니다. 그리고 그러나 달리기 실력이 많이 좋아졌습니다.","mis":"K3-2-u3-X18"},{"t":"나는 달리기 연습을 매일 꾸준히 했습니다. 달리기 실력이 많이 좋아졌습니다.","mis":"K3-2-u3-X19"}],"explanation":["긴 문장을 짧게 나누면 이어 주는 말이 필요해져요.","꾸준히 연습한 것이 실력이 좋아진 이유라서 ‘그래서’를 써요.","이어 주는 말이 없으면 두 문장의 관계가 잘 드러나지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_challenge#8','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',4,'essay','teacher','이어 주는 말 ‘그리고’, ‘그러나’, ‘그래서’를 하나씩 넣어 문장을 세 개 만드세요. 각 문장에서 앞뒤 내용이 어떻게 이어지는지도 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u3-C12","difficulty":4,"kind":"essay","stem":"이어 주는 말 ‘그리고’, ‘그러나’, ‘그래서’를 하나씩 넣어 문장을 세 개 만드세요. 각 문장에서 앞뒤 내용이 어떻게 이어지는지도 쓰세요.","answer_guide":{"answer":"예: 나는 숙제를 했습니다. 그리고 일기도 썼습니다.(비슷한 내용) 나는 일찍 일어났습니다. 그러나 버스를 놓쳤습니다.(반대되는 내용) 비가 많이 왔습니다. 그래서 우산을 썼습니다.(앞이 뒤의 이유)","scoring_points":["세 이어 주는 말을 모두 넣었는가","각 쓰임에 맞게 앞뒤 내용을 이었는가","앞뒤가 어떻게 이어지는지 썼는가"]},"explanation":["그리고는 비슷한 내용, 그러나는 반대되는 내용을 이어요.","그래서는 앞이 뒤의 이유가 될 때 써요.","생활 속에서 겪은 일로 문장을 만들어 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_challenge#9','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C13',4,'essay','teacher','「감기 걸린 날」에서 연우에게 일어난 일을 순서대로 정리하고, 이어 주는 말을 두 개 이상 바르게 사용해 내용을 간추려 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C13","difficulty":4,"kind":"essay","stem":"「감기 걸린 날」에서 연우에게 일어난 일을 순서대로 정리하고, 이어 주는 말을 두 개 이상 바르게 사용해 내용을 간추려 쓰세요.","answer_guide":{"answer":"예: 토요일 아침에 일어나자마자 연우는 머리가 아팠습니다. 그리고 재채기도 났습니다. 어머니께서는 걱정하지 말라고 하셨습니다. 그러나 연우는 연극 공연 때문에 무척 걱정되었습니다. 그래서 어머니와 함께 병원에 갔습니다.","scoring_points":["일어난 일을 순서대로 정리했는가","이어 주는 말을 두 개 이상 썼는가","이어 주는 말을 앞뒤 관계에 맞게 썼는가"]},"explanation":["먼저 연우에게 일어난 일을 차례대로 떠올려요.","앞뒤 관계에 맞는 이어 주는 말로 문장을 이어요.","이어 주는 말을 쓰면 일어난 일의 차례가 잘 드러나요."],"asset":{"type":"passage","lines":["토요일 아침이었습니다.","(간추림) 연우는 머리가 아프고 재채기가 나와 감기에 걸린 것 같았다.","(간추림) 어머니께서는 병원에 다녀오면 괜찮아질 거라며 걱정하지 말라고 하셨다.","그러나 연우는 마음이 놓이지 않았습니다.","(간추림) 다음 주 금요일 연극 공연에서 목소리가 안 나올까 봐 걱정되었다.","그래서 연우는 어머니와 함께 병원에 갔습니다.","(간추림) 의사 선생님께서 이틀 동안 먹을 약을 처방해 주셨다.","그리고 따뜻한 물을 자주 마시고 푹 쉬어야 한다고 알려 주셨습니다."],"title":"「감기 걸린 날」 — 『국어』 124쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L07_challenge#10','kor',3,2,'u3','L07','tb_g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',4,'essay','teacher','『국어』 108쪽 여자아이의 글에서 「먼저, 색종이를 반으로 접었다 펼쳐 봐. 그래서 접은 선을 따라 양쪽 날개를 똑같이 접어 봐.」를 알맞게 고쳐 쓰고, 고친 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C12","difficulty":4,"kind":"essay","stem":"『국어』 108쪽 여자아이의 글에서 「먼저, 색종이를 반으로 접었다 펼쳐 봐. 그래서 접은 선을 따라 양쪽 날개를 똑같이 접어 봐.」를 알맞게 고쳐 쓰고, 고친 까닭을 쓰세요.","answer_guide":{"answer":"예: 먼저, 색종이를 반으로 접었다 펼쳐 봐. 그다음에 접은 선을 따라 양쪽 날개를 똑같이 접어 봐. — 앞 문장이 뒤 문장의 이유가 아니라 다음 차례가 이어지는 것이므로 ‘그래서’ 대신 차례를 나타내는 말을 써야 한다.","scoring_points":["‘그래서’를 알맞은 말로 바꾸었는가","앞 문장이 이유가 아님을 밝혔는가","차례를 나타내는 말을 써야 하는 까닭을 썼는가"]},"explanation":["‘그래서’는 앞이 뒤의 이유가 될 때 써요.","접는 차례가 이어질 때는 ‘그다음에’ 같은 말이 어울려요.","설명하는 글은 일의 차례가 잘 드러나게 써요."],"asset":{"type":"passage","lines":["종이비행기 만드는 방법을 설명해 줄게.","먼저, 색종이를 반으로 접었다 펼쳐 봐.","그래서 접은 선을 따라 양쪽 날개를 똑같이 접어 봐. ……","마지막으로, 책에 나오지 않는 나만의 비법은","양쪽 날개를 점선을 따라 바깥쪽으로 접어서 날개 끝을 하늘로 향하게 하는 거야."],"title":"여자아이가 쓴 글 — 『국어』 108쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_basic#1','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C14',1,'mc','auto','『국어』 128쪽 만화를 읽고 답해요. 수지가 학급 신문에 쓰려는 글을 읽을 사람은 누구인가요?',ARRAY['K3-2-u3-X21']::text[],false,'{"seq":1,"concept":"K3-2-u3-C14","difficulty":1,"kind":"mc","stem":"『국어』 128쪽 만화를 읽고 답해요. 수지가 학급 신문에 쓰려는 글을 읽을 사람은 누구인가요?","options":[{"t":"3학년 우리 반 친구들","correct":true},{"t":"전기 회사에서 일하는 어른들","mis":"K3-2-u3-X21"},{"t":"수지 혼자","mis":"K3-2-u3-X21"},{"t":"외국에 사는 사람들","mis":"K3-2-u3-X21"}],"explanation":["학급 신문은 우리 반 친구들이 읽어요.","『국어』 129쪽에서 「내가 쓰는 글은 3학년 우리 반 친구들이 읽을 거야.」라고 했어요.","쓰기 전에 읽는 사람이 누구인지 생각해요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"수지야, 학급 신문에 ‘생활 안전’에 대한 글을 싣기로 했어. 알려 주고 싶은 내용이 있으면 써 볼래?"},{"who":"수지","text":"친구들에게 전기 안전 규칙을 알려 주고 싶은데 어떻게 해야 하지?"},{"who":"수지","text":"전기 안전 규칙에는 어떤 것들이 있는지 찾아봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_basic#2','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C14',1,'match','auto','『국어』 129쪽 3번이에요. 수지가 한 생각과 설명하는 글에 쓸 내용을 알아보는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u3-C14","difficulty":1,"kind":"match","stem":"『국어』 129쪽 3번이에요. 수지가 한 생각과 설명하는 글에 쓸 내용을 알아보는 방법을 알맞게 이으세요.","pairs":[{"l":"내가 쓰는 글은 3학년 우리 반 친구들이 읽을 거야.","r":"읽는 사람이 누구인지 생각한다."},{"l":"이 글의 목적은 친구들이 전기 안전 규칙을 잘 알도록 하는 거야.","r":"글의 목적이 무엇인지 생각한다."},{"l":"전기 안전 규칙에 대한 내용이 꼭 들어가야 해.","r":"어떤 내용을 설명할지 생각한다."}],"mis":"K3-2-u3-X21","explanation":["설명하는 글을 쓰기 전에 읽는 사람을 생각해요.","글을 쓰는 목적을 생각해요.","꼭 들어가야 할 내용을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_basic#3','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C15',1,'ox','auto','설명하는 글에 ‘먼저’, ‘다음에’, ‘끝으로’처럼 순서를 나타내는 말을 쓰면 읽는 사람이 이해하기 쉬워요.',ARRAY['K3-2-u3-X22']::text[],false,'{"seq":3,"concept":"K3-2-u3-C15","difficulty":1,"kind":"ox","stem":"설명하는 글에 ‘먼저’, ‘다음에’, ‘끝으로’처럼 순서를 나타내는 말을 쓰면 읽는 사람이 이해하기 쉬워요.","answer":"O","reason_options":[{"t":"일의 차례가 잘 드러나서 읽는 사람이 그대로 따라 하기 쉬워요.","correct":true},{"t":"순서를 나타내는 말은 꾸미는 말이라 아무 차례로 써도 돼요.","mis":"K3-2-u3-X22"}],"mis":"K3-2-u3-X22","explanation":["순서를 나타내는 말은 일의 차례를 알려 줘요.","‘먼저 → 다음에 → 끝으로’처럼 일의 순서에 맞게 써요.","읽는 사람이 무엇을 먼저 할지 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_basic#4','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C16',1,'sa','auto','수지가 고쳐 쓴 글에서 활용한 자료의 출처는 어느 기관의 누리집인가요? 기관 이름을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u3-C16","difficulty":1,"kind":"sa","stem":"수지가 고쳐 쓴 글에서 활용한 자료의 출처는 어느 기관의 누리집인가요? 기관 이름을 쓰세요.","answer":["한국전기안전공사","한국전기안전공사 누리집"],"explanation":["고쳐 쓴 글의 맨 끝을 보아요.","「■ 출처: 「전기 제품을 안전하게 사용할 때 지켜야 할 약속」, 한국전기안전공사 누리집.」이에요.","조사한 자료가 있으면 출처를 밝혀요."],"asset":{"type":"passage","lines":["(간추림) 처음 부분은 처음 쓴 글과 같다.","첫째, 젖은 손으로 전기 제품을 만지면 안 돼요.","둘째, 전깃줄을 뺄 때에는 줄이 아니라 꽂개를 꼭 잡고 빼야 해요.","셋째, 전기를 많이 사용하는 여러 개의 전기 제품을","모둠 전원 꽂이에 한꺼번에 꽂으면 안 돼요.","넷째, 고장 난 전기 제품은 혼자 고치지 말고 어른께 알려야 해요.","(간추림) 끝 — 가정에서 전기 제품을 어떻게 써야 안전한지 꼭 기억하자.","■ 출처: 「전기 제품을 안전하게 사용할 때 지켜야 할 약속」, 한국전기안전공사 누리집."],"title":"「전기 제품, 이렇게 쓰면 안전해요」 수지가 고쳐 쓴 글 — 『국어』 131쪽"},"mis":"K3-2-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_basic#5','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C15',2,'match','auto','수지가 처음 쓴 글에 친구들이 한 말과, 수지가 고쳐 쓴 부분을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u3-C15","difficulty":2,"kind":"match","stem":"수지가 처음 쓴 글에 친구들이 한 말과, 수지가 고쳐 쓴 부분을 알맞게 이으세요.","pairs":[{"l":"이해하기 힘든 낱말이 있어서 무슨 뜻인지 알기 어려워.","r":"‘과열’·‘합선’을 쉬운 말로 풀어 썼다."},{"l":"자료의 출처가 없어서 믿을 만한지 모르겠어.","r":"글 끝에 한국전기안전공사 누리집 출처를 밝혔다."},{"l":"전기 안전 규칙이 많아서 한눈에 파악하기 어려워.","r":"규칙을 ‘첫째, 둘째, 셋째, 넷째’로 나누어 썼다."}],"mis":"K3-2-u3-X21","explanation":["어려운 낱말은 읽는 사람이 이해하기 쉬운 낱말로 바꾸어요.","조사한 자료는 출처를 밝혀요.","규칙이 많으면 차례를 나타내는 말로 나누어 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"이해하기 힘든 낱말이 있어서 무슨 뜻인지 알기 어려워."},{"who":"친구 2","text":"자료의 출처가 없어서 믿을 만한지 모르겠어."},{"who":"친구 3","text":"전기 안전 규칙이 많아서 한눈에 파악하기 어려워."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_basic#6','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C15',2,'mc','auto','수지가 처음 쓴 글의 「다수의 전기 제품을 동시에 사용하면 과열이나 합선의 위험이 있어요.」를 3학년 친구들이 알기 쉽게 고쳐 쓴 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X21','K3-2-u3-X02','K3-2-u3-X35']::text[],false,'{"seq":6,"concept":"K3-2-u3-C15","difficulty":2,"kind":"mc","stem":"수지가 처음 쓴 글의 「다수의 전기 제품을 동시에 사용하면 과열이나 합선의 위험이 있어요.」를 3학년 친구들이 알기 쉽게 고쳐 쓴 것으로 알맞은 것은 무엇인가요?","options":[{"t":"셋째, 전기를 많이 사용하는 여러 개의 전기 제품을 모둠 전원 꽂이에 한꺼번에 꽂으면 안 돼요.","correct":true},{"t":"셋째, 다수 전기 제품 동시 사용 시 과열·합선 위험이 있어요.","mis":"K3-2-u3-X21"},{"t":"셋째, 전기 제품은 위험하니 아예 쓰지 말아요.","mis":"K3-2-u3-X02"},{"t":"어려운 말이 있으니 이 규칙은 빼고 쓰지 않아요.","mis":"K3-2-u3-X35"}],"explanation":["‘과열’, ‘합선’은 3학년 친구들이 이해하기 어려운 낱말이에요.","무엇을 하면 안 되는지 쉬운 말로 풀어 썼어요.","중요한 규칙은 빼지 않고 알기 쉽게 고쳐요."],"asset":{"type":"passage","lines":["(간추림) 집에 있는 전기 제품을 안전하게 쓰려면 몇 가지 약속을 꼭 지켜야 한다.","젖은 손으로 전기 제품을 만지면 안 돼요.","전깃줄을 뺄 때에는 줄이 아니라 꽂개를 꼭 잡고 빼야 해요.","다수의 전기 제품을 동시에 사용하면 과열이나 합선의 위험이 있어요.","고장 난 전기 제품은 혼자 고치지 말고 어른께 알려야 해요.","(간추림) 규칙을 한 문단에 이어 썼고, 자료의 출처는 적지 않았다."],"title":"「전기 제품, 이렇게 쓰면 안전해요」 수지가 처음 쓴 글 — 『국어』 130쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_basic#7','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C14',2,'mc','auto','수지는 쓰기 전에 「전기 안전 규칙에는 어떤 것들이 있는지 찾아봐야겠어.」라고 했어요. 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X20','K3-2-u3-X02','K3-2-u3-X21']::text[],false,'{"seq":7,"concept":"K3-2-u3-C14","difficulty":2,"kind":"mc","stem":"수지는 쓰기 전에 「전기 안전 규칙에는 어떤 것들이 있는지 찾아봐야겠어.」라고 했어요. 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"친구들에게 알려 줄 정보가 정확한지 확인하려고","correct":true},{"t":"글씨 색과 제목 꾸미기를 먼저 정하려고","mis":"K3-2-u3-X20"},{"t":"아는 것이 모자라면 그럴듯하게 지어내도 되니까","mis":"K3-2-u3-X02"},{"t":"어려운 낱말을 많이 찾아 넣으려고","mis":"K3-2-u3-X21"}],"explanation":["설명하는 글은 친구들에게 정보를 전하는 글이에요.","책이나 인터넷으로 조사해 내용이 정확한지 확인해요.","모르는 것을 지어내지 않아요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"수지야, 학급 신문에 ‘생활 안전’에 대한 글을 싣기로 했어. 알려 주고 싶은 내용이 있으면 써 볼래?"},{"who":"수지","text":"친구들에게 전기 안전 규칙을 알려 주고 싶은데 어떻게 해야 하지?"},{"who":"수지","text":"전기 안전 규칙에는 어떤 것들이 있는지 찾아봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_basic#8','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C16',2,'mc','auto','친구가 「글에 활용한 자료의 출처를 써 주어서 더 알고 싶은 내용을 찾아볼 수 있어서 좋아.」라고 했어요. 수지는 출처를 어떻게 밝혔나요?',ARRAY['K3-2-u3-X03','K3-2-u3-X06','K3-2-u3-X07']::text[],false,'{"seq":8,"concept":"K3-2-u3-C16","difficulty":2,"kind":"mc","stem":"친구가 「글에 활용한 자료의 출처를 써 주어서 더 알고 싶은 내용을 찾아볼 수 있어서 좋아.」라고 했어요. 수지는 출처를 어떻게 밝혔나요?","options":[{"t":"글의 맨 끝에 자료를 가져온 곳을 밝혔다","correct":true},{"t":"제목 바로 위에 글쓴이 이름을 썼다","mis":"K3-2-u3-X03"},{"t":"출처는 밝히지 않고 내가 아는 것처럼 썼다","mis":"K3-2-u3-X06"},{"t":"자료에서 알아낸 규칙을 모두 뺐다","mis":"K3-2-u3-X07"}],"explanation":["고쳐 쓴 글의 맨 끝에 「■ 출처」가 있어요.","조사한 자료가 있으면 출처를 글의 맨 끝에 밝혀요.","글쓴이 이름은 출처가 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"지켜야 하는 규칙을 ‘첫째, 둘째, 셋째’로 정리해서 기억하기 쉬워."},{"who":"친구 2","text":"이해하기 쉬운 낱말을 써서 하고 싶은 말이 무엇인지 정확히 이해할 수 있었어."},{"who":"친구 3","text":"글에 활용한 자료의 출처를 써 주어서 더 알고 싶은 내용을 찾아볼 수 있어서 좋아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_basic#9','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C14',2,'error','auto','설명하는 글을 쓰기 전에 생각할 것을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X20','K3-2-u3-X21']::text[],false,'{"seq":9,"concept":"K3-2-u3-C14","difficulty":2,"kind":"error","stem":"설명하는 글을 쓰기 전에 생각할 것을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호: 쓰기 전에 글씨 색과 글자 크기부터 정해야 해.","correct":true,"mis_target":"K3-2-u3-X20"},{"t":"가윤: 이 글을 누가 읽을지 먼저 생각해야 해.","mis":"K3-2-u3-X21"},{"t":"시우: 글에 꼭 들어가야 할 내용을 정해야 해.","mis":"K3-2-u3-X21"}],"explanation":["쓰기 전에는 읽는 사람, 글의 목적, 꼭 들어갈 내용을 생각해요.","글씨 색이나 크기 같은 꾸밈은 나중 일이에요.","계획을 먼저 세우면 쓸 내용이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_basic#10','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C15',3,'mc','auto','긴팔 윗옷을 개는 방법을 짝에게 설명하려고 해요. ㉠~㉤을 차례대로 바르게 늘어놓은 것은 무엇인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X35']::text[],false,'{"seq":10,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"긴팔 윗옷을 개는 방법을 짝에게 설명하려고 해요. ㉠~㉤을 차례대로 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"㉡ → ㉣ → ㉤ → ㉠ → ㉢","correct":true},{"t":"㉡ → ㉤ → ㉠ → ㉣ → ㉢","mis":"K3-2-u3-X22"},{"t":"㉢ → ㉡ → ㉣ → ㉤ → ㉠","mis":"K3-2-u3-X22"},{"t":"㉡ → ㉣ → ㉢","mis":"K3-2-u3-X35"}],"explanation":["먼저 윗옷을 반듯하게 펼쳐 놓고, 그리고 소매를 가운데로 모아요.","아래에서 3분의 1, 위에서 3분의 1을 차례로 접어요.","끝으로 보관해요 — 단계를 빠뜨리면 따라 하기 어려워요."],"asset":{"type":"passage","lines":["㉠ 위에서 3분의 1 지점을 안으로 접어 준다.","㉡ 윗옷을 반듯하게 펼쳐 놓는다.","㉢ 원하는 곳에 보관한다.","㉣ 소매를 옷의 중심선을 향해 가지런히 모아 준다.","㉤ 아래에서 3분의 1 지점을 안으로 접어 준다."],"title":"긴팔 윗옷을 개는 방법 (차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_challenge#1','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C14',2,'mc','auto','「읽을 대상에 따라 설명하는 글의 내용은 달라질 수 있어요.」 수지가 같은 내용을 1학년 동생들에게 설명한다면 어떻게 하면 좋을까요?',ARRAY['K3-2-u3-X21']::text[],false,'{"seq":1,"concept":"K3-2-u3-C14","difficulty":2,"kind":"mc","stem":"「읽을 대상에 따라 설명하는 글의 내용은 달라질 수 있어요.」 수지가 같은 내용을 1학년 동생들에게 설명한다면 어떻게 하면 좋을까요?","options":[{"t":"어려운 낱말을 더 쉬운 말로 바꾸고 차례를 더 자세히 나누어 쓴다","correct":true},{"t":"3학년 친구들에게 쓴 글을 하나도 바꾸지 않고 준다","mis":"K3-2-u3-X21"},{"t":"어려운 낱말을 더 넣어 멋있게 쓴다","mis":"K3-2-u3-X21"}],"explanation":["읽는 사람이 달라지면 쓰는 낱말과 자세한 정도도 달라져요.","1학년 동생들이 알아들을 수 있는 말로 바꾸어요.","읽는 사람을 생각하며 자세하게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_challenge#2','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C15',2,'blank','auto','규칙을 차례대로 정리한 안내 글이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X16']::text[],false,'{"seq":2,"concept":"K3-2-u3-C15","difficulty":2,"kind":"blank","stem":"규칙을 차례대로 정리한 안내 글이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"첫째","correct":true},{"t":"마지막으로","mis":"K3-2-u3-X22"},{"t":"그래서","mis":"K3-2-u3-X16"}],"explanation":["뒤에 「둘째」, 「마지막으로」가 이어져요.","그러니 맨 앞에는 「첫째」가 와야 해요.","지킬 규칙을 차례대로 정리하면 기억하기 쉬워요."],"asset":{"type":"passage","lines":["아리수 음수대 사용 에티켓","(     ), 수도꼭지에 직접 입이 닿지 않게 마신다.","둘째, 먹는 물로만 이용한다.","마지막으로, 누구나 함께 마시는 물이므로 깨끗하게 사용하고 아껴 준다."],"title":"규칙을 차례대로 정리한 안내 글 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_challenge#3','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C15',3,'mc','auto','수지가 처음 쓴 글보다 고쳐 쓴 글이 나아진 점이 아닌 것은 무엇인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X21','K3-2-u3-X07']::text[],false,'{"seq":3,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"수지가 처음 쓴 글보다 고쳐 쓴 글이 나아진 점이 아닌 것은 무엇인가요?","options":[{"t":"글자 수가 늘어나서 더 길어졌다","correct":true},{"t":"규칙을 첫째~넷째로 나누어 한눈에 보인다","mis":"K3-2-u3-X22"},{"t":"어려운 낱말을 쉬운 말로 풀었다","mis":"K3-2-u3-X21"},{"t":"글 끝에 자료의 출처를 밝혔다","mis":"K3-2-u3-X07"}],"explanation":["고쳐 쓴 글은 규칙을 차례대로 나누고, 쉬운 말로 풀고, 출처를 밝혔어요.","글이 길어진 것 자체가 좋아진 점은 아니에요.","읽는 사람이 알기 쉬워진 것이 좋아진 점이에요."],"asset":{"type":"passage","lines":["(간추림) 처음 부분은 처음 쓴 글과 같다.","첫째, 젖은 손으로 전기 제품을 만지면 안 돼요.","둘째, 전깃줄을 뺄 때에는 줄이 아니라 꽂개를 꼭 잡고 빼야 해요.","셋째, 전기를 많이 사용하는 여러 개의 전기 제품을","모둠 전원 꽂이에 한꺼번에 꽂으면 안 돼요.","넷째, 고장 난 전기 제품은 혼자 고치지 말고 어른께 알려야 해요.","(간추림) 끝 — 가정에서 전기 제품을 어떻게 써야 안전한지 꼭 기억하자.","■ 출처: 「전기 제품을 안전하게 사용할 때 지켜야 할 약속」, 한국전기안전공사 누리집."],"title":"「전기 제품, 이렇게 쓰면 안전해요」 수지가 고쳐 쓴 글 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_challenge#4','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C16',3,'mc','auto','순서나 방법을 설명하는 글을 쓸 때 출처를 밝혀야 하는 것은 무엇인가요?',ARRAY['K3-2-u3-X24','K3-2-u3-X03']::text[],false,'{"seq":4,"concept":"K3-2-u3-C16","difficulty":3,"kind":"mc","stem":"순서나 방법을 설명하는 글을 쓸 때 출처를 밝혀야 하는 것은 무엇인가요?","options":[{"t":"한국전기안전공사 누리집에서 알아낸 전기 안전 약속","correct":true},{"t":"내가 직접 해 보고 알게 된 방법","mis":"K3-2-u3-X24"},{"t":"글을 쓴 날짜","mis":"K3-2-u3-X03"},{"t":"글을 읽을 친구들의 이름","mis":"K3-2-u3-X03"}],"explanation":["다른 곳에서 찾아 가져온 자료는 출처를 밝혀요.","내가 직접 해 본 방법은 출처가 없어도 돼요.","날짜나 읽을 사람 이름은 출처가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_challenge#5','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C16',3,'error','auto','수지에게 출처를 쓰는 방법을 조언했어요. 잘못 조언한 친구는 누구인가요?',ARRAY['K3-2-u3-X23','K3-2-u3-X07']::text[],false,'{"seq":5,"concept":"K3-2-u3-C16","difficulty":3,"kind":"error","stem":"수지에게 출처를 쓰는 방법을 조언했어요. 잘못 조언한 친구는 누구인가요?","options":[{"t":"하람: 어느 누리집에서 봤는지 기억이 안 나면 그럴듯한 이름을 지어 적으면 돼.","correct":true,"mis_target":"K3-2-u3-X23"},{"t":"윤서: 찾아본 누리집 이름을 글 끝에 밝혀.","mis":"K3-2-u3-X07"},{"t":"도겸: 기억이 안 나면 다시 찾아 확인한 뒤에 적어.","mis":"K3-2-u3-X23"}],"explanation":["출처는 지어내는 것이 아니라 확인하는 거예요.","지어 적은 이름을 믿고 찾아간 친구는 아무것도 찾을 수 없어요.","기억이 안 나면 다시 찾아 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_challenge#6','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C14',3,'mc','auto','자신의 설명하기 계획을 붙임쪽지에 써서 친구와 바꾸어 읽었어요. 친구의 계획을 읽고 살펴볼 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X20','K3-2-u3-X01','K3-2-u3-X26']::text[],false,'{"seq":6,"concept":"K3-2-u3-C14","difficulty":3,"kind":"mc","stem":"자신의 설명하기 계획을 붙임쪽지에 써서 친구와 바꾸어 읽었어요. 친구의 계획을 읽고 살펴볼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"글의 목적이 무엇인지, 읽는 사람이 잘 이해할 수 있는지","correct":true},{"t":"글씨가 예쁜지, 붙임쪽지 색이 고운지","mis":"K3-2-u3-X20"},{"t":"계획이 얼마나 긴지","mis":"K3-2-u3-X01"},{"t":"몇 점을 줄 수 있는지","mis":"K3-2-u3-X26"}],"explanation":["계획을 바꾸어 읽으면 고칠 부분을 찾을 수 있어요.","글의 목적, 읽는 사람의 이해, 설명이 잘 전달될지를 살펴요.","친구의 의견이나 궁금한 점을 모아 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_challenge#7','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C15',3,'mc','auto','줄넘기하는 방법을 설명하는 글을 쓰려고 해요. 운동이나 놀이를 하는 방법을 설명할 때 순서를 나누는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X35','K3-2-u3-X31']::text[],false,'{"seq":7,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"줄넘기하는 방법을 설명하는 글을 쓰려고 해요. 운동이나 놀이를 하는 방법을 설명할 때 순서를 나누는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"하기 전 → 할 때 → 마친 뒤 정리하기","correct":true},{"t":"마친 뒤 → 하기 전 → 할 때","mis":"K3-2-u3-X22"},{"t":"할 때만 자세히 쓰고 준비와 정리는 뺀다","mis":"K3-2-u3-X35"},{"t":"줄넘기를 하며 든 느낌만 쓴다","mis":"K3-2-u3-X31"}],"explanation":["운동이나 놀이 방법은 하기 전, 할 때, 마친 뒤로 나누어 쓸 수 있어요.","준비와 정리도 중요한 순서라 빠뜨리지 않아요.","설명하는 글은 느낌이 아니라 방법을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_challenge#8','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C14',4,'essay','teacher','순서나 방법을 설명하는 글을 쓰려고 해요. 설명할 주제를 하나 정하고, 읽는 사람 · 글의 목적 · 꼭 들어가야 할 내용을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u3-C14","difficulty":4,"kind":"essay","stem":"순서나 방법을 설명하는 글을 쓰려고 해요. 설명할 주제를 하나 정하고, 읽는 사람 · 글의 목적 · 꼭 들어가야 할 내용을 쓰세요.","answer_guide":{"answer":"예: 주제 — 우리 반 화분에 물 주는 방법. 읽는 사람 — 3학년 우리 반 친구들. 글의 목적 — 친구들이 화분을 잘 돌볼 수 있게 하려고. 꼭 들어갈 내용 — 흙을 만져 보고 물 주기, 물을 주는 양, 물받이 비우기.","scoring_points":["설명할 주제를 정했는가","읽는 사람과 글의 목적을 썼는가","꼭 들어가야 할 내용을 썼는가"]},"explanation":["경험한 것 가운데 설명하고 싶은 주제를 찾아요.","읽는 사람과 목적을 먼저 생각하면 쓸 내용이 보여요.","읽는 사람이 궁금해할 내용으로 계획해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_challenge#9','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C15',4,'essay','teacher','수지가 처음 쓴 글에 친구들이 한 말 가운데 두 가지를 골라, 수지가 각각 어떻게 고쳤는지와 고쳐서 좋아진 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C15","difficulty":4,"kind":"essay","stem":"수지가 처음 쓴 글에 친구들이 한 말 가운데 두 가지를 골라, 수지가 각각 어떻게 고쳤는지와 고쳐서 좋아진 점을 쓰세요.","answer_guide":{"answer":"예: 「전기 안전 규칙이 많아서 한눈에 파악하기 어려워.」 → 규칙을 첫째, 둘째, 셋째, 넷째로 나누어 써서 기억하기 쉬워졌다. 「이해하기 힘든 낱말이 있어」 → 과열, 합선 같은 낱말을 쉬운 말로 풀어 써서 하고 싶은 말을 정확히 알 수 있게 되었다.","scoring_points":["친구의 말 두 가지를 골랐는가","각각 어떻게 고쳤는지 썼는가","고쳐서 좋아진 점을 썼는가"]},"explanation":["읽는 사람의 반응을 듣고 글을 고쳐요.","차례를 나타내는 말, 쉬운 낱말, 출처가 글을 좋아지게 해요.","고친 글을 다시 읽으며 알기 쉬운지 확인해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"이해하기 힘든 낱말이 있어서 무슨 뜻인지 알기 어려워."},{"who":"친구 2","text":"자료의 출처가 없어서 믿을 만한지 모르겠어."},{"who":"친구 3","text":"전기 안전 규칙이 많아서 한눈에 파악하기 어려워."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L09_challenge#10','kor',3,2,'u3','L09','tb_g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C16',4,'essay','teacher','책에서 알아낸 방법과 내가 직접 해 본 방법을 함께 넣어 설명하는 글을 쓰려고 해요. 출처를 어떻게 밝히면 좋을지 두 가지 경우로 나누어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C16","difficulty":4,"kind":"essay","stem":"책에서 알아낸 방법과 내가 직접 해 본 방법을 함께 넣어 설명하는 글을 쓰려고 해요. 출처를 어떻게 밝히면 좋을지 두 가지 경우로 나누어 쓰세요.","answer_guide":{"answer":"예: 책에서 알아낸 방법은 그 책 이름과 만든 곳을 글의 맨 끝에 출처로 밝힌다. 내가 직접 해 본 방법은 다른 곳에서 가져온 것이 아니므로 출처를 쓰지 않아도 되고, 내가 해 본 방법이라고 밝히면 된다.","scoring_points":["찾아본 자료는 출처를 밝힌다고 썼는가","직접 해 본 방법은 출처가 없어도 된다고 썼는가","출처를 밝히는 자리를 썼는가"]},"explanation":["다른 사람이 만든 자료를 가져왔다면 출처를 밝혀요.","내가 이미 해 본 방법에는 출처가 없어도 돼요.","출처는 글의 맨 끝에 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_basic#1','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C17',1,'mc','auto','『국어』 135쪽처럼 「개인 사물함을 정리하는 방법」의 짜임을 정리했어요. 처음 부분에 쓸 내용은 무엇인가요?',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":1,"concept":"K3-2-u3-C17","difficulty":1,"kind":"mc","stem":"『국어』 135쪽처럼 「개인 사물함을 정리하는 방법」의 짜임을 정리했어요. 처음 부분에 쓸 내용은 무엇인가요?","options":[{"t":"무엇을 설명하는 글인지(글을 쓰는 목적)","correct":true},{"t":"사물함을 정리하는 차례와 방법","mis":"K3-2-u3-X25"},{"t":"설명한 내용 간추리기","mis":"K3-2-u3-X25"},{"t":"참고한 자료의 출처","mis":"K3-2-u3-X25"}],"explanation":["처음 부분에는 무엇을 설명하는 글인지 밝혀요.","가운데 부분에는 일의 순서나 방법을 자세히 써요.","끝부분에는 설명한 내용을 간추려요."],"asset":{"type":"passage","lines":["제목 — 개인 사물함을 정리하는 방법","처음(글을 쓰는 목적) — 개인 사물함을 정리하는 방법 설명하기","가운데(일의 순서나 방법) — 물건을 종류에 따라 분류하기","가운데 — 교과서와 공책은 파일꽂이를 사용해 세워 두기","가운데 — 자주 쓰는 색연필, 자, 휴지는 정리 바구니에 넣어 두기","가운데 — 참고한 자료의 출처 쓰기","끝(설명한 내용 간추리기) — 분류하고 정리 도구로 보관하면 편리함"],"title":"쓸 내용 정리하기 — 『국어』 135쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_basic#2','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C17',1,'match','auto','『국어』 134쪽 (1)이에요. 정리할 사물의 종류와 정리하는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u3-C17","difficulty":1,"kind":"match","stem":"『국어』 134쪽 (1)이에요. 정리할 사물의 종류와 정리하는 방법을 알맞게 이으세요.","pairs":[{"l":"교과서, 공책, 파일","r":"세우거나 꽂기"},{"l":"색연필, 풀, 가위","r":"정리 바구니에 담기"},{"l":"리코더, 줄넘기","r":"정리 주머니에 넣기"}],"mis":"K3-2-u3-X08","explanation":["교과서와 공책은 파일꽂이에 세워 꽂으면 쓰러지지 않아요.","자주 쓰는 작은 물건은 정리 바구니에 담아요.","리코더는 정리 주머니에 넣어 깨끗하게 써요."],"asset":{"type":"passage","lines":["세워 두기 — 교과서, 공책은 세워서 꽂는다. 파일꽂이를 쓰면 쓰러지지 않는다.","정리 주머니에 넣어 두기 — 리코더는 정리 주머니에 넣어 깨끗하게 쓴다.","담아 두기 — 자주 쓰는 색연필과 자, 휴지는 정리 바구니 안에 담는다.","■ 출처: 「학교 사물함을 정리하는 방법」, 오늘의 어린이.","사용 횟수에 따라 분류하기 — 다 쓴 공책, 완성한 작품은 집으로 가져간다.","여분 갖추기 — 연필, 지우개, 풀, 공책, 휴지는 여분을 미리 준비해 둔다.","■ 출처: 「개인 사물함 정리하기」, ‘정리의 달인’ 누리 소통망."],"title":"다영이가 조사한 자료 — 『국어』 133쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_basic#3','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C16',1,'blank','auto','『국어』 136쪽에 나온 말이에요. 「조사한 자료가 있으면 출처를 글의 (     )에 밝혀야 해요. 그림이나 사진 자료도 출처를 밝혀요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X04']::text[],false,'{"seq":3,"concept":"K3-2-u3-C16","difficulty":1,"kind":"blank","stem":"『국어』 136쪽에 나온 말이에요. 「조사한 자료가 있으면 출처를 글의 (     )에 밝혀야 해요. 그림이나 사진 자료도 출처를 밝혀요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"맨 끝","correct":true},{"t":"맨 앞","mis":"K3-2-u3-X04"},{"t":"제목 안","mis":"K3-2-u3-X04"}],"explanation":["조사한 자료의 출처는 글의 맨 끝에 밝혀요.","예시 글에도 맨 끝에 「■ 출처」가 두 줄 있어요.","그림이나 사진 자료도 출처를 밝혀요."],"asset":{"type":"passage","lines":["(처음) 개인 사물함에 물건이 가지런히 정돈되어 있으면","공부할 때 필요한 물건을 편리하게 찾아 쓸 수 있습니다.","먼저, 사물함에 보관할 물건을 종류에 따라 분류합니다.","다음으로, 분류한 물건들을 모양이나 쓸모, 사용 횟수에 따라 정돈합니다.","(간추림) 교과서·공책은 파일꽂이에 세우고, 색연필·자·휴지는 정리 바구니에 넣는다.","(끝) 분류하고 정리 도구를 사용하여 보관하면 필요한 물건을 쉽게 찾을 수 있습니다.","■ 출처: 「학교 사물함을 정리하는 방법」, 오늘의 어린이.","■ 출처: 「개인 사물함 정리하기」, ‘정리의 달인’ 누리 소통망."],"title":"설명하는 글 「개인 사물함을 정리하는 방법」 — 『국어』 136쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_basic#4','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C18',1,'ox','auto','『국어』 137쪽처럼 쓴 글을 다시 읽고 점검하는 것은 점수를 매기기 위해서예요.',ARRAY['K3-2-u3-X26']::text[],false,'{"seq":4,"concept":"K3-2-u3-C18","difficulty":1,"kind":"ox","stem":"『국어』 137쪽처럼 쓴 글을 다시 읽고 점검하는 것은 점수를 매기기 위해서예요.","answer":"X","reason_options":[{"t":"고칠 부분이 있는지 찾아 더 알기 쉬운 글로 고치려는 거예요.","correct":true},{"t":"친구 글과 견주어 몇 점인지 매기려는 거예요.","mis":"K3-2-u3-X26"}],"mis":"K3-2-u3-X26","explanation":["점검은 고치려고 하는 일이에요.","일의 순서, 읽는 사람이 궁금해할 내용, 바른 문장, 이어 주는 말을 살펴요.","찾은 부분을 고쳐 더 좋은 글로 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_basic#5','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C17',2,'mc','auto','「개인 사물함을 정리하는 방법」의 가운데 부분에 들어갈 내용이 아닌 것은 무엇인가요?',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":5,"concept":"K3-2-u3-C17","difficulty":2,"kind":"mc","stem":"「개인 사물함을 정리하는 방법」의 가운데 부분에 들어갈 내용이 아닌 것은 무엇인가요?","options":[{"t":"종류에 따라 분류하고 정리 도구로 보관하면 편리하다는 간추림","correct":true},{"t":"물건을 종류에 따라 분류하기","mis":"K3-2-u3-X25"},{"t":"교과서와 공책은 파일꽂이를 사용해 세워 두기","mis":"K3-2-u3-X25"},{"t":"색연필, 자, 휴지는 정리 바구니에 넣어 두기","mis":"K3-2-u3-X25"}],"explanation":["가운데 부분에는 일의 순서나 방법을 써요.","설명한 내용을 간추리는 것은 끝부분이에요.","처음·가운데·끝에 들어갈 내용을 가려 써요."],"asset":{"type":"passage","lines":["제목 — 개인 사물함을 정리하는 방법","처음(글을 쓰는 목적) — 개인 사물함을 정리하는 방법 설명하기","가운데(일의 순서나 방법) — 물건을 종류에 따라 분류하기","가운데 — 교과서와 공책은 파일꽂이를 사용해 세워 두기","가운데 — 자주 쓰는 색연필, 자, 휴지는 정리 바구니에 넣어 두기","가운데 — 참고한 자료의 출처 쓰기","끝(설명한 내용 간추리기) — 분류하고 정리 도구로 보관하면 편리함"],"title":"쓸 내용 정리하기 — 『국어』 135쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_basic#6','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C18',2,'mc','auto','『국어』 137쪽 점검하기에서 스스로 확인하는 물음이 아닌 것은 무엇인가요?',ARRAY['K3-2-u3-X26']::text[],false,'{"seq":6,"concept":"K3-2-u3-C18","difficulty":2,"kind":"mc","stem":"『국어』 137쪽 점검하기에서 스스로 확인하는 물음이 아닌 것은 무엇인가요?","options":[{"t":"글씨를 크고 진하게 썼나요?","correct":true},{"t":"일의 순서나 방법이 잘 드러나게 썼나요?","mis":"K3-2-u3-X26"},{"t":"읽는 사람이 궁금해할 내용으로 썼나요?","mis":"K3-2-u3-X26"},{"t":"이어 주는 말을 적절하게 사용했나요?","mis":"K3-2-u3-X26"}],"explanation":["점검하는 물음은 넷이에요.","일의 순서나 방법 · 읽는 사람이 궁금해할 내용 · 바르고 정확한 문장 · 이어 주는 말이에요.","글씨의 크기는 점검 물음이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_basic#7','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C17',2,'mc','auto','다영이가 조사한 자료를 보고 답해요. 「공부 시간에 완성한 작품」은 어떻게 정리하나요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":7,"concept":"K3-2-u3-C17","difficulty":2,"kind":"mc","stem":"다영이가 조사한 자료를 보고 답해요. 「공부 시간에 완성한 작품」은 어떻게 정리하나요?","options":[{"t":"분류해서 집으로 가져가기","correct":true},{"t":"정리 바구니에 담기","mis":"K3-2-u3-X08"},{"t":"여분 갖추기","mis":"K3-2-u3-X08"},{"t":"파일꽂이에 세워 꽂기","mis":"K3-2-u3-X08"}],"explanation":["사용 횟수에 따라 계속 쓸 것과 더 쓰지 않을 것으로 분류해요.","완성한 작품, 다 쓴 공책은 집으로 가져가요.","자료를 꼼꼼히 읽고 쓸 내용을 정해요."],"asset":{"type":"passage","lines":["세워 두기 — 교과서, 공책은 세워서 꽂는다. 파일꽂이를 쓰면 쓰러지지 않는다.","정리 주머니에 넣어 두기 — 리코더는 정리 주머니에 넣어 깨끗하게 쓴다.","담아 두기 — 자주 쓰는 색연필과 자, 휴지는 정리 바구니 안에 담는다.","■ 출처: 「학교 사물함을 정리하는 방법」, 오늘의 어린이.","사용 횟수에 따라 분류하기 — 다 쓴 공책, 완성한 작품은 집으로 가져간다.","여분 갖추기 — 연필, 지우개, 풀, 공책, 휴지는 여분을 미리 준비해 둔다.","■ 출처: 「개인 사물함 정리하기」, ‘정리의 달인’ 누리 소통망."],"title":"다영이가 조사한 자료 — 『국어』 133쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_basic#8','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C17',2,'error','auto','『국어』 134쪽 (2)처럼 읽는 사람을 생각해 쓸 내용을 정했는지 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X21','K3-2-u3-X22','K3-2-u3-X35']::text[],false,'{"seq":8,"concept":"K3-2-u3-C17","difficulty":2,"kind":"error","stem":"『국어』 134쪽 (2)처럼 읽는 사람을 생각해 쓸 내용을 정했는지 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태린: 정리에 관한 어려운 낱말을 많이 써야 읽는 사람이 감탄해.","correct":true,"mis_target":"K3-2-u3-X21"},{"t":"주안: 일의 순서를 나타내는 말을 사용해서 설명하면 이해하기 쉬워.","mis":"K3-2-u3-X22"},{"t":"보람: 일을 하는 방법을 빠뜨리지 않고 쉽게 설명해야 해.","mis":"K3-2-u3-X35"}],"explanation":["설명하는 글은 읽는 사람이 알기 쉽게 써야 해요.","어려운 낱말을 많이 쓰면 이해하기 어려워져요.","순서를 나타내는 말을 쓰고, 방법을 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_basic#9','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C16',2,'sa','auto','다영이가 조사한 자료에서 「여분 갖추기」 내용의 출처인 누리 소통망 이름은 무엇인가요?','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C16","difficulty":2,"kind":"sa","stem":"다영이가 조사한 자료에서 「여분 갖추기」 내용의 출처인 누리 소통망 이름은 무엇인가요?","answer":["정리의 달인","‘정리의 달인’","정리의 달인 누리 소통망","‘정리의 달인’ 누리 소통망"],"explanation":["「여분 갖추기」 아래의 출처를 찾아요.","「■ 출처: 「개인 사물함 정리하기」, ‘정리의 달인’ 누리 소통망.」이에요.","글을 쓸 때 이 출처를 글의 맨 끝에 밝혀요."],"asset":{"type":"passage","lines":["세워 두기 — 교과서, 공책은 세워서 꽂는다. 파일꽂이를 쓰면 쓰러지지 않는다.","정리 주머니에 넣어 두기 — 리코더는 정리 주머니에 넣어 깨끗하게 쓴다.","담아 두기 — 자주 쓰는 색연필과 자, 휴지는 정리 바구니 안에 담는다.","■ 출처: 「학교 사물함을 정리하는 방법」, 오늘의 어린이.","사용 횟수에 따라 분류하기 — 다 쓴 공책, 완성한 작품은 집으로 가져간다.","여분 갖추기 — 연필, 지우개, 풀, 공책, 휴지는 여분을 미리 준비해 둔다.","■ 출처: 「개인 사물함 정리하기」, ‘정리의 달인’ 누리 소통망."],"title":"다영이가 조사한 자료 — 『국어』 133쪽 (간추림)"},"mis":"K3-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_basic#10','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C18',3,'mc','auto','두 친구가 사물함 정리 방법을 썼어요. 한 친구는 물건의 종류에 따라, 다른 친구는 물건을 쓰는 횟수에 따라 정리하는 방법을 썼어요. 어떻게 생각해야 할까요?',ARRAY['K3-2-u3-X27']::text[],false,'{"seq":10,"concept":"K3-2-u3-C18","difficulty":3,"kind":"mc","stem":"두 친구가 사물함 정리 방법을 썼어요. 한 친구는 물건의 종류에 따라, 다른 친구는 물건을 쓰는 횟수에 따라 정리하는 방법을 썼어요. 어떻게 생각해야 할까요?","options":[{"t":"두 글 모두 차례와 까닭이 드러나면 알맞은 글이다","correct":true},{"t":"종류에 따라 정리한 글만 맞다","mis":"K3-2-u3-X27"},{"t":"쓰는 횟수에 따라 정리한 글만 맞다","mis":"K3-2-u3-X27"},{"t":"방법이 서로 다르니 둘 다 틀렸다","mis":"K3-2-u3-X27"}],"explanation":["사물함은 종류와 크기로도, 사용 횟수로도 정리할 수 있어요.","같은 일도 방법이 다를 수 있어요.","차례와 까닭이 드러나면 둘 다 알맞은 설명하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_challenge#1','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C17',2,'mc','auto','개인 사물함을 정리하는 방법을 설명하는 글을 쓰려고 쓸 내용을 떠올려요. 무엇을 중심으로 계획하면 좋을까요?',ARRAY['K3-2-u3-X21','K3-2-u3-X06']::text[],false,'{"seq":1,"concept":"K3-2-u3-C17","difficulty":2,"kind":"mc","stem":"개인 사물함을 정리하는 방법을 설명하는 글을 쓰려고 쓸 내용을 떠올려요. 무엇을 중심으로 계획하면 좋을까요?","options":[{"t":"내가 능숙하게 할 수 있는 정리 방법","correct":true},{"t":"한 번도 해 보지 않은 어려운 방법","mis":"K3-2-u3-X21"},{"t":"친구 글에서 그대로 옮겨 온 방법","mis":"K3-2-u3-X06"}],"explanation":["먼저 능숙하게 할 수 있는 방법을 중심으로 계획해요.","잘 아는 방법이어야 차례를 빠뜨리지 않고 쓸 수 있어요.","조사한 자료는 확인하고 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_challenge#2','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C17',2,'blank','auto','설명하는 글을 쓰는 과정이에요. 「내용 떠올리기 → 내용 조직하기 → (     ) → 점검하기」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X20','K3-2-u3-X26']::text[],false,'{"seq":2,"concept":"K3-2-u3-C17","difficulty":2,"kind":"blank","stem":"설명하는 글을 쓰는 과정이에요. 「내용 떠올리기 → 내용 조직하기 → (     ) → 점검하기」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"글쓰기","correct":true},{"t":"꾸미기","mis":"K3-2-u3-X20"},{"t":"점수 매기기","mis":"K3-2-u3-X26"}],"explanation":["먼저 쓸 내용을 떠올리고 처음·가운데·끝으로 조직해요.","그다음에 글을 써요.","끝으로 쓴 글을 점검하고 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_challenge#3','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C15',3,'mc','auto','설명하는 글 「개인 사물함을 정리하는 방법」에서 일의 순서를 나타내는 말을 바르게 찾은 것은 무엇인가요?',ARRAY['K3-2-u3-X17','K3-2-u3-X16']::text[],false,'{"seq":3,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"설명하는 글 「개인 사물함을 정리하는 방법」에서 일의 순서를 나타내는 말을 바르게 찾은 것은 무엇인가요?","options":[{"t":"먼저, 다음으로","correct":true},{"t":"사물함, 물건","mis":"K3-2-u3-X17"},{"t":"공부할 때, 편리하게","mis":"K3-2-u3-X17"},{"t":"그래서, 그러나","mis":"K3-2-u3-X16"}],"explanation":["「먼저, 사물함에 보관할 물건을 종류에 따라 분류합니다.」라고 했어요.","「다음으로, 분류한 물건들을 … 정돈합니다.」라고 이어 썼어요.","순서를 나타내는 말이 일의 차례를 알려 줘요."],"asset":{"type":"passage","lines":["(처음) 개인 사물함에 물건이 가지런히 정돈되어 있으면","공부할 때 필요한 물건을 편리하게 찾아 쓸 수 있습니다.","먼저, 사물함에 보관할 물건을 종류에 따라 분류합니다.","다음으로, 분류한 물건들을 모양이나 쓸모, 사용 횟수에 따라 정돈합니다.","(간추림) 교과서·공책은 파일꽂이에 세우고, 색연필·자·휴지는 정리 바구니에 넣는다.","(끝) 분류하고 정리 도구를 사용하여 보관하면 필요한 물건을 쉽게 찾을 수 있습니다.","■ 출처: 「학교 사물함을 정리하는 방법」, 오늘의 어린이.","■ 출처: 「개인 사물함 정리하기」, ‘정리의 달인’ 누리 소통망."],"title":"설명하는 글 「개인 사물함을 정리하는 방법」 — 『국어』 136쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_challenge#4','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C18',3,'error','auto','친구들이 쓴 글을 점검했어요. 알맞게 점검하지 않은 친구는 누구인가요?',ARRAY['K3-2-u3-X26','K3-2-u3-X18']::text[],false,'{"seq":4,"concept":"K3-2-u3-C18","difficulty":3,"kind":"error","stem":"친구들이 쓴 글을 점검했어요. 알맞게 점검하지 않은 친구는 누구인가요?","options":[{"t":"라온: 문장이 열 개가 넘으니 잘 쓴 글이야.","correct":true,"mis_target":"K3-2-u3-X26"},{"t":"세아: 일의 순서가 잘 드러났는지 확인했어.","mis":"K3-2-u3-X26"},{"t":"호진: 이어 주는 말을 알맞게 썼는지 확인했어.","mis":"K3-2-u3-X18"}],"explanation":["점검은 문장 수를 세는 일이 아니에요.","일의 순서, 읽는 사람이 궁금해할 내용, 바른 문장, 이어 주는 말을 살펴요.","고칠 곳을 찾으려고 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_challenge#5','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C18',3,'mc','auto','한 친구가 가운데 부분에서 「물건을 종류에 따라 분류하기」를 빼고 바로 「정리 바구니에 넣기」를 썼어요. 무엇을 점검해야 할까요?',ARRAY['K3-2-u3-X01','K3-2-u3-X35','K3-2-u3-X04']::text[],false,'{"seq":5,"concept":"K3-2-u3-C18","difficulty":3,"kind":"mc","stem":"한 친구가 가운데 부분에서 「물건을 종류에 따라 분류하기」를 빼고 바로 「정리 바구니에 넣기」를 썼어요. 무엇을 점검해야 할까요?","options":[{"t":"중요한 순서를 빠뜨리지 않았는지","correct":true},{"t":"글씨가 바른지","mis":"K3-2-u3-X01"},{"t":"읽는 사람이 알아서 할 테니 그냥 두어도 되는지","mis":"K3-2-u3-X35"},{"t":"출처를 글의 맨 앞에 썼는지","mis":"K3-2-u3-X04"}],"explanation":["분류하기는 정리의 첫 단계예요.","중요한 순서를 빠뜨리면 읽는 사람이 따라 하기 어려워요.","쓴 글을 다시 읽으며 빠진 차례가 없는지 살펴요."],"asset":{"type":"passage","lines":["제목 — 개인 사물함을 정리하는 방법","처음(글을 쓰는 목적) — 개인 사물함을 정리하는 방법 설명하기","가운데(일의 순서나 방법) — 물건을 종류에 따라 분류하기","가운데 — 교과서와 공책은 파일꽂이를 사용해 세워 두기","가운데 — 자주 쓰는 색연필, 자, 휴지는 정리 바구니에 넣어 두기","가운데 — 참고한 자료의 출처 쓰기","끝(설명한 내용 간추리기) — 분류하고 정리 도구로 보관하면 편리함"],"title":"쓸 내용 정리하기 — 『국어』 135쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_challenge#6','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C17',3,'mc','auto','『국어』 137쪽 더 나아가기 예시 글처럼 양말을 정리하는 방법을 설명하려고 해요. 차례로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X35','K3-2-u3-X31']::text[],false,'{"seq":6,"concept":"K3-2-u3-C17","difficulty":3,"kind":"mc","stem":"『국어』 137쪽 더 나아가기 예시 글처럼 양말을 정리하는 방법을 설명하려고 해요. 차례로 알맞은 것은 무엇인가요?","options":[{"t":"길이·색깔·두께로 나누기 → 반으로 접거나 말기 → 칸막이 정리함에 넣기","correct":true},{"t":"칸막이 정리함에 넣기 → 길이·색깔·두께로 나누기 → 반으로 접거나 말기","mis":"K3-2-u3-X22"},{"t":"반으로 접거나 말기 → 칸막이 정리함에 넣기","mis":"K3-2-u3-X35"},{"t":"양말을 신었을 때의 느낌 쓰기","mis":"K3-2-u3-X31"}],"explanation":["먼저 양말목의 길이, 색깔, 두께로 나누어요.","다음으로 반으로 접거나 말아요.","끝으로 칸막이가 있는 정리함에 넣으면 편리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_challenge#7','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C15',3,'mc','auto','「종이접기로 고깔모자를 만드는 방법」에서 ② 다음에 할 일은 무엇인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X35']::text[],false,'{"seq":7,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"「종이접기로 고깔모자를 만드는 방법」에서 ② 다음에 할 일은 무엇인가요?","options":[{"t":"양쪽 모서리를 삼각형 모양이 되도록 마주 접는다","correct":true},{"t":"모자의 중간 부분을 적당히 열어 준다","mis":"K3-2-u3-X22"},{"t":"색종이의 중심선에 맞추어 양옆을 마주 접은 뒤 뒤집는다","mis":"K3-2-u3-X22"},{"t":"아래쪽을 한 번 더 위로 접어 올린다","mis":"K3-2-u3-X35"}],"explanation":["번호가 일의 차례를 알려 줘요.","②「아래로 반을 내려 접습니다.」 다음은 ③이에요.","중요한 순서를 빠뜨리지 않아야 모자를 만들 수 있어요."],"asset":{"type":"passage","lines":["준비물: 색종이 한 장 (신문지나 큰 도화지로 만들면 더 큰 모자)","① 색종이의 중심선에 맞추어 양옆을 마주 접은 뒤 뒤집어 줍니다.","② 아래로 반을 내려 접습니다.","③ 양쪽 모서리를 삼각형 모양이 되도록 마주 접습니다.","④ 아래쪽을 삼각형으로 접은 선 아래까지 접습니다.","⑤ 아래쪽을 한 번 더 위로 접어 올립니다. 뒤집어서 반대쪽도 똑같이 접습니다.","⑥ 모자의 중간 부분을 적당히 열어 줍니다."],"title":"「종이접기로 고깔모자를 만드는 방법」 — 『국어활동』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_challenge#8','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C17',4,'essay','teacher','개인 사물함을 정리하는 방법을 설명하는 글을 쓰세요. 처음·가운데·끝으로 나누고, 순서를 나타내는 말을 쓰고, 조사한 자료가 있다면 출처를 글의 맨 끝에 밝히세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u3-C17","difficulty":4,"kind":"essay","stem":"개인 사물함을 정리하는 방법을 설명하는 글을 쓰세요. 처음·가운데·끝으로 나누고, 순서를 나타내는 말을 쓰고, 조사한 자료가 있다면 출처를 글의 맨 끝에 밝히세요.","answer_guide":{"answer":"예: (처음) 개인 사물함을 정리하는 방법을 알아봅시다. (가운데) 먼저, 물건을 종류에 따라 나눕니다. 다음으로, 교과서와 공책은 파일꽂이에 세워 둡니다. 끝으로, 색연필과 자는 정리 바구니에 넣습니다. (끝) 이렇게 정리하면 필요한 물건을 쉽게 찾을 수 있습니다. ■ 출처: 「학교 사물함을 정리하는 방법」, 오늘의 어린이.","scoring_points":["처음·가운데·끝으로 나누어 썼는가","순서를 나타내는 말로 일의 차례를 드러냈는가","조사한 자료의 출처를 글의 맨 끝에 밝혔는가"]},"explanation":["처음에는 무엇을 설명할지, 가운데에는 순서와 방법, 끝에는 간추림을 써요.","‘먼저, 다음으로, 끝으로’로 차례를 드러내요.","조사한 자료는 출처를 맨 끝에 밝혀요."],"asset":{"type":"passage","lines":["세워 두기 — 교과서, 공책은 세워서 꽂는다. 파일꽂이를 쓰면 쓰러지지 않는다.","정리 주머니에 넣어 두기 — 리코더는 정리 주머니에 넣어 깨끗하게 쓴다.","담아 두기 — 자주 쓰는 색연필과 자, 휴지는 정리 바구니 안에 담는다.","■ 출처: 「학교 사물함을 정리하는 방법」, 오늘의 어린이.","사용 횟수에 따라 분류하기 — 다 쓴 공책, 완성한 작품은 집으로 가져간다.","여분 갖추기 — 연필, 지우개, 풀, 공책, 휴지는 여분을 미리 준비해 둔다.","■ 출처: 「개인 사물함 정리하기」, ‘정리의 달인’ 누리 소통망."],"title":"다영이가 조사한 자료 — 『국어』 133쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_challenge#9','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C18',4,'essay','teacher','친구가 처음 쓴 글 「책상 서랍 정리하는 방법」을 『국어』 137쪽 점검 물음으로 살펴보고, 고칠 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C18","difficulty":4,"kind":"essay","stem":"친구가 처음 쓴 글 「책상 서랍 정리하는 방법」을 『국어』 137쪽 점검 물음으로 살펴보고, 고칠 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 일의 순서가 잘 드러나지 않는다 — ‘먼저, 다음으로, 끝으로’를 넣고 서랍을 비우는 단계부터 차례대로 쓴다. 이어 주는 말이 알맞지 않다 — 「그래서 공책을 넣어요」는 앞이 이유가 아니므로 ‘그다음에’로 고친다.","scoring_points":["점검 물음에 비추어 문제를 찾았는가","고칠 점을 두 가지 썼는가","어떻게 고칠지 구체적으로 썼는가"]},"explanation":["일의 순서나 방법이 잘 드러났는지 살펴요.","이어 주는 말이 앞뒤 관계에 맞는지 살펴요.","찾은 문제는 어떻게 고칠지까지 써요."],"asset":{"type":"passage","lines":["책상 서랍을 정리해요.","필요 없는 것은 버려요.","그래서 공책을 넣어요.","끝."],"title":"친구가 처음 쓴 글 「책상 서랍 정리하는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L10_challenge#10','kor',3,2,'u3','L10','tb_g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C17',4,'essay','teacher','『국어』 137쪽 더 나아가기처럼 양말을 정리하는 방법을 우리 반 친구들에게 설명하는 글을 쓰세요. 제목을 쓰고 일의 순서가 드러나게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C17","difficulty":4,"kind":"essay","stem":"『국어』 137쪽 더 나아가기처럼 양말을 정리하는 방법을 우리 반 친구들에게 설명하는 글을 쓰세요. 제목을 쓰고 일의 순서가 드러나게 쓰세요.","answer_guide":{"answer":"예: 제목 — 양말을 정리하는 방법. 먼저, 양말을 양말목의 길이와 색깔, 두께에 따라 나눕니다. 다음으로, 양말을 반으로 접거나 말아 둡니다. 끝으로, 칸막이가 있는 정리함에 넣으면 꺼내 쓰기 편리합니다.","scoring_points":["제목을 썼는가","일의 순서가 드러나게 썼는가","읽는 사람이 따라 할 수 있게 방법을 썼는가"]},"explanation":["자신이 잘 알고 있는 방법으로 써요.","순서를 나타내는 말을 쓰면 차례가 잘 드러나요.","방법을 몰랐던 친구도 따라 할 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_basic#1','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C19',1,'mc','auto','『국어』 139쪽 대중교통 이용 설명서 만들기에서 모둠이 고를 수 있는 대중교통이 아닌 것은 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":1,"concept":"K3-2-u3-C19","difficulty":1,"kind":"mc","stem":"『국어』 139쪽 대중교통 이용 설명서 만들기에서 모둠이 고를 수 있는 대중교통이 아닌 것은 무엇인가요?","options":[{"t":"자전거","correct":true},{"t":"여객선","mis":"K3-2-u3-X08"},{"t":"비행기","mis":"K3-2-u3-X08"},{"t":"기차, 지하철","mis":"K3-2-u3-X08"}],"explanation":["『국어』 139쪽에는 버스, 기차·지하철, 비행기, 여객선이 나와요.","여럿이 함께 타는 탈것이 대중교통이에요.","친구들이 알고 싶어 할 대중교통을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_basic#2','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C20',1,'sa','auto','『국어』 142쪽 기초 다지기예요. 「내가 읽어 보니 그 책 정말 (재미있데, 재미있대)!」 알맞은 말을 골라 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u3-C20","difficulty":1,"kind":"sa","stem":"『국어』 142쪽 기초 다지기예요. 「내가 읽어 보니 그 책 정말 (재미있데, 재미있대)!」 알맞은 말을 골라 쓰세요.","answer":["재미있데"],"explanation":["말하는 사람이 직접 읽어 보고 안 것이에요.","과거에 직접 경험한 내용을 말할 때는 ‘-데’를 써요.","그래서 「재미있데」가 알맞아요."],"mis":"K3-2-u3-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_basic#3','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C20',1,'blank','auto','『국어』 142쪽 기초 다지기예요. 「현지가 왜 아직 오지 않았지?」 「현지는 감기에 걸려 못 (     ).」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":3,"concept":"K3-2-u3-C20","difficulty":1,"kind":"blank","stem":"『국어』 142쪽 기초 다지기예요. 「현지가 왜 아직 오지 않았지?」 「현지는 감기에 걸려 못 (     ).」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"온대","correct":true},{"t":"온데","mis":"K3-2-u3-X29"},{"t":"왔데","mis":"K3-2-u3-X29"}],"explanation":["현지가 감기에 걸렸다는 말을 다른 사람에게 듣고 전하는 상황이에요.","남의 말을 전할 때는 ‘-대’를 써요.","‘온대’는 ‘온다고 해’가 줄어든 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_basic#4','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C21',1,'mc','auto','『국어』 142쪽 낱말 그물 보기예요. 「자전거」에서 「준비물」로 뻗은 말은 무엇인가요?',ARRAY['K3-2-u3-X30']::text[],false,'{"seq":4,"concept":"K3-2-u3-C21","difficulty":1,"kind":"mc","stem":"『국어』 142쪽 낱말 그물 보기예요. 「자전거」에서 「준비물」로 뻗은 말은 무엇인가요?","options":[{"t":"안전모","correct":true},{"t":"균형 잡기","mis":"K3-2-u3-X30"},{"t":"건강","mis":"K3-2-u3-X30"},{"t":"공원","mis":"K3-2-u3-X30"}],"explanation":["균형 잡기는 방법, 건강은 좋은 점, 공원은 장소예요.","자전거를 탈 때 준비할 것은 안전모예요.","한 낱말에서 여러 갈래로 떠오르는 말이 뻗어 나가요."],"asset":{"type":"passage","lines":["가운데 낱말: 자전거","방법 → 균형 잡기","준비물 → 안전모","좋은 점 → 건강","장소 → 공원"],"title":"보기 — 낱말 그물, 『국어』 142쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_basic#5','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C21',2,'match','auto','『국어』 142쪽처럼 「여행」으로 낱말 그물을 만들었어요. 갈래와 떠오른 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u3-C21","difficulty":2,"kind":"match","stem":"『국어』 142쪽처럼 「여행」으로 낱말 그물을 만들었어요. 갈래와 떠오른 말을 알맞게 이으세요.","pairs":[{"l":"방법","r":"기차 여행"},{"l":"준비물","r":"가방"},{"l":"좋은 점","r":"즐거움"},{"l":"장소","r":"관광지"}],"mis":"K3-2-u3-X30","explanation":["기차를 타고 가는 것은 여행하는 방법이에요.","가방은 준비물, 즐거움은 좋은 점이에요.","관광지는 여행하는 장소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_basic#6','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C19',2,'mc','auto','기차 이용 설명서를 모둠에서 나누어 쓰기로 했어요. 둘째 문단을 쓰는 친구가 기차를 이용하는 차례를 생각했어요. 둘째 문단에 쓸 내용으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":6,"concept":"K3-2-u3-C19","difficulty":2,"kind":"mc","stem":"기차 이용 설명서를 모둠에서 나누어 쓰기로 했어요. 둘째 문단을 쓰는 친구가 기차를 이용하는 차례를 생각했어요. 둘째 문단에 쓸 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"기차를 타기 전에 해야 하는 일","correct":true},{"t":"기차의 특징","mis":"K3-2-u3-X25"},{"t":"기차를 탈 때 주의할 점","mis":"K3-2-u3-X25"},{"t":"기차 이용 방법","mis":"K3-2-u3-X25"}],"explanation":["첫째 문단은 기차의 특징, 셋째는 이용 방법, 마지막은 주의할 점이에요.","이용하는 차례로 보면 타기 전에 할 일이 둘째에 와요.","문단마다 중심 내용을 나누어 맡아 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나는 첫째 문단에 기차의 특징을 쓸 거야."},{"who":"친구 2","text":"나는 둘째 문단을 쓸 거야. 기차를 이용하는 차례를 생각해 볼게."},{"who":"친구 3","text":"나는 셋째 문단에 기차 이용 방법을 쓸 거야."},{"who":"친구 4","text":"나는 마지막 문단에 기차를 탈 때 주의할 점을 쓸 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_basic#7','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C19',2,'mc','auto','대중교통에 대한 자료를 조사했는데 사진, 글, 동영상처럼 자료의 종류가 여러 가지예요. 출처는 어떻게 써야 할까요?',ARRAY['K3-2-u3-X28','K3-2-u3-X23']::text[],false,'{"seq":7,"concept":"K3-2-u3-C19","difficulty":2,"kind":"mc","stem":"대중교통에 대한 자료를 조사했는데 사진, 글, 동영상처럼 자료의 종류가 여러 가지예요. 출처는 어떻게 써야 할까요?","options":[{"t":"종류가 달라도 그 자료를 가져온 곳을 똑같이 적는다","correct":true},{"t":"사진과 동영상은 출처를 적지 않아도 된다","mis":"K3-2-u3-X28"},{"t":"글로 된 자료만 출처를 적는다","mis":"K3-2-u3-X28"},{"t":"기억나지 않으면 비슷한 이름을 적는다","mis":"K3-2-u3-X23"}],"explanation":["출처는 그 자료를 가져온 곳이에요.","사진, 글, 동영상처럼 종류가 달라도 출처를 밝혀요.","기억나지 않으면 다시 찾아 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_basic#8','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C12',2,'mc','auto','‘이어 주는 말’ 놀이를 해요. 상황 카드 「학교 운동장에 새로운 놀이터가 만들어졌습니다.」와 이어 주는 말 카드 「그래서」를 뽑았어요. 뒤 문장으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X19']::text[],false,'{"seq":8,"concept":"K3-2-u3-C12","difficulty":2,"kind":"mc","stem":"‘이어 주는 말’ 놀이를 해요. 상황 카드 「학교 운동장에 새로운 놀이터가 만들어졌습니다.」와 이어 주는 말 카드 「그래서」를 뽑았어요. 뒤 문장으로 알맞은 것은 무엇인가요?","options":[{"t":"그래서 쉬는 시간마다 친구들이 놀이터로 달려갑니다.","correct":true},{"t":"그래서 놀이터는 오래되어 낡았습니다.","mis":"K3-2-u3-X16"},{"t":"그래서 어제는 비가 많이 왔습니다.","mis":"K3-2-u3-X19"}],"explanation":["새 놀이터가 생긴 것이 뒤 문장의 이유가 되어야 해요.","새 놀이터가 생겨서 친구들이 달려간다는 내용이 어울려요.","있을 만한 이야기로 뒤 문장을 만들어요."],"asset":{"type":"passage","lines":["① 가위바위보로 순서를 정한다.","② 모둠별로 상황 카드와 이어 주는 말 카드를 모아 뒤집어 쌓아 놓는다.","③ 첫 번째 사람은 상황 카드 한 장과 이어 주는 말 카드 한 장을 뽑는다.","④ 이어 주는 말과 어울리도록 뒤 문장을 만든다.","⑤ 모둠원이 돌아가며 문장을 만든다.","[상황 카드] 학교 운동장에 새로운 놀이터가 만들어졌습니다."],"title":"‘이어 주는 말’ 놀이 — 『국어』 138쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_basic#9','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C12',2,'blank','auto','같은 상황 카드 「학교 운동장에 새로운 놀이터가 만들어졌습니다.」 뒤에 「(     ) 아직 그네는 다 만들어지지 않았습니다.」를 이었어요. 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":9,"concept":"K3-2-u3-C12","difficulty":2,"kind":"blank","stem":"같은 상황 카드 「학교 운동장에 새로운 놀이터가 만들어졌습니다.」 뒤에 「(     ) 아직 그네는 다 만들어지지 않았습니다.」를 이었어요. 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그러나","correct":true},{"t":"그래서","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["놀이터가 만들어졌다는 내용과 그네가 아직이라는 내용은 서로 반대예요.","앞의 내용과 반대되는 내용이 이어질 때 ‘그러나’를 써요.","뽑은 이어 주는 말의 쓰임을 생각하며 문장을 만들어요."],"asset":{"type":"passage","lines":["① 가위바위보로 순서를 정한다.","② 모둠별로 상황 카드와 이어 주는 말 카드를 모아 뒤집어 쌓아 놓는다.","③ 첫 번째 사람은 상황 카드 한 장과 이어 주는 말 카드 한 장을 뽑는다.","④ 이어 주는 말과 어울리도록 뒤 문장을 만든다.","⑤ 모둠원이 돌아가며 문장을 만든다.","[상황 카드] 학교 운동장에 새로운 놀이터가 만들어졌습니다."],"title":"‘이어 주는 말’ 놀이 — 『국어』 138쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_basic#10','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C20',3,'error','auto','‘-데’와 ‘-대’를 써서 말했어요. 바르게 쓰지 않은 친구는 누구인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":10,"concept":"K3-2-u3-C20","difficulty":3,"kind":"error","stem":"‘-데’와 ‘-대’를 써서 말했어요. 바르게 쓰지 않은 친구는 누구인가요?","options":[{"t":"민서: 어제 내가 직접 가서 먹어 보니 그 식당 음식이 정말 맛있대.","correct":true,"mis_target":"K3-2-u3-X29"},{"t":"수아: 선생님께서 내일 비가 온다고 하셨어. 내일 비가 온대.","mis":"K3-2-u3-X29"},{"t":"건우: 내가 먹어 보니 그 떡볶이 정말 맵데.","mis":"K3-2-u3-X29"}],"explanation":["민서는 직접 먹어 보고 안 것을 말하고 있어요.","직접 경험한 것은 ‘맛있데’처럼 ‘-데’를 써야 해요.","수아처럼 남의 말을 전할 때는 ‘-대’를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_challenge#1','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C19',2,'mc','auto','모둠원이 각자 맡은 문단을 써서 대중교통 이용 설명서를 하나의 글로 모았어요. 그다음에 할 일은 무엇인가요?',ARRAY['K3-2-u3-X25','K3-2-u3-X01']::text[],false,'{"seq":1,"concept":"K3-2-u3-C19","difficulty":2,"kind":"mc","stem":"모둠원이 각자 맡은 문단을 써서 대중교통 이용 설명서를 하나의 글로 모았어요. 그다음에 할 일은 무엇인가요?","options":[{"t":"모아서 읽어 보고 부족하거나 어색한 부분을 찾아 다시 쓴다","correct":true},{"t":"각자 쓴 문단을 고치지 않고 붙이기만 한다","mis":"K3-2-u3-X25"},{"t":"가장 긴 문단만 남기고 나머지는 지운다","mis":"K3-2-u3-X01"}],"explanation":["하나의 글로 모은 뒤 처음부터 끝까지 읽어 봐요.","빠진 차례나 어색하게 이어지는 부분을 찾아요.","고쳐 쓴 글은 학급 알림판에 붙여 함께 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_challenge#2','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C20',2,'blank','auto','『국어』 142쪽에 나온 말이에요. 「‘-대’는 남의 말을 (     ) 때 써요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":2,"concept":"K3-2-u3-C20","difficulty":2,"kind":"blank","stem":"『국어』 142쪽에 나온 말이에요. 「‘-대’는 남의 말을 (     ) 때 써요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"전달할","correct":true},{"t":"직접 경험할","mis":"K3-2-u3-X29"},{"t":"혼자 생각할","mis":"K3-2-u3-X29"}],"explanation":["‘-대’는 남의 말을 전달할 때 써요.","‘-데’는 말하는 사람이 과거에 직접 경험한 내용일 때 써요.","‘보니’가 붙었는지가 아니라 누가 겪었는지로 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_challenge#3','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C17',3,'mc','auto','친구들과 하고 싶은 놀이를 설명하는 자료를 만들어요. 「가위바위보로 술래를 정한다 → 술래가 눈을 감고 열을 센다 → 친구들이 숨는다」는 어느 칸에 써야 할까요?',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":3,"concept":"K3-2-u3-C17","difficulty":3,"kind":"mc","stem":"친구들과 하고 싶은 놀이를 설명하는 자료를 만들어요. 「가위바위보로 술래를 정한다 → 술래가 눈을 감고 열을 센다 → 친구들이 숨는다」는 어느 칸에 써야 할까요?","options":[{"t":"놀이 방법을 순서대로 정리하기","correct":true},{"t":"친구들과 하고 싶은 까닭","mis":"K3-2-u3-X25"},{"t":"준비물 및 주의할 점","mis":"K3-2-u3-X25"},{"t":"놀이 이름","mis":"K3-2-u3-X25"}],"explanation":["「→」로 이어진 것은 놀이하는 차례예요.","차례는 「놀이 방법을 순서대로 정리하기」 칸에 써요.","칸마다 들어갈 내용을 가려 써야 읽는 사람이 알기 쉬워요."],"asset":{"type":"passage","lines":["놀이 이름","친구들과 하고 싶은 까닭","놀이 방법을 순서대로 정리하기","준비물 및 주의할 점"],"title":"친구들과 하고 싶은 놀이 설명하기 자료의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_challenge#4','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C15',3,'mc','auto','「한지 제기 만드는 방법」의 단계가 섞여 있어요. 두 번째 단계는 무엇인가요?',ARRAY['K3-2-u3-X22']::text[],false,'{"seq":4,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"「한지 제기 만드는 방법」의 단계가 섞여 있어요. 두 번째 단계는 무엇인가요?","options":[{"t":"㉣ 한지 가운데 아래쪽에 고리를 놓고 한지와 함께 돌돌 만다.","correct":true},{"t":"㉠ 연필로 고리 중심 부분에 한지와 함께 구멍을 뚫는다.","mis":"K3-2-u3-X22"},{"t":"㉢ 구멍에 한지의 양 끝을 넣어 고정하고, 끝을 잘게 찢는다.","mis":"K3-2-u3-X22"},{"t":"㉡ 한지 네다섯 장, 금속 연결 고리 한 개, 연필 하나를 준비한다.","mis":"K3-2-u3-X22"}],"explanation":["첫 번째는 준비물을 갖추는 일이에요.","두 번째에 고리를 놓고 한지를 돌돌 말아요.","그다음 구멍을 뚫고, 마지막에 양 끝을 넣어 고정해요."],"asset":{"type":"passage","lines":["㉠ 연필로 고리 중심 부분에 한지와 함께 구멍을 뚫는다.","㉡ 한지 네다섯 장, 금속 연결 고리 한 개, 연필 하나를 준비한다.","㉢ 구멍에 한지의 양 끝을 넣어 고정하고, 끝을 잘게 찢는다.","㉣ 한지 가운데 아래쪽에 고리를 놓고 한지와 함께 돌돌 만다."],"title":"「한지 제기 만드는 방법」 — 단계가 섞여 있음 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_challenge#5','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C15',3,'mc','auto','「한지 제기 만드는 방법」의 첫 번째 단계에는 「금속 연결 고리의 크기가 너무 작지 않은지 사용하기 전에 미리 확인해야 합니다.」라는 말도 있어요. 이 말을 쓴 까닭은 무엇일까요?',ARRAY['K3-2-u3-X01','K3-2-u3-X08','K3-2-u3-X31']::text[],false,'{"seq":5,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"「한지 제기 만드는 방법」의 첫 번째 단계에는 「금속 연결 고리의 크기가 너무 작지 않은지 사용하기 전에 미리 확인해야 합니다.」라는 말도 있어요. 이 말을 쓴 까닭은 무엇일까요?","options":[{"t":"한지 네다섯 장을 겹쳐 고리 안으로 넣어야 하니, 주의할 점을 미리 알려 주려고","correct":true},{"t":"글을 길어 보이게 하려고","mis":"K3-2-u3-X01"},{"t":"고리가 작을수록 제기가 잘 올라가서","mis":"K3-2-u3-X08"},{"t":"제기를 만들며 든 느낌을 나타내려고","mis":"K3-2-u3-X31"}],"explanation":["방법을 설명하는 글에는 주의할 점도 함께 써요.","고리가 작으면 한지를 넣을 수 없어요.","미리 알려 주면 읽는 사람이 실수하지 않아요."],"asset":{"type":"passage","lines":["㉠ 연필로 고리 중심 부분에 한지와 함께 구멍을 뚫는다.","㉡ 한지 네다섯 장, 금속 연결 고리 한 개, 연필 하나를 준비한다.","㉢ 구멍에 한지의 양 끝을 넣어 고정하고, 끝을 잘게 찢는다.","㉣ 한지 가운데 아래쪽에 고리를 놓고 한지와 함께 돌돌 만다."],"title":"「한지 제기 만드는 방법」 — 단계가 섞여 있음 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_challenge#6','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C21',3,'error','auto','「도서관」으로 낱말 그물을 만들었어요. 갈래와 떠오른 말을 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K3-2-u3-X30']::text[],false,'{"seq":6,"concept":"K3-2-u3-C21","difficulty":3,"kind":"error","stem":"「도서관」으로 낱말 그물을 만들었어요. 갈래와 떠오른 말을 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"하윤: 준비물 — 조용히 하기","correct":true,"mis_target":"K3-2-u3-X30"},{"t":"이준: 방법 — 빌린 책을 정해진 날까지 돌려주기","mis":"K3-2-u3-X30"},{"t":"다온: 좋은 점 — 여러 가지 책을 읽을 수 있음","mis":"K3-2-u3-X30"}],"explanation":["조용히 하기는 준비물이 아니라 도서관에서 지킬 일이에요.","준비물이라면 「빌린 책」이나 「도서 대출 카드」처럼 챙길 것이 와요.","갈래와 떠오른 말이 어울리는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_challenge#7','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C13',3,'mc','auto','‘이어 주는 말’ 놀이에서 상황 카드 「현장 체험학습 날 아침에 비가 많이 왔습니다.」와 「그러나」를 뽑았어요. 뒤 문장으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":7,"concept":"K3-2-u3-C13","difficulty":3,"kind":"mc","stem":"‘이어 주는 말’ 놀이에서 상황 카드 「현장 체험학습 날 아침에 비가 많이 왔습니다.」와 「그러나」를 뽑았어요. 뒤 문장으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그러나 낮이 되자 비가 그치고 해가 났습니다.","correct":true},{"t":"그러나 비 때문에 길이 많이 젖었습니다.","mis":"K3-2-u3-X16"},{"t":"그러나 우리는 비옷을 입고 우산도 챙겼습니다.","mis":"K3-2-u3-X16"}],"explanation":["‘그러나’ 뒤에는 앞과 반대되는 내용이 와야 해요.","비가 많이 왔다는 것과 비가 그치고 해가 났다는 것이 서로 반대예요.","비가 와서 길이 젖거나 우산을 챙긴 것은 앞의 결과라 ‘그래서’가 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_challenge#8','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C19',4,'essay','teacher','『국어』 139쪽처럼 대중교통 가운데 하나를 골라 이용 설명서를 계획하세요. 네 문단의 중심 내용과, 조사한 사진·글·동영상 자료의 출처를 어떻게 적을지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u3-C19","difficulty":4,"kind":"essay","stem":"『국어』 139쪽처럼 대중교통 가운데 하나를 골라 이용 설명서를 계획하세요. 네 문단의 중심 내용과, 조사한 사진·글·동영상 자료의 출처를 어떻게 적을지 쓰세요.","answer_guide":{"answer":"예: 대중교통 — 버스. 첫째 문단 — 버스의 특징. 둘째 문단 — 버스를 타기 전에 할 일(노선 확인, 교통 카드 준비). 셋째 문단 — 버스 이용 방법(앞문으로 타고 카드 대기, 내릴 때 하차 벨 누르기). 마지막 문단 — 주의할 점. 조사한 자료는 사진이든 글이든 동영상이든 가져온 곳을 자료 아래나 글 끝에 적는다.","scoring_points":["대중교통을 하나 골랐는가","네 문단의 중심 내용을 차례에 맞게 정했는가","자료의 종류와 상관없이 출처를 적는다고 썼는가"]},"explanation":["각 문단의 중심 문장은 모둠이 함께 정해요.","뒷받침하는 내용은 각자 조사해서 써요.","사진, 글, 동영상 모두 가져온 곳을 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_challenge#9','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C17',4,'essay','teacher','친구들과 하고 싶은 놀이를 하나 정해 놀이 설명하기 자료를 쓰세요. 놀이 이름, 하고 싶은 까닭, 놀이 방법(순서대로), 준비물 및 주의할 점을 모두 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C17","difficulty":4,"kind":"essay","stem":"친구들과 하고 싶은 놀이를 하나 정해 놀이 설명하기 자료를 쓰세요. 놀이 이름, 하고 싶은 까닭, 놀이 방법(순서대로), 준비물 및 주의할 점을 모두 쓰세요.","answer_guide":{"answer":"예: 놀이 이름 — 제기차기. 까닭 — 우리나라 전통놀이를 친구들과 즐기고 싶어서. 방법 — 가위바위보로 차는 순서를 정한다. 자기 차례가 되면 제기를 한 발이나 두 발로 번갈아 찬다. 제기를 가장 많이 찬 사람이 이긴다. 준비물 — 제기. 주의할 점 — 친구와 부딪치지 않게 넓은 곳에서 한다.","scoring_points":["놀이 이름과 하고 싶은 까닭을 썼는가","놀이 방법을 순서대로 썼는가","준비물과 주의할 점을 썼는가"]},"explanation":["놀이 방법은 순서를 빠뜨리지 않고 차례대로 써요.","준비물과 주의할 점도 꼭 알려 줘요.","친구가 읽고 그대로 놀 수 있게 써요."],"asset":{"type":"passage","lines":["놀이 이름","친구들과 하고 싶은 까닭","놀이 방법을 순서대로 정리하기","준비물 및 주의할 점"],"title":"친구들과 하고 싶은 놀이 설명하기 자료의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_L12_challenge#10','kor',3,2,'u3','L12','tb_g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C20',4,'essay','teacher','‘-데’를 쓴 문장과 ‘-대’를 쓴 문장을 하나씩 만들고, 각각 그 말을 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C20","difficulty":4,"kind":"essay","stem":"‘-데’를 쓴 문장과 ‘-대’를 쓴 문장을 하나씩 만들고, 각각 그 말을 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: ‘-데’ — 어제 가 보니 놀이터가 정말 넓데.(내가 직접 가서 보고 안 것이라서) ‘-대’ — 짝이 그러는데 내일 급식에 떡볶이가 나온대.(짝에게 들은 말을 전하는 것이라서)","scoring_points":["‘-데’를 쓴 문장을 바르게 만들었는가","‘-대’를 쓴 문장을 바르게 만들었는가","직접 경험과 남의 말 전달로 까닭을 밝혔는가"]},"explanation":["‘-데’는 내가 직접 겪어 안 것을 말할 때 써요.","‘-대’는 남의 말을 전할 때 써요.","누가 겪었는지를 생각하면 가릴 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#1','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C3',1,'mc','auto','출처에 들어가는 내용으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X03']::text[],false,'{"seq":1,"concept":"K3-2-u3-C3","difficulty":1,"kind":"mc","stem":"출처에 들어가는 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"자료를 만든 기관과 자료의 이름","correct":true},{"t":"글을 쓴 사람의 이름","mis":"K3-2-u3-X03"},{"t":"학급 신문을 만든 날짜","mis":"K3-2-u3-X03"},{"t":"글이 실린 쪽수","mis":"K3-2-u3-X03"}],"explanation":["출처는 가져온 자료가 어디에서 왔는지 알려 줘요.","자료를 만든 사람이나 기관, 자료의 이름이 들어가요.","글을 쓴 사람이나 날짜는 출처가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#2','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C4',1,'ox','auto','출처는 자료 아래에만 쓰고, 본문 글 속에는 밝힐 수 없어요.',ARRAY['K3-2-u3-X04']::text[],false,'{"seq":2,"concept":"K3-2-u3-C4","difficulty":1,"kind":"ox","stem":"출처는 자료 아래에만 쓰고, 본문 글 속에는 밝힐 수 없어요.","answer":"X","reason_options":[{"t":"「…에 따르면」처럼 본문 속에서 글로 출처를 밝히기도 해요.","correct":true},{"t":"출처는 「■ 출처」로만 쓰는 약속이라 글 속에는 쓸 수 없어요.","mis":"K3-2-u3-X04"}],"mis":"K3-2-u3-X04","explanation":["출처는 자료 아래에 따로 쓰기도 해요.","본문 속에 「…에 따르면」처럼 글로 나타내기도 해요.","출처를 찾을 때는 두 곳을 모두 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#3','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C12',1,'blank','auto','「어머니는 시장에 가서 과일을 사셨습니다. (     ) 맛있는 떡도 사셨습니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":3,"concept":"K3-2-u3-C12","difficulty":1,"kind":"blank","stem":"「어머니는 시장에 가서 과일을 사셨습니다. (     ) 맛있는 떡도 사셨습니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그리고","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그래서","mis":"K3-2-u3-X16"}],"explanation":["과일을 산 일에 떡을 산 일이 더해져요.","비슷한 내용이 연결되니 ‘그리고’를 써요.","‘떡도’의 ‘도’가 단서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#4','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C15',1,'ox','auto','『국어』 141쪽 표지판 ㉠ 「설명하는 글을 쓸 때에는 어려운 낱말을 많이 써야 한다.」는 알맞은 설명이에요.',ARRAY['K3-2-u3-X21']::text[],false,'{"seq":4,"concept":"K3-2-u3-C15","difficulty":1,"kind":"ox","stem":"『국어』 141쪽 표지판 ㉠ 「설명하는 글을 쓸 때에는 어려운 낱말을 많이 써야 한다.」는 알맞은 설명이에요.","answer":"X","reason_options":[{"t":"설명하는 글은 읽는 사람이 이해하기 쉬운 낱말로 써야 해요.","correct":true},{"t":"어려운 낱말이 많을수록 좋은 설명하는 글이에요.","mis":"K3-2-u3-X21"}],"mis":"K3-2-u3-X21","explanation":["길 찾기에서 ㉠ 표지판 쪽은 틀린 길이에요.","어려운 낱말은 쉬운 말로 풀어 써요.","수지도 ‘과열’, ‘합선’을 쉬운 말로 고쳤어요."],"asset":{"type":"passage","lines":["㉠ 설명하는 글을 쓸 때에는 어려운 낱말을 많이 써야 한다.","㉡ 이어 주는 말의 앞뒤 문장이 자연스럽게 연결되었는지 확인한다.","㉢ 설명하는 글에서는 ‘첫째’, ‘그다음에는’과 같은 말을 사용하면 이해하기 쉽다.","㉣ 자료의 출처를 보면 글의 내용이 믿을 만한지 확인할 수 있다."],"title":"스스로 확인하기 — 길에 선 표지판 넷, 『국어』 141쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#5','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C20',1,'mc','auto','‘-데’는 언제 쓰나요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":5,"concept":"K3-2-u3-C20","difficulty":1,"kind":"mc","stem":"‘-데’는 언제 쓰나요?","options":[{"t":"말하는 사람이 과거에 직접 경험한 내용을 말할 때","correct":true},{"t":"남의 말을 전할 때","mis":"K3-2-u3-X29"},{"t":"앞에 ‘보니’라는 말이 있을 때만","mis":"K3-2-u3-X29"}],"explanation":["‘-데’는 직접 경험한 내용을 말할 때 써요.","「내가 읽어 보니 그 책 정말 재미있데!」처럼 써요.","남의 말을 전할 때는 ‘-대’를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#6','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C21',1,'mc','auto','『국어』 142쪽 낱말 그물 보기에서 「자전거」의 「장소」로 뻗은 말은 무엇인가요?',ARRAY['K3-2-u3-X30']::text[],false,'{"seq":6,"concept":"K3-2-u3-C21","difficulty":1,"kind":"mc","stem":"『국어』 142쪽 낱말 그물 보기에서 「자전거」의 「장소」로 뻗은 말은 무엇인가요?","options":[{"t":"공원","correct":true},{"t":"안전모","mis":"K3-2-u3-X30"},{"t":"건강","mis":"K3-2-u3-X30"},{"t":"균형 잡기","mis":"K3-2-u3-X30"}],"explanation":["자전거를 타는 곳이 장소예요.","보기에서는 「공원」이 장소로 뻗어 있어요.","안전모는 준비물, 건강은 좋은 점, 균형 잡기는 방법이에요."],"asset":{"type":"passage","lines":["가운데 낱말: 자전거","방법 → 균형 잡기","준비물 → 안전모","좋은 점 → 건강","장소 → 공원"],"title":"보기 — 낱말 그물, 『국어』 142쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#7','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C14',1,'mc','auto','설명하는 글을 쓰기 전에 먼저 생각할 것을 바르게 묶은 것은 무엇인가요?',ARRAY['K3-2-u3-X20','K3-2-u3-X01']::text[],false,'{"seq":7,"concept":"K3-2-u3-C14","difficulty":1,"kind":"mc","stem":"설명하는 글을 쓰기 전에 먼저 생각할 것을 바르게 묶은 것은 무엇인가요?","options":[{"t":"읽는 사람, 글을 쓰는 목적, 꼭 들어가야 할 내용","correct":true},{"t":"글씨 색, 제목 크기, 그림 꾸미기","mis":"K3-2-u3-X20"},{"t":"글자 수, 문장 수, 쪽수","mis":"K3-2-u3-X01"}],"explanation":["『국어』 129쪽 3번에서 세 가지를 생각했어요.","읽는 사람, 글의 목적, 설명할 내용이에요.","꾸미는 일은 글을 다 쓴 뒤에 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#8','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C7',1,'mc','auto','『국어활동』 43쪽 더 알아보기예요. 출처가 분명하지 않은 자료는 어떤가요?',ARRAY['K3-2-u3-X10','K3-2-u3-X32']::text[],false,'{"seq":8,"concept":"K3-2-u3-C7","difficulty":1,"kind":"mc","stem":"『국어활동』 43쪽 더 알아보기예요. 출처가 분명하지 않은 자료는 어떤가요?","options":[{"t":"믿을 만한지 확인하기 어려워 글 전체의 신뢰도를 떨어뜨린다","correct":true},{"t":"글을 더 빨리 읽게 해 준다","mis":"K3-2-u3-X10"},{"t":"글 전체를 더 믿게 해 준다","mis":"K3-2-u3-X32"}],"explanation":["출처가 없으면 자료를 확인할 길이 없어요.","그래서 글 전체를 믿기 어려워져요.","자료가 있는 글을 읽을 때는 출처를 꼭 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#9','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C6',2,'mc','auto','『국어활동』 43쪽 (2)예요. 「글 (     )는 활용한 자료의 출처를 밝혔어.」 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X09']::text[],false,'{"seq":9,"concept":"K3-2-u3-C6","difficulty":2,"kind":"mc","stem":"『국어활동』 43쪽 (2)예요. 「글 (     )는 활용한 자료의 출처를 밝혔어.」 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"K3-2-u3-X09"},{"t":"가와 나 모두","mis":"K3-2-u3-X09"}],"explanation":["글 가는 「한국인 영양소 섭취 기준」을 출처로 밝혔어요.","글 나는 자료의 출처가 적혀 있지 않아요.","두 글 모두 글쓴이의 의견은 잘 드러나 있어요."],"asset":{"type":"passage","lines":["글 가 — 의견: 자신에게 필요한 만큼의 물을 충분히 마시자.","글 가 — 자료의 출처: 「한국인 영양소 섭취 기준」, 보건복지부·한국영양학회.","글 나 — 의견: 가장 안전하고 간편한 운동인 걷기를 규칙적으로 실천하자.","글 나 — 자료의 출처: (적혀 있지 않음)"],"title":"글 가와 글 나를 정리한 표 — 『국어활동』 43쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#10','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C12',2,'blank','auto','「아침부터 비가 거세게 온다. (     ) 나는 장화를 신고 학교에 간다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":10,"concept":"K3-2-u3-C12","difficulty":2,"kind":"blank","stem":"「아침부터 비가 거세게 온다. (     ) 나는 장화를 신고 학교에 간다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그래서","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["비가 거세게 오는 것이 장화를 신은 이유예요.","앞이 뒤의 이유가 되니 ‘그래서’를 써요.","앞뒤 문장을 ‘왜?’로 이어 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#11','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C17',2,'mc','auto','순서나 방법을 설명하는 글의 끝부분에 쓸 내용은 무엇인가요?',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":11,"concept":"K3-2-u3-C17","difficulty":2,"kind":"mc","stem":"순서나 방법을 설명하는 글의 끝부분에 쓸 내용은 무엇인가요?","options":[{"t":"설명한 내용 간추리기","correct":true},{"t":"무엇을 설명하는 글인지 밝히기","mis":"K3-2-u3-X25"},{"t":"일의 차례와 방법을 자세히 쓰기","mis":"K3-2-u3-X25"}],"explanation":["처음에는 무엇을 설명할지 밝혀요.","가운데에는 일의 순서와 방법을 자세히 써요.","끝에는 설명한 내용을 간추려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#12','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C11',2,'mc','auto','자료의 출처가 알맞은지 확인하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X14']::text[],false,'{"seq":12,"concept":"K3-2-u3-C11","difficulty":2,"kind":"mc","stem":"자료의 출처가 알맞은지 확인하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"출처에 적힌 누리집에 직접 들어가 그 자료가 있는지 본다","correct":true},{"t":"출처의 글씨가 크면 믿는다","mis":"K3-2-u3-X14"},{"t":"출처의 이름이 길면 믿는다","mis":"K3-2-u3-X14"}],"explanation":["적혀 있는 곳에 직접 가 보거나 누리집에 들어가 봐요.","그곳이 어떤 곳인지도 알아봐요.","이름이나 글씨 크기로 믿을 만한지 정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#13','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C15',2,'mc','auto','설명하는 글을 쓰는데 조사한 자료에 「과열」, 「합선」처럼 어려운 낱말이 있어요. 어떻게 하면 좋을까요?',ARRAY['K3-2-u3-X21','K3-2-u3-X35']::text[],false,'{"seq":13,"concept":"K3-2-u3-C15","difficulty":2,"kind":"mc","stem":"설명하는 글을 쓰는데 조사한 자료에 「과열」, 「합선」처럼 어려운 낱말이 있어요. 어떻게 하면 좋을까요?","options":[{"t":"읽는 사람이 이해하기 쉬운 낱말로 바꾸어 쓴다","correct":true},{"t":"어려울수록 멋있으니 그대로 쓴다","mis":"K3-2-u3-X21"},{"t":"뜻을 모르겠으면 그 규칙을 빼 버린다","mis":"K3-2-u3-X35"}],"explanation":["읽는 사람이 이해하기 어려운 낱말은 쉬운 말로 바꾸어요.","수지는 「한꺼번에 꽂으면 안 돼요」로 풀어 썼어요.","중요한 내용은 빼지 않고 쉽게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#14','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C16',2,'mc','auto','설명하는 글에 책에서 가져온 그림이나 사진 자료를 넣었어요. 출처는 어떻게 해야 할까요?',ARRAY['K3-2-u3-X28','K3-2-u3-X06']::text[],false,'{"seq":14,"concept":"K3-2-u3-C16","difficulty":2,"kind":"mc","stem":"설명하는 글에 책에서 가져온 그림이나 사진 자료를 넣었어요. 출처는 어떻게 해야 할까요?","options":[{"t":"그림이나 사진 자료도 출처를 밝힌다","correct":true},{"t":"그림과 사진은 출처가 필요 없다","mis":"K3-2-u3-X28"},{"t":"출처 대신 내 이름을 쓴다","mis":"K3-2-u3-X06"}],"explanation":["『국어』 136쪽에서 「그림이나 사진 자료도 출처를 밝혀요.」라고 했어요.","자료의 종류가 달라도 가져온 곳을 적어요.","내 이름은 출처가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#15','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C18',2,'mc','auto','점검 물음 「바르고 정확한 문장으로 썼나요?」를 살피는 까닭은 무엇인가요?',ARRAY['K3-2-u3-X26','K3-2-u3-X01']::text[],false,'{"seq":15,"concept":"K3-2-u3-C18","difficulty":2,"kind":"mc","stem":"점검 물음 「바르고 정확한 문장으로 썼나요?」를 살피는 까닭은 무엇인가요?","options":[{"t":"읽는 사람이 내용을 정확히 이해할 수 있게 고치려고","correct":true},{"t":"점수를 매기려고","mis":"K3-2-u3-X26"},{"t":"글자 수를 늘리려고","mis":"K3-2-u3-X01"}],"explanation":["점검은 고칠 곳을 찾으려고 해요.","문장이 바르고 정확해야 내용이 잘 전달돼요.","찾은 곳을 고쳐 더 좋은 글로 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#16','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C19',2,'mc','auto','『국어』 141쪽 생활 속으로에서 「가족과 함께 다녀왔던 곳을 찾아가는 방법을 친구들에게 글로 설명할 거야.」라고 했어요. 이 글에 꼭 들어갈 것은 무엇인가요?',ARRAY['K3-2-u3-X31','K3-2-u3-X35']::text[],false,'{"seq":16,"concept":"K3-2-u3-C19","difficulty":2,"kind":"mc","stem":"『국어』 141쪽 생활 속으로에서 「가족과 함께 다녀왔던 곳을 찾아가는 방법을 친구들에게 글로 설명할 거야.」라고 했어요. 이 글에 꼭 들어갈 것은 무엇인가요?","options":[{"t":"출발하는 곳부터 도착하는 곳까지 가는 차례","correct":true},{"t":"그곳에서 느낀 기분만","mis":"K3-2-u3-X31"},{"t":"그곳의 이름만","mis":"K3-2-u3-X35"}],"explanation":["찾아가는 방법을 설명하는 글이에요.","어디서 출발해 어떻게 가는지 차례대로 써야 해요.","읽는 친구가 그대로 따라갈 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#17','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C9',3,'mc','auto','평가 글 「유네스코 세종 대왕 문해상」을 읽고 답해요. 이 글이 설명하는 대상은 무엇인가요?',ARRAY['K3-2-u3-X34','K3-2-u3-X08']::text[],false,'{"seq":17,"concept":"K3-2-u3-C9","difficulty":3,"kind":"mc","stem":"평가 글 「유네스코 세종 대왕 문해상」을 읽고 답해요. 이 글이 설명하는 대상은 무엇인가요?","options":[{"t":"유네스코 세종 대왕 문해상","correct":true},{"t":"문화체육관광부","mis":"K3-2-u3-X34"},{"t":"세계 문해의 날","mis":"K3-2-u3-X08"},{"t":"한글날","mis":"K3-2-u3-X08"}],"explanation":["글의 제목과 가장 많이 쓰인 낱말을 생각해요.","이 글은 유네스코 세종 대왕 문해상을 설명해요.","문화체육관광부는 자료의 출처예요."],"asset":{"type":"passage","lines":["(간추림) 한국 정부가 유네스코에 제의해서 만든 ‘유네스코 세종 대왕 문해상’이 있다.","여기서 ‘문해’란 글을 읽고 이해한다는 뜻이에요.","(간추림) 글을 익히도록 도운 개인과 단체를 뽑아 세계 문해의 날(9월 8일)에 준다.","문화체육관광부의 보도 자료에 따르면, 1990년부터 2024년까지","전 세계 68개의 단체와 개인이 유네스코 세종 대왕 문해상을 받았습니다.","(간추림) 세종 대왕의 한글 창제 정신이 이 상을 통해 전 세계에 퍼지고 있다."],"title":"「유네스코 세종 대왕 문해상」 — 평가 글 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#18','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C6',3,'mc','auto','글 ㉮의 「요즘 많은 사람이 걷기만 해도 건강해졌다는 말을 많이 한다.」에서 이 내용의 출처는 무엇인가요?',ARRAY['K3-2-u3-X32','K3-2-u3-X03']::text[],false,'{"seq":18,"concept":"K3-2-u3-C6","difficulty":3,"kind":"mc","stem":"글 ㉮의 「요즘 많은 사람이 걷기만 해도 건강해졌다는 말을 많이 한다.」에서 이 내용의 출처는 무엇인가요?","options":[{"t":"출처가 없다 — 누가 말했는지 밝히지 않았다","correct":true},{"t":"많은 사람","mis":"K3-2-u3-X32"},{"t":"걷기","mis":"K3-2-u3-X03"}],"explanation":["「많은 사람」은 누구인지 알 수 없어요.","찾아가 확인할 곳이 없으니 출처가 없는 것이에요.","그래서 ㉮는 내용을 모두 믿기 어려워요."],"asset":{"type":"passage","lines":["㉮ 하루에 30분만 걸어도 모든 병이 낫고 기분이 좋아진다고 한다.","요즘 많은 사람이 걷기만 해도 건강해졌다는 말을 많이 한다.","걷는 것은 최고의 치료법이다.","㉯ 세계보건기구에 따르면, 하루 30분 이상 걷기 운동을 하면","심혈관 건강 개선에 효과가 있으며 고혈압 예방에도 도움이 된다고 한다."],"title":"같은 걷기 이야기, 두 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#19','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C13',3,'mc','auto','한 친구가 글의 모든 문장 앞에 이어 주는 말을 넣었어요. 어떤 문제가 있나요?',ARRAY['K3-2-u3-X18','K3-2-u3-X19']::text[],false,'{"seq":19,"concept":"K3-2-u3-C13","difficulty":3,"kind":"mc","stem":"한 친구가 글의 모든 문장 앞에 이어 주는 말을 넣었어요. 어떤 문제가 있나요?","options":[{"t":"앞뒤 뜻과 상관없이 넣어서 오히려 문장 사이의 관계가 흐려진다","correct":true},{"t":"많을수록 좋으니 문제가 없다","mis":"K3-2-u3-X18"},{"t":"그러니 이어 주는 말은 아예 빼야 한다","mis":"K3-2-u3-X19"}],"explanation":["이어 주는 말은 많이 쓸수록 좋은 것이 아니에요.","앞뒤 뜻이 어떻게 이어지는지에 맞을 때 써요.","하나도 안 쓰는 것도 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#20','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C18',3,'mc','auto','『국어활동』 45쪽 더 알아보기예요. 일의 순서를 설명하는 글을 쓸 때 주의할 점은 무엇인가요?',ARRAY['K3-2-u3-X35','K3-2-u3-X31']::text[],false,'{"seq":20,"concept":"K3-2-u3-C18","difficulty":3,"kind":"mc","stem":"『국어활동』 45쪽 더 알아보기예요. 일의 순서를 설명하는 글을 쓸 때 주의할 점은 무엇인가요?","options":[{"t":"중요한 순서를 빠뜨리지 않았는지 확인한다","correct":true},{"t":"읽는 사람이 알아서 하니 몇 단계는 빼도 된다","mis":"K3-2-u3-X35"},{"t":"순서보다 느낌을 자세히 쓴다","mis":"K3-2-u3-X31"}],"explanation":["설명하는 글에는 일의 순서가 차근차근 나타나야 해요.","중요한 순서를 빠뜨리면 따라 할 수 없어요.","다 쓴 뒤 빠진 순서가 없는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#21','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C8',3,'mc','auto','출처가 있는 자료를 읽을 때 알맞은 태도는 무엇인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X14']::text[],false,'{"seq":21,"concept":"K3-2-u3-C8","difficulty":3,"kind":"mc","stem":"출처가 있는 자료를 읽을 때 알맞은 태도는 무엇인가요?","options":[{"t":"어떤 곳에서 가져왔는지 살펴보고 생각하며 읽는다","correct":true},{"t":"출처가 적혀 있으면 무조건 믿는다","mis":"K3-2-u3-X12"},{"t":"거짓일 수 있으니 무조건 믿지 않는다","mis":"K3-2-u3-X13"},{"t":"출처의 이름이 길면 믿는다","mis":"K3-2-u3-X14"}],"explanation":["출처가 있다고 다 맞는 것도, 다 거짓인 것도 아니에요.","어떤 곳인지 살펴보며 읽어요.","함부로 믿지 않고 생각해 보는 자세가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#22','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C5',3,'mc','auto','다른 사람이 만든 그림을 가져와 출처 없이 내 글에 넣었어요. 무엇이 문제인가요?',ARRAY['K3-2-u3-X06','K3-2-u3-X28']::text[],false,'{"seq":22,"concept":"K3-2-u3-C5","difficulty":3,"kind":"mc","stem":"다른 사람이 만든 그림을 가져와 출처 없이 내 글에 넣었어요. 무엇이 문제인가요?","options":[{"t":"만든 사람의 것을 내 것처럼 쓴 것이라 출처를 밝혀야 한다","correct":true},{"t":"내가 골랐으니 내 것이라 문제없다","mis":"K3-2-u3-X06"},{"t":"그림은 출처가 필요 없다","mis":"K3-2-u3-X28"}],"explanation":["다른 사람이 만든 것을 내 것처럼 쓰면 안 돼요.","출처를 밝히면 만든 사람을 존중하게 돼요.","그림이나 사진도 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#23','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C17',4,'essay','teacher','윷놀이하는 방법을 설명하는 글을 쓰세요. 놀이할 사람의 수, 놀이에 필요한 준비물, 놀이의 규칙, 놀이하는 순서가 드러나게 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u3-C17","difficulty":4,"kind":"essay","stem":"윷놀이하는 방법을 설명하는 글을 쓰세요. 놀이할 사람의 수, 놀이에 필요한 준비물, 놀이의 규칙, 놀이하는 순서가 드러나게 쓰세요.","answer_guide":{"answer":"예: 제목 — 윷놀이하는 방법. 윷놀이는 두 사람 이상이 두 편으로 나누어 해요. 준비물은 윷 네 개, 윷판, 말이에요. 먼저, 편을 나누고 순서를 정해요. 다음으로, 차례가 되면 윷을 던져 나온 대로 말을 움직여요. 윷이나 모가 나오면 한 번 더 던져요. 끝으로, 말 네 개가 먼저 모두 들어온 편이 이겨요.","scoring_points":["놀이할 사람의 수와 준비물을 썼는가","놀이의 규칙을 썼는가","놀이하는 순서를 차례를 나타내는 말로 드러냈는가"]},"explanation":["윷놀이를 해 본 경험을 떠올려 정리해요.","사람 수, 준비물, 규칙, 순서를 나누어 생각해요.","읽는 사람이 그대로 놀 수 있게 차례대로 써요."],"asset":{"type":"passage","lines":["제목: 윷놀이하는 방법","놀이할 사람의 수 · 놀이에 필요한 준비물","놀이의 규칙 · 놀이하는 순서"],"title":"설명하는 글 쓰기 — 정리하는 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#24','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C9',4,'essay','teacher','평가 글 「유네스코 세종 대왕 문해상」을 읽고 설명하는 대상, 자료의 내용, 자료의 출처를 각각 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u3-C9","difficulty":4,"kind":"essay","stem":"평가 글 「유네스코 세종 대왕 문해상」을 읽고 설명하는 대상, 자료의 내용, 자료의 출처를 각각 쓰세요.","answer_guide":{"answer":"예: 설명하는 대상 — 유네스코 세종 대왕 문해상. 자료의 내용 — 1990년부터 2024년까지 전 세계 68개의 단체와 개인이 유네스코 세종 대왕 문해상을 받았다. 자료의 출처 — 문화체육관광부의 보도 자료.","scoring_points":["설명하는 대상을 바르게 찾았는가","자료의 내용을 바르게 썼는가","자료의 출처를 바르게 찾았는가"]},"explanation":["글의 제목과 많이 쓰인 낱말로 설명하는 대상을 찾아요.","「…에 따르면」 뒤에 자료의 내용이 와요.","「…에 따르면」 앞이 자료의 출처예요."],"asset":{"type":"passage","lines":["(간추림) 한국 정부가 유네스코에 제의해서 만든 ‘유네스코 세종 대왕 문해상’이 있다.","여기서 ‘문해’란 글을 읽고 이해한다는 뜻이에요.","(간추림) 글을 익히도록 도운 개인과 단체를 뽑아 세계 문해의 날(9월 8일)에 준다.","문화체육관광부의 보도 자료에 따르면, 1990년부터 2024년까지","전 세계 68개의 단체와 개인이 유네스코 세종 대왕 문해상을 받았습니다.","(간추림) 세종 대왕의 한글 창제 정신이 이 상을 통해 전 세계에 퍼지고 있다."],"title":"「유네스코 세종 대왕 문해상」 — 평가 글 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_a#25','kor',3,2,'u3','','tb_g3_2_kor_u3_review_a','unit_review','K3-2-u3-C13',4,'essay','teacher','오늘 하루 동안 있었던 일을 세 문장 이상으로 쓰세요. ‘그리고’, ‘그러나’, ‘그래서’ 가운데 두 가지 이상을 앞뒤 관계에 맞게 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u3-C13","difficulty":4,"kind":"essay","stem":"오늘 하루 동안 있었던 일을 세 문장 이상으로 쓰세요. ‘그리고’, ‘그러나’, ‘그래서’ 가운데 두 가지 이상을 앞뒤 관계에 맞게 넣으세요.","answer_guide":{"answer":"예: 아침에 일찍 일어났습니다. 그래서 여유 있게 아침밥을 먹었습니다. 그러나 학교에 가는 길에 비가 내리기 시작했습니다. 그리고 바람도 세게 불었습니다.","scoring_points":["있었던 일을 세 문장 이상 썼는가","이어 주는 말을 두 가지 이상 넣었는가","이어 주는 말을 앞뒤 관계에 맞게 썼는가"]},"explanation":["일어난 일을 차례대로 떠올려요.","앞뒤 관계를 생각해 알맞은 이어 주는 말을 골라요.","문장마다 넣지 말고 필요한 곳에 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#1','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C3',1,'ox','auto','『국어활동』 43쪽에서 「출처는 사람, 기관, 누리집 주소처럼 다양한 형태로 제시될 수 있어요.」라고 했어요. 맞는 말이에요.',ARRAY['K3-2-u3-X04']::text[],false,'{"seq":1,"concept":"K3-2-u3-C3","difficulty":1,"kind":"ox","stem":"『국어활동』 43쪽에서 「출처는 사람, 기관, 누리집 주소처럼 다양한 형태로 제시될 수 있어요.」라고 했어요. 맞는 말이에요.","answer":"O","reason_options":[{"t":"출처는 자료에 따라 사람, 기관, 누리집 주소 등으로 나타나요.","correct":true},{"t":"출처는 언제나 기관 이름 하나로만 써요.","mis":"K3-2-u3-X04"}],"mis":"K3-2-u3-X04","explanation":["출처의 형태는 여러 가지예요.","사람, 기관, 누리집 주소로 나타날 수 있어요.","어떤 형태든 자료를 가져온 곳을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#2','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C4',1,'mc','auto','『국어』 113쪽 4번에서 한 친구가 「동영상에 사용된 자료에 출처가 나와 있었어.」라고 했어요. 동영상에서는 출처를 어디에서 찾아볼 수 있을까요?',ARRAY['K3-2-u3-X04','K3-2-u3-X03']::text[],false,'{"seq":2,"concept":"K3-2-u3-C4","difficulty":1,"kind":"mc","stem":"『국어』 113쪽 4번에서 한 친구가 「동영상에 사용된 자료에 출처가 나와 있었어.」라고 했어요. 동영상에서는 출처를 어디에서 찾아볼 수 있을까요?","options":[{"t":"동영상 화면에 나오는 글씨","correct":true},{"t":"동영상에는 출처가 있을 수 없다","mis":"K3-2-u3-X04"},{"t":"동영상을 본 날짜","mis":"K3-2-u3-X03"},{"t":"동영상에 나온 사람의 얼굴","mis":"K3-2-u3-X03"}],"explanation":["글뿐만 아니라 영상 자료에서도 출처를 볼 수 있어요.","화면 아래쪽 작은 글씨 등으로 출처를 밝혀요.","자료의 형식에 상관없이 출처를 찾아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#3','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C12',1,'blank','auto','「나는 그림을 잘 그리지 못합니다. (     ) 실망하지 않고 열심히 연습할 것입니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":3,"concept":"K3-2-u3-C12","difficulty":1,"kind":"blank","stem":"「나는 그림을 잘 그리지 못합니다. (     ) 실망하지 않고 열심히 연습할 것입니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그러나","correct":true},{"t":"그래서","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["잘 그리지 못한다는 것과 실망하지 않는다는 것은 반대 방향이에요.","반대되는 내용이 이어지니 ‘그러나’를 써요.","앞뒤 관계를 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#4','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C13',1,'ox','auto','『국어』 141쪽 표지판 ㉡ 「이어 주는 말의 앞뒤 문장이 자연스럽게 연결되었는지 확인한다.」는 알맞은 설명이에요.',ARRAY['K3-2-u3-X18']::text[],false,'{"seq":4,"concept":"K3-2-u3-C13","difficulty":1,"kind":"ox","stem":"『국어』 141쪽 표지판 ㉡ 「이어 주는 말의 앞뒤 문장이 자연스럽게 연결되었는지 확인한다.」는 알맞은 설명이에요.","answer":"O","reason_options":[{"t":"이어 주는 말은 앞뒤 관계에 맞게 썼는지 확인해야 해요.","correct":true},{"t":"이어 주는 말은 넣기만 하면 되고 앞뒤를 살필 필요는 없어요.","mis":"K3-2-u3-X18"}],"mis":"K3-2-u3-X18","explanation":["이어 주는 말은 앞뒤 내용을 연결해요.","앞뒤가 자연스럽게 이어지는지 확인해요.","많이 넣는 것보다 알맞게 넣는 것이 중요해요."],"asset":{"type":"passage","lines":["㉠ 설명하는 글을 쓸 때에는 어려운 낱말을 많이 써야 한다.","㉡ 이어 주는 말의 앞뒤 문장이 자연스럽게 연결되었는지 확인한다.","㉢ 설명하는 글에서는 ‘첫째’, ‘그다음에는’과 같은 말을 사용하면 이해하기 쉽다.","㉣ 자료의 출처를 보면 글의 내용이 믿을 만한지 확인할 수 있다."],"title":"스스로 확인하기 — 길에 선 표지판 넷, 『국어』 141쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#5','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C20',1,'mc','auto','짝에게 들은 말을 전해요. 「짝이 그러는데 내일 운동장 청소를 (     ).」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":5,"concept":"K3-2-u3-C20","difficulty":1,"kind":"mc","stem":"짝에게 들은 말을 전해요. 「짝이 그러는데 내일 운동장 청소를 (     ).」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"한대","correct":true},{"t":"한데","mis":"K3-2-u3-X29"},{"t":"했데","mis":"K3-2-u3-X29"}],"explanation":["짝에게 들은 말을 다른 사람에게 전하는 상황이에요.","남의 말을 전할 때는 ‘-대’를 써요.","「한대」는 「한다고 해」가 줄어든 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#6','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C21',1,'mc','auto','『국어』 142쪽 낱말 그물 보기에서 「건강」은 「자전거」의 어느 갈래로 뻗은 말인가요?',ARRAY['K3-2-u3-X30']::text[],false,'{"seq":6,"concept":"K3-2-u3-C21","difficulty":1,"kind":"mc","stem":"『국어』 142쪽 낱말 그물 보기에서 「건강」은 「자전거」의 어느 갈래로 뻗은 말인가요?","options":[{"t":"좋은 점","correct":true},{"t":"준비물","mis":"K3-2-u3-X30"},{"t":"장소","mis":"K3-2-u3-X30"},{"t":"방법","mis":"K3-2-u3-X30"}],"explanation":["자전거를 타면 몸이 튼튼해져요.","그래서 「건강」은 좋은 점 갈래예요.","한 낱말에서 여러 갈래로 생각이 뻗어 나가요."],"asset":{"type":"passage","lines":["가운데 낱말: 자전거","방법 → 균형 잡기","준비물 → 안전모","좋은 점 → 건강","장소 → 공원"],"title":"보기 — 낱말 그물, 『국어』 142쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#7','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C14',1,'ox','auto','설명하는 글은 읽을 사람이 누구든 똑같이 쓰면 돼요.',ARRAY['K3-2-u3-X21']::text[],false,'{"seq":7,"concept":"K3-2-u3-C14","difficulty":1,"kind":"ox","stem":"설명하는 글은 읽을 사람이 누구든 똑같이 쓰면 돼요.","answer":"X","reason_options":[{"t":"읽을 대상에 따라 쓰는 낱말과 자세한 정도가 달라져요.","correct":true},{"t":"설명하는 글은 내용만 맞으면 누가 읽든 상관없어요.","mis":"K3-2-u3-X21"}],"mis":"K3-2-u3-X21","explanation":["읽는 사람이 1학년인지 3학년인지에 따라 글이 달라져요.","읽는 사람이 이해할 수 있는 낱말로 써요.","쓰기 전에 읽는 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#8','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C7',1,'blank','auto','「출처를 확인하며 글을 읽으면 자료를 가져온 곳에서 주제와 관련 있는 정보를 더 (     ) 수 있다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X10']::text[],false,'{"seq":8,"concept":"K3-2-u3-C7","difficulty":1,"kind":"blank","stem":"「출처를 확인하며 글을 읽으면 자료를 가져온 곳에서 주제와 관련 있는 정보를 더 (     ) 수 있다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"찾아볼","correct":true},{"t":"빨리 읽을","mis":"K3-2-u3-X10"},{"t":"외울","mis":"K3-2-u3-X10"}],"explanation":["출처는 자료를 가져온 곳이에요.","그곳에 가면 주제와 관련 있는 정보를 더 찾아볼 수 있어요.","출처를 확인하며 읽으면 좋은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#9','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C7',2,'mc','auto','『국어활동』 43쪽 (2)예요. 「글 (     )는 전문적인 지식을 갖춘 사람이나 전문 기관의 자료를 가져왔는지 확인할 수 있어.」 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X11']::text[],false,'{"seq":9,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"『국어활동』 43쪽 (2)예요. 「글 (     )는 전문적인 지식을 갖춘 사람이나 전문 기관의 자료를 가져왔는지 확인할 수 있어.」 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"K3-2-u3-X11"},{"t":"둘 다 확인할 수 없다","mis":"K3-2-u3-X11"}],"explanation":["글 가의 출처는 보건복지부·한국영양학회예요.","출처가 있어야 어떤 곳의 자료인지 확인할 수 있어요.","글 나는 출처가 없어 확인할 수 없어요."],"asset":{"type":"passage","lines":["글 가 — 의견: 자신에게 필요한 만큼의 물을 충분히 마시자.","글 가 — 자료의 출처: 「한국인 영양소 섭취 기준」, 보건복지부·한국영양학회.","글 나 — 의견: 가장 안전하고 간편한 운동인 걷기를 규칙적으로 실천하자.","글 나 — 자료의 출처: (적혀 있지 않음)"],"title":"글 가와 글 나를 정리한 표 — 『국어활동』 43쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#10','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C12',2,'blank','auto','「내일은 나무를 심고 가꾸는 식목일이다. (     ) 선생님께서는 나무의 소중함을 알려 주셨다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":10,"concept":"K3-2-u3-C12","difficulty":2,"kind":"blank","stem":"「내일은 나무를 심고 가꾸는 식목일이다. (     ) 선생님께서는 나무의 소중함을 알려 주셨다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그래서","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["식목일이라는 것이 나무의 소중함을 알려 주신 이유예요.","그래서 ‘그래서’를 써요.","앞뒤 내용의 관계를 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#11','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C17',2,'match','auto','순서나 방법을 설명하는 글의 짜임과 그 부분에 쓸 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K3-2-u3-C17","difficulty":2,"kind":"match","stem":"순서나 방법을 설명하는 글의 짜임과 그 부분에 쓸 내용을 알맞게 이으세요.","pairs":[{"l":"처음","r":"무엇을 설명하는 글인지 밝힌다."},{"l":"가운데","r":"일의 순서와 방법을 자세히 쓴다."},{"l":"끝","r":"설명한 내용을 간추린다."}],"mis":"K3-2-u3-X25","explanation":["처음 부분은 글을 쓰는 목적을 밝히는 자리예요.","가운데 부분은 일의 순서나 방법을 쓰는 자리예요.","끝부분은 설명한 내용을 간추리는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#12','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C11',2,'error','auto','출처에 적힌 곳을 어떻게 확인할지 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X14','K3-2-u3-X12']::text[],false,'{"seq":12,"concept":"K3-2-u3-C11","difficulty":2,"kind":"error","stem":"출처에 적힌 곳을 어떻게 확인할지 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은찬: 출처에 ‘누리집’이라는 말만 있으면 들어가 보지 않아도 돼.","correct":true,"mis_target":"K3-2-u3-X14"},{"t":"소리: 출처가 어떤 곳인지 먼저 알아봐.","mis":"K3-2-u3-X14"},{"t":"예준: 적혀 있는 곳에 직접 가 보거나 누리집에 들어가 봐.","mis":"K3-2-u3-X12"}],"explanation":["‘누리집’이라는 말만으로 확인한 것이 아니에요.","직접 들어가서 자료가 있는지 봐야 해요.","어떤 곳인지 알아보는 것도 확인 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#13','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C15',2,'blank','auto','그림자놀이 방법을 설명해요. 「① 그림자놀이를 해 볼까요? ② (     ) 왼손 손바닥을 하늘로 향하게 한 상태에서 엄지손가락과 집게손가락을 동그랗게 만들어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X16']::text[],false,'{"seq":13,"concept":"K3-2-u3-C15","difficulty":2,"kind":"blank","stem":"그림자놀이 방법을 설명해요. 「① 그림자놀이를 해 볼까요? ② (     ) 왼손 손바닥을 하늘로 향하게 한 상태에서 엄지손가락과 집게손가락을 동그랗게 만들어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"먼저","correct":true},{"t":"끝으로","mis":"K3-2-u3-X22"},{"t":"그러나","mis":"K3-2-u3-X16"}],"explanation":["그림자놀이에서 처음 하는 동작이에요.","첫 단계 앞에는 「먼저」를 써요.","다음 단계에는 「다음에」, 마지막에는 「끝으로」를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#14','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C16',2,'ox','auto','내가 직접 해 본 정리 방법에도 반드시 출처를 붙여야 해요.',ARRAY['K3-2-u3-X24']::text[],false,'{"seq":14,"concept":"K3-2-u3-C16","difficulty":2,"kind":"ox","stem":"내가 직접 해 본 정리 방법에도 반드시 출처를 붙여야 해요.","answer":"X","reason_options":[{"t":"내가 해 본 방법은 가져온 것이 아니라서 출처가 없어도 돼요.","correct":true},{"t":"글에 쓴 내용은 모두 출처가 있어야 해요.","mis":"K3-2-u3-X24"}],"mis":"K3-2-u3-X24","explanation":["출처는 다른 곳에서 가져온 자료에 밝혀요.","내가 직접 해 보고 안 방법은 가져온 것이 아니에요.","찾아본 것과 해 본 것을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#15','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C18',2,'mc','auto','『국어』 137쪽 점검하기 표에서 ●●●, ●●, ●는 무엇을 나타내나요?',ARRAY['K3-2-u3-X26']::text[],false,'{"seq":15,"concept":"K3-2-u3-C18","difficulty":2,"kind":"mc","stem":"『국어』 137쪽 점검하기 표에서 ●●●, ●●, ●는 무엇을 나타내나요?","options":[{"t":"매우 잘함은 ●●●, 잘함은 ●●, 보통임은 ●","correct":true},{"t":"●가 많을수록 고칠 것이 많다","mis":"K3-2-u3-X26"},{"t":"●는 쓴 문장의 수를 나타낸다","mis":"K3-2-u3-X26"}],"explanation":["점검 물음마다 스스로 얼마나 잘했는지 표시해요.","매우 잘함 ●●●, 잘함 ●●, 보통임 ●이에요.","●가 적은 물음은 다시 살펴 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#16','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C19',2,'mc','auto','대중교통 이용 설명서를 모둠에서 쓸 때, 문단마다 중심 문장과 뒷받침 내용은 어떻게 정하면 좋을까요?',ARRAY['K3-2-u3-X25','K3-2-u3-X02']::text[],false,'{"seq":16,"concept":"K3-2-u3-C19","difficulty":2,"kind":"mc","stem":"대중교통 이용 설명서를 모둠에서 쓸 때, 문단마다 중심 문장과 뒷받침 내용은 어떻게 정하면 좋을까요?","options":[{"t":"중심 문장은 모둠이 함께 정하고, 뒷받침 내용은 각자 조사한다","correct":true},{"t":"중심 문장은 정하지 않고 각자 아무거나 쓴다","mis":"K3-2-u3-X25"},{"t":"조사하지 않고 그럴듯하게 쓴다","mis":"K3-2-u3-X02"}],"explanation":["문단의 짜임은 모둠 전체가 함께 정해요.","각자 맡은 문단의 뒷받침 내용은 조사해서 써요.","조사한 자료는 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#17','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C9',3,'mc','auto','평가 글 「유네스코 세종 대왕 문해상」에 제시된 자료의 내용은 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":17,"concept":"K3-2-u3-C9","difficulty":3,"kind":"mc","stem":"평가 글 「유네스코 세종 대왕 문해상」에 제시된 자료의 내용은 무엇인가요?","options":[{"t":"1990년부터 2024년까지 전 세계 68개의 단체와 개인이 상을 받았다","correct":true},{"t":"세종 대왕이 유네스코를 만들었다","mis":"K3-2-u3-X08"},{"t":"상은 해마다 10월 9일 한글날에 준다","mis":"K3-2-u3-X08"},{"t":"68개 나라가 이 상을 만들었다","mis":"K3-2-u3-X08"}],"explanation":["「문화체육관광부의 보도 자료에 따르면」 다음을 읽어요.","1990년부터 2024년까지 68개의 단체와 개인이 받았다고 했어요.","자료의 내용과 출처를 함께 확인해요."],"asset":{"type":"passage","lines":["(간추림) 한국 정부가 유네스코에 제의해서 만든 ‘유네스코 세종 대왕 문해상’이 있다.","여기서 ‘문해’란 글을 읽고 이해한다는 뜻이에요.","(간추림) 글을 익히도록 도운 개인과 단체를 뽑아 세계 문해의 날(9월 8일)에 준다.","문화체육관광부의 보도 자료에 따르면, 1990년부터 2024년까지","전 세계 68개의 단체와 개인이 유네스코 세종 대왕 문해상을 받았습니다.","(간추림) 세종 대왕의 한글 창제 정신이 이 상을 통해 전 세계에 퍼지고 있다."],"title":"「유네스코 세종 대왕 문해상」 — 평가 글 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#18','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C6',3,'error','auto','「손끝으로 읽는 여섯 개의 점」에서 활용한 자료를 찾았어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X33','K3-2-u3-X09']::text[],false,'{"seq":18,"concept":"K3-2-u3-C6","difficulty":3,"kind":"error","stem":"「손끝으로 읽는 여섯 개의 점」에서 활용한 자료를 찾았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시하: 이 글에서 활용한 자료는 그림 두 개뿐이야.","correct":true,"mis_target":"K3-2-u3-X33"},{"t":"은재: 『한국 점자 규정』에 따른 내용도 활용한 자료야.","mis":"K3-2-u3-X33"},{"t":"태민: 훈맹정음 그림에는 국립한글박물관 누리집이라는 출처가 있어.","mis":"K3-2-u3-X09"}],"explanation":["그림처럼 눈에 띄는 것만 자료가 아니에요.","「『한국 점자 규정』에 따르면」으로 가져온 내용도 자료예요.","글 속에 인용된 자료도 출처와 함께 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#19','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C13',3,'mc','auto','「비가 많이 왔습니다. 소풍을 다음 주로 미루었습니다.」 두 문장 사이에 넣어 앞뒤 관계를 드러내려면 무엇을 넣어야 하나요?',ARRAY['K3-2-u3-X16','K3-2-u3-X19']::text[],false,'{"seq":19,"concept":"K3-2-u3-C13","difficulty":3,"kind":"mc","stem":"「비가 많이 왔습니다. 소풍을 다음 주로 미루었습니다.」 두 문장 사이에 넣어 앞뒤 관계를 드러내려면 무엇을 넣어야 하나요?","options":[{"t":"그래서","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"아무것도 넣지 않아도 관계가 잘 드러난다","mis":"K3-2-u3-X19"}],"explanation":["비가 많이 온 것이 소풍을 미룬 이유예요.","이유와 결과를 이을 때 ‘그래서’를 써요.","이어 주는 말이 있으면 두 문장이 왜 붙어 있는지 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#20','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C15',3,'mc','auto','「종이접기로 고깔모자를 만드는 방법」을 친구에게 설명하면서 ③을 빼고 말했어요. 어떤 일이 생길까요?',ARRAY['K3-2-u3-X35','K3-2-u3-X03']::text[],false,'{"seq":20,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"「종이접기로 고깔모자를 만드는 방법」을 친구에게 설명하면서 ③을 빼고 말했어요. 어떤 일이 생길까요?","options":[{"t":"양쪽 모서리를 접지 않아 고깔 모양을 만들 수 없다","correct":true},{"t":"빼도 똑같은 모자를 만들 수 있다","mis":"K3-2-u3-X35"},{"t":"글의 출처가 없어진다","mis":"K3-2-u3-X03"}],"explanation":["③은 양쪽 모서리를 삼각형 모양으로 접는 단계예요.","이 단계를 빼면 뾰족한 고깔 모양이 나오지 않아요.","중요한 순서는 하나도 빠뜨리지 않아요."],"asset":{"type":"passage","lines":["준비물: 색종이 한 장 (신문지나 큰 도화지로 만들면 더 큰 모자)","① 색종이의 중심선에 맞추어 양옆을 마주 접은 뒤 뒤집어 줍니다.","② 아래로 반을 내려 접습니다.","③ 양쪽 모서리를 삼각형 모양이 되도록 마주 접습니다.","④ 아래쪽을 삼각형으로 접은 선 아래까지 접습니다.","⑤ 아래쪽을 한 번 더 위로 접어 올립니다. 뒤집어서 반대쪽도 똑같이 접습니다.","⑥ 모자의 중간 부분을 적당히 열어 줍니다."],"title":"「종이접기로 고깔모자를 만드는 방법」 — 『국어활동』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#21','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C8',3,'ox','auto','출처는 「이 자료를 그대로 믿어라」는 표시예요.',ARRAY['K3-2-u3-X12']::text[],false,'{"seq":21,"concept":"K3-2-u3-C8","difficulty":3,"kind":"ox","stem":"출처는 「이 자료를 그대로 믿어라」는 표시예요.","answer":"X","reason_options":[{"t":"출처는 자료를 가져온 곳을 살펴볼 수 있게 해 주는 표시예요.","correct":true},{"t":"출처가 붙은 자료는 모두 맞으니 그대로 믿어요.","mis":"K3-2-u3-X12"}],"mis":"K3-2-u3-X12","explanation":["출처는 「살펴볼 수 있다」는 표예요.","이름만 적어 놓은 것일 수도 있어요.","어떤 곳인지 살펴보며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#22','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C16',3,'error','auto','설명하는 글에 출처를 쓴 방법을 말했어요. 잘못한 친구는 누구인가요?',ARRAY['K3-2-u3-X23','K3-2-u3-X24','K3-2-u3-X07']::text[],false,'{"seq":22,"concept":"K3-2-u3-C16","difficulty":3,"kind":"error","stem":"설명하는 글에 출처를 쓴 방법을 말했어요. 잘못한 친구는 누구인가요?","options":[{"t":"나린: 찾아본 곳이 생각나지 않아서 그럴듯한 누리집 이름을 지어 적었어.","correct":true,"mis_target":"K3-2-u3-X23"},{"t":"지오: 내가 직접 해 본 방법이라서 출처를 쓰지 않았어.","mis":"K3-2-u3-X24"},{"t":"하경: 조사한 책 이름을 글 끝에 밝혔어.","mis":"K3-2-u3-X07"}],"explanation":["지어 적은 출처를 믿고 찾아간 친구는 아무것도 찾을 수 없어요.","출처는 확인해서 적는 거예요.","직접 해 본 방법은 출처가 없어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#23','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C17',4,'essay','teacher','윷놀이 대신 내가 잘 아는 다른 놀이를 하나 골라 설명하는 글을 쓰세요. 놀이할 사람의 수, 준비물, 규칙, 놀이하는 순서가 드러나게 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u3-C17","difficulty":4,"kind":"essay","stem":"윷놀이 대신 내가 잘 아는 다른 놀이를 하나 골라 설명하는 글을 쓰세요. 놀이할 사람의 수, 준비물, 규칙, 놀이하는 순서가 드러나게 쓰세요.","answer_guide":{"answer":"예: 제목 — 사방치기하는 방법. 두 사람 이상이 할 수 있어요. 준비물은 납작한 돌과 분필이에요. 먼저, 땅에 분필로 칸을 그려요. 다음으로, 돌을 첫째 칸에 던지고 한 발로 뛰어 칸을 차례대로 지나요. 규칙 — 돌이 놓인 칸은 밟지 않고, 금을 밟으면 차례가 넘어가요. 끝으로, 모든 칸을 먼저 마친 사람이 이겨요.","scoring_points":["놀이할 사람의 수와 준비물을 썼는가","놀이의 규칙을 썼는가","놀이하는 순서를 차례대로 썼는가"]},"explanation":["자신이 잘 아는 놀이를 고르면 순서를 빠뜨리지 않아요.","규칙과 순서를 나누어 정리해요.","처음 해 보는 친구도 따라 할 수 있게 써요."],"asset":{"type":"passage","lines":["제목: 윷놀이하는 방법","놀이할 사람의 수 · 놀이에 필요한 준비물","놀이의 규칙 · 놀이하는 순서"],"title":"설명하는 글 쓰기 — 정리하는 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#24','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C7',4,'essay','teacher','평소 내가 글을 읽을 때 출처를 확인하는지 스스로 돌아보고, 앞으로 출처를 확인하며 읽기 위해 실천할 일을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u3-C7","difficulty":4,"kind":"essay","stem":"평소 내가 글을 읽을 때 출처를 확인하는지 스스로 돌아보고, 앞으로 출처를 확인하며 읽기 위해 실천할 일을 두 가지 쓰세요.","answer_guide":{"answer":"예: 전에는 신문이나 잡지를 읽을 때 사진과 그래프만 보고 출처는 보지 않았다. 앞으로는 자료 아래와 「…에 따르면」을 찾아 출처를 확인하겠다. 또 더 궁금한 점이 있으면 출처의 누리집에 들어가 정보를 더 찾아보겠다.","scoring_points":["자신의 읽기 습관을 돌아보았는가","출처를 찾는 방법을 실천할 일로 썼는가","출처를 활용해 더 찾아보는 일을 썼는가"]},"explanation":["출처를 확인하며 글을 읽는 습관을 스스로 점검해요.","자료 아래와 본문 속 「…에 따르면」을 찾아요.","궁금한 점은 출처에서 더 찾아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_b#25','kor',3,2,'u3','','tb_g3_2_kor_u3_review_b','unit_review','K3-2-u3-C15',4,'essay','teacher','「종이접기로 고깔모자를 만드는 방법」을 1학년 동생에게 설명하는 글로 다시 쓰세요. 번호 대신 ‘먼저’, ‘다음으로’, ‘끝으로’ 같은 차례를 나타내는 말을 쓰고, 준비물도 앞에 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u3-C15","difficulty":4,"kind":"essay","stem":"「종이접기로 고깔모자를 만드는 방법」을 1학년 동생에게 설명하는 글로 다시 쓰세요. 번호 대신 ‘먼저’, ‘다음으로’, ‘끝으로’ 같은 차례를 나타내는 말을 쓰고, 준비물도 앞에 쓰세요.","answer_guide":{"answer":"예: 준비물은 색종이 한 장이에요. 먼저, 색종이 가운데 선에 맞추어 양옆을 접고 뒤집어요. 다음으로, 아래에서 반을 내려 접어요. 그다음에 양쪽 모서리를 세모 모양으로 접어요. 그리고 아래쪽을 두 번 접어 올리고, 뒤집어서 반대쪽도 똑같이 접어요. 끝으로, 모자 가운데를 살짝 벌려요.","scoring_points":["준비물을 앞에 썼는가","차례를 나타내는 말로 순서를 드러냈는가","중요한 순서를 빠뜨리지 않고 쉬운 말로 썼는가"]},"explanation":["읽는 사람이 1학년이니 쉬운 말로 써요.","준비물을 먼저 쓰면 알기 쉬워요.","여섯 단계를 하나도 빠뜨리지 않아요."],"asset":{"type":"passage","lines":["준비물: 색종이 한 장 (신문지나 큰 도화지로 만들면 더 큰 모자)","① 색종이의 중심선에 맞추어 양옆을 마주 접은 뒤 뒤집어 줍니다.","② 아래로 반을 내려 접습니다.","③ 양쪽 모서리를 삼각형 모양이 되도록 마주 접습니다.","④ 아래쪽을 삼각형으로 접은 선 아래까지 접습니다.","⑤ 아래쪽을 한 번 더 위로 접어 올립니다. 뒤집어서 반대쪽도 똑같이 접습니다.","⑥ 모자의 중간 부분을 적당히 열어 줍니다."],"title":"「종이접기로 고깔모자를 만드는 방법」 — 『국어활동』 44쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#1','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C5',1,'blank','auto','「다른 사람이 만든 자료를 사용할 때에는 (     )을/를 밝혀야 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X06','K3-2-u3-X31']::text[],false,'{"seq":1,"concept":"K3-2-u3-C5","difficulty":1,"kind":"blank","stem":"「다른 사람이 만든 자료를 사용할 때에는 (     )을/를 밝혀야 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"출처","correct":true},{"t":"내 이름","mis":"K3-2-u3-X06"},{"t":"내 느낌","mis":"K3-2-u3-X31"}],"explanation":["다른 사람이 만든 자료를 가져왔다면 어디서 가져왔는지 밝혀요.","그것이 출처예요.","출처를 밝히는 것은 만든 사람을 존중하는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#2','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C4',1,'sa','auto','본문에서 글로 출처를 밝힐 때 「질병관리청의 안내 자료에 (     ),」처럼 써요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u3-C4","difficulty":1,"kind":"sa","stem":"본문에서 글로 출처를 밝힐 때 「질병관리청의 안내 자료에 (     ),」처럼 써요. 빈칸에 알맞은 말을 쓰세요.","answer":["따르면"],"explanation":["「2023년 질병관리청의 ‘올바른 손 씻기’ 안내 자료에 따르면,」이라고 했어요.","「…에 따르면」은 자료를 가져온 곳을 알려 주는 말이에요.","이렇게 본문 속에서 글로 출처를 밝힐 수 있어요."],"mis":"K3-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#3','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C12',1,'blank','auto','『국어활동』 45쪽이에요. 「우리 반 희은이와 정은이는 쌍둥이야. (     ) 두 사람은 성격이 아주 달라.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":3,"concept":"K3-2-u3-C12","difficulty":1,"kind":"blank","stem":"『국어활동』 45쪽이에요. 「우리 반 희은이와 정은이는 쌍둥이야. (     ) 두 사람은 성격이 아주 달라.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그러나","correct":true},{"t":"그래서","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["쌍둥이라면 닮았을 것 같아요.","그런데 성격이 아주 다르다는 반대되는 내용이 이어져요.","그래서 ‘그러나’를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#4','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C15',1,'ox','auto','『국어』 141쪽 표지판 ㉢ 「설명하는 글에서는 ‘첫째’, ‘그다음에는’과 같은 말을 사용하면 이해하기 쉽다.」는 알맞은 설명이에요.',ARRAY['K3-2-u3-X22']::text[],false,'{"seq":4,"concept":"K3-2-u3-C15","difficulty":1,"kind":"ox","stem":"『국어』 141쪽 표지판 ㉢ 「설명하는 글에서는 ‘첫째’, ‘그다음에는’과 같은 말을 사용하면 이해하기 쉽다.」는 알맞은 설명이에요.","answer":"O","reason_options":[{"t":"차례를 나타내는 말이 일의 순서를 드러내 주어요.","correct":true},{"t":"차례를 나타내는 말은 아무 차례로 써도 돼요.","mis":"K3-2-u3-X22"}],"mis":"K3-2-u3-X22","explanation":["‘첫째’, ‘그다음에는’은 차례를 나타내는 말이에요.","일의 순서에 맞게 쓰면 이해하기 쉬워요.","설명하는 글에 자주 써요."],"asset":{"type":"passage","lines":["㉠ 설명하는 글을 쓸 때에는 어려운 낱말을 많이 써야 한다.","㉡ 이어 주는 말의 앞뒤 문장이 자연스럽게 연결되었는지 확인한다.","㉢ 설명하는 글에서는 ‘첫째’, ‘그다음에는’과 같은 말을 사용하면 이해하기 쉽다.","㉣ 자료의 출처를 보면 글의 내용이 믿을 만한지 확인할 수 있다."],"title":"스스로 확인하기 — 길에 선 표지판 넷, 『국어』 141쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#5','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C20',1,'ox','auto','직접 읽어 본 책을 말하며 「내가 읽어 보니 그 책 정말 재미있대!」라고 했어요. 바르게 쓴 말이에요.',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":5,"concept":"K3-2-u3-C20","difficulty":1,"kind":"ox","stem":"직접 읽어 본 책을 말하며 「내가 읽어 보니 그 책 정말 재미있대!」라고 했어요. 바르게 쓴 말이에요.","answer":"X","reason_options":[{"t":"직접 읽고 안 것이라 「재미있데」라고 써야 해요.","correct":true},{"t":"‘보니’가 있으면 늘 ‘-대’를 써요.","mis":"K3-2-u3-X29"}],"mis":"K3-2-u3-X29","explanation":["말하는 사람이 직접 겪은 일이에요.","직접 경험한 내용은 ‘-데’를 써요.","‘보니’가 있는지가 아니라 누가 겪었는지로 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#6','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C10',1,'mc','auto','「손끝으로 읽는 여섯 개의 점」에 나온 낱말이에요. 「세종 대왕이 훈민정음을 창제하고」에서 「창제하고」의 뜻은 무엇인가요?',ARRAY['K3-2-u3-X15']::text[],false,'{"seq":6,"concept":"K3-2-u3-C10","difficulty":1,"kind":"mc","stem":"「손끝으로 읽는 여섯 개의 점」에 나온 낱말이에요. 「세종 대왕이 훈민정음을 창제하고」에서 「창제하고」의 뜻은 무엇인가요?","options":[{"t":"전에 없던 것을 새로 만들고","correct":true},{"t":"세상에 널리 퍼뜨려 모두 알게 하고","mis":"K3-2-u3-X15"},{"t":"여러 사람과 함께 나누어 쓰고","mis":"K3-2-u3-X15"}],"explanation":["세종 대왕은 전에 없던 글자를 새로 만들었어요.","그래서 「창제하고」는 「새로 만들고」라는 뜻이에요.","「반포」와 헷갈리지 않게 문장에 넣어 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#7','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C1',1,'mc','auto','『국어』 128쪽 1번처럼 일의 순서나 방법을 다른 사람에게 알려 준 경험으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X31']::text[],false,'{"seq":7,"concept":"K3-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 128쪽 1번처럼 일의 순서나 방법을 다른 사람에게 알려 준 경험으로 알맞은 것은 무엇인가요?","options":[{"t":"도서실에서 1학년 학생에게 도서 자동 대출 반납기 사용 순서를 알려 준 일","correct":true},{"t":"주말에 놀이공원에서 즐거웠던 느낌을 말한 일","mis":"K3-2-u3-X31"},{"t":"좋아하는 동물이 귀엽다고 생각한 일","mis":"K3-2-u3-X31"}],"explanation":["순서나 방법을 알려 준 경험을 떠올려요.","대출 반납기 사용 순서, 종이학 접는 차례가 그런 경험이에요.","느낌을 말한 것은 방법을 설명한 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#8','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C7',1,'ox','auto','출처를 확인하며 읽으면 전문적인 지식이 있는 사람이나 기관의 자료인지 알 수 있어요.',ARRAY['K3-2-u3-X11']::text[],false,'{"seq":8,"concept":"K3-2-u3-C7","difficulty":1,"kind":"ox","stem":"출처를 확인하며 읽으면 전문적인 지식이 있는 사람이나 기관의 자료인지 알 수 있어요.","answer":"O","reason_options":[{"t":"출처를 보면 자료를 만든 사람이나 기관을 알 수 있어요.","correct":true},{"t":"출처는 자료가 어디에서 왔는지와 상관없어요.","mis":"K3-2-u3-X11"}],"mis":"K3-2-u3-X11","explanation":["출처에는 자료를 만든 사람이나 기관이 나와요.","그것을 보고 전문적인 곳의 자료인지 알 수 있어요.","그래서 자료가 믿을 만한지 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#9','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C7',2,'mc','auto','『국어활동』 43쪽 (2)예요. 「글 (     )는 주제와 관련 있는 더 많은 정보를 출처에서 찾아볼 수 없어.」 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X11','K3-2-u3-X13']::text[],false,'{"seq":9,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"『국어활동』 43쪽 (2)예요. 「글 (     )는 주제와 관련 있는 더 많은 정보를 출처에서 찾아볼 수 없어.」 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"K3-2-u3-X11"},{"t":"가와 나 모두","mis":"K3-2-u3-X13"}],"explanation":["글 나는 출처가 적혀 있지 않아요.","출처가 없으니 더 찾아볼 곳을 알 수 없어요.","출처가 있는 글 가는 출처에서 정보를 더 찾아볼 수 있어요."],"asset":{"type":"passage","lines":["글 가 — 의견: 자신에게 필요한 만큼의 물을 충분히 마시자.","글 가 — 자료의 출처: 「한국인 영양소 섭취 기준」, 보건복지부·한국영양학회.","글 나 — 의견: 가장 안전하고 간편한 운동인 걷기를 규칙적으로 실천하자.","글 나 — 자료의 출처: (적혀 있지 않음)"],"title":"글 가와 글 나를 정리한 표 — 『국어활동』 43쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#10','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C12',2,'blank','auto','「연우는 손전등 스위치를 켰습니다. (     ) 손전등에 불이 들어오지 않았습니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":10,"concept":"K3-2-u3-C12","difficulty":2,"kind":"blank","stem":"「연우는 손전등 스위치를 켰습니다. (     ) 손전등에 불이 들어오지 않았습니다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그러나","correct":true},{"t":"그래서","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["스위치를 켜면 불이 들어올 것 같아요.","그런데 불이 들어오지 않았으니 반대되는 내용이에요.","반대되는 내용이 이어질 때 ‘그러나’를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#11','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C17',2,'mc','auto','「개인 사물함에 물건이 가지런히 정돈되어 있으면 공부할 때 필요한 물건을 편리하게 찾아 쓸 수 있습니다.」는 글의 어느 부분에 어울리나요?',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":11,"concept":"K3-2-u3-C17","difficulty":2,"kind":"mc","stem":"「개인 사물함에 물건이 가지런히 정돈되어 있으면 공부할 때 필요한 물건을 편리하게 찾아 쓸 수 있습니다.」는 글의 어느 부분에 어울리나요?","options":[{"t":"처음","correct":true},{"t":"가운데","mis":"K3-2-u3-X25"},{"t":"끝","mis":"K3-2-u3-X25"}],"explanation":["정리하면 좋은 점을 들며 무엇을 설명할지 여는 문장이에요.","그래서 처음 부분에 어울려요.","설명하는 글의 처음은 무엇을 설명할지 여는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#12','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C11',2,'ox','auto','국립한글박물관이 어떤 기관인지 알아보는 것도 출처를 확인하는 방법이에요.',ARRAY['K3-2-u3-X14']::text[],false,'{"seq":12,"concept":"K3-2-u3-C11","difficulty":2,"kind":"ox","stem":"국립한글박물관이 어떤 기관인지 알아보는 것도 출처를 확인하는 방법이에요.","answer":"O","reason_options":[{"t":"출처가 어떤 곳인지 알면 자료가 믿을 만한지 생각해 볼 수 있어요.","correct":true},{"t":"기관이 어떤 곳인지는 출처 확인과 상관없어요.","mis":"K3-2-u3-X14"}],"mis":"K3-2-u3-X14","explanation":["『국어』 123쪽에서 「어떤 기관인지 확인해야 해.」라고 했어요.","어떤 곳인지 알면 그 자료를 어떻게 읽을지 생각할 수 있어요.","누리집에 직접 들어가 보는 방법도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#13','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C15',2,'mc','auto','지켜야 할 규칙을 「첫째, 둘째, 셋째, 넷째」로 정리하면 좋은 점은 무엇인가요?',ARRAY['K3-2-u3-X01','K3-2-u3-X03']::text[],false,'{"seq":13,"concept":"K3-2-u3-C15","difficulty":2,"kind":"mc","stem":"지켜야 할 규칙을 「첫째, 둘째, 셋째, 넷째」로 정리하면 좋은 점은 무엇인가요?","options":[{"t":"지켜야 할 규칙이 한눈에 보여 기억하기 쉽다","correct":true},{"t":"글이 길어 보인다","mis":"K3-2-u3-X01"},{"t":"규칙의 출처가 저절로 밝혀진다","mis":"K3-2-u3-X03"}],"explanation":["『국어』 131쪽 친구가 「‘첫째, 둘째, 셋째’로 정리해서 기억하기 쉬워.」라고 했어요.","규칙이 많을 때 차례를 나타내는 말로 나누어요.","읽는 사람이 한눈에 파악할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#14','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C16',2,'mc','auto','설명하는 글을 다 썼는데 찾아본 누리집 이름이 기억나지 않아요. 어떻게 해야 할까요?',ARRAY['K3-2-u3-X23']::text[],false,'{"seq":14,"concept":"K3-2-u3-C16","difficulty":2,"kind":"mc","stem":"설명하는 글을 다 썼는데 찾아본 누리집 이름이 기억나지 않아요. 어떻게 해야 할까요?","options":[{"t":"다시 찾아 확인한 뒤 적고, 확인할 수 없으면 그 내용은 쓰지 않는다","correct":true},{"t":"비슷한 누리집 이름을 지어 적는다","mis":"K3-2-u3-X23"},{"t":"출처 칸을 아무 말로 채운다","mis":"K3-2-u3-X23"}],"explanation":["출처는 지어내는 것이 아니에요.","다시 찾아 확인한 뒤 바르게 적어요.","확인할 수 없다면 그 내용은 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#15','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C18',2,'error','auto','쓴 글을 점검하며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X18','K3-2-u3-X26']::text[],false,'{"seq":15,"concept":"K3-2-u3-C18","difficulty":2,"kind":"error","stem":"쓴 글을 점검하며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤: 이어 주는 말을 문장마다 넣었으니 점검할 필요가 없어.","correct":true,"mis_target":"K3-2-u3-X18"},{"t":"지수: 읽는 사람이 궁금해할 내용인지 살펴봐야 해.","mis":"K3-2-u3-X26"},{"t":"민결: 일의 순서나 방법이 잘 드러났는지 살펴봐야 해.","mis":"K3-2-u3-X26"}],"explanation":["이어 주는 말은 많이 넣는다고 좋은 것이 아니에요.","앞뒤 관계에 맞게 적절히 썼는지 점검해요.","점검 물음 네 가지를 모두 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#16','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C19',2,'mc','auto','『국어』 141쪽 생활 속으로에서 「수영할 때 주의해야 할 점을 글로 써 볼 거야.」라고 했어요. 글을 쓸 때 할 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X02','K3-2-u3-X06']::text[],false,'{"seq":16,"concept":"K3-2-u3-C19","difficulty":2,"kind":"mc","stem":"『국어』 141쪽 생활 속으로에서 「수영할 때 주의해야 할 점을 글로 써 볼 거야.」라고 했어요. 글을 쓸 때 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"책이나 믿을 만한 누리집에서 정확한 정보를 확인하고 출처를 밝힌다","correct":true},{"t":"기억나는 대로 그럴듯하게 쓴다","mis":"K3-2-u3-X02"},{"t":"찾아본 내용을 내가 생각한 것처럼 쓴다","mis":"K3-2-u3-X06"}],"explanation":["안전에 관한 내용은 특히 정확해야 해요.","조사해서 정보가 정확한지 확인해요.","가져온 자료는 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#17','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C9',3,'sa','auto','평가 글 「유네스코 세종 대왕 문해상」에 제시된 자료의 출처를 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"K3-2-u3-C9","difficulty":3,"kind":"sa","stem":"평가 글 「유네스코 세종 대왕 문해상」에 제시된 자료의 출처를 쓰세요.","answer":["문화체육관광부의 보도 자료","문화체육관광부 보도 자료","문화체육관광부의 보도자료","문화체육관광부"],"explanation":["「…에 따르면」 앞을 보아요.","「문화체육관광부의 보도 자료에 따르면」이라고 했어요.","본문 속에서 글로 밝힌 출처예요."],"asset":{"type":"passage","lines":["(간추림) 한국 정부가 유네스코에 제의해서 만든 ‘유네스코 세종 대왕 문해상’이 있다.","여기서 ‘문해’란 글을 읽고 이해한다는 뜻이에요.","(간추림) 글을 익히도록 도운 개인과 단체를 뽑아 세계 문해의 날(9월 8일)에 준다.","문화체육관광부의 보도 자료에 따르면, 1990년부터 2024년까지","전 세계 68개의 단체와 개인이 유네스코 세종 대왕 문해상을 받았습니다.","(간추림) 세종 대왕의 한글 창제 정신이 이 상을 통해 전 세계에 퍼지고 있다."],"title":"「유네스코 세종 대왕 문해상」 — 평가 글 (간추림)"},"mis":"K3-2-u3-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#18','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C6',3,'mc','auto','「한 기관의 조사에 따르면」을 출처가 있는 자료로 고친 것은 무엇인가요?',ARRAY['K3-2-u3-X32']::text[],false,'{"seq":18,"concept":"K3-2-u3-C6","difficulty":3,"kind":"mc","stem":"「한 기관의 조사에 따르면」을 출처가 있는 자료로 고친 것은 무엇인가요?","options":[{"t":"조사한 기관의 이름을 밝혀 「○○의 조사에 따르면」이라고 쓴다","correct":true},{"t":"「여러 기관의 조사에 따르면」으로 바꾼다","mis":"K3-2-u3-X32"},{"t":"「조사에 따르면」만 남긴다","mis":"K3-2-u3-X32"}],"explanation":["출처는 찾아갈 수 있는 곳의 이름이 있어야 해요.","「한 기관」, 「여러 기관」은 어디인지 알 수 없어요.","기관 이름을 밝혀야 출처가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#19','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C13',3,'error','auto','이어 주는 말을 쓰는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X18','K3-2-u3-X19','K3-2-u3-X16']::text[],false,'{"seq":19,"concept":"K3-2-u3-C13","difficulty":3,"kind":"error","stem":"이어 주는 말을 쓰는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도율: 이어 주는 말은 문장마다 빠짐없이 넣어야 좋은 글이야.","correct":true,"mis_target":"K3-2-u3-X18"},{"t":"나래: 앞뒤 문장이 자연스럽게 이어지는지 보고 넣어야 해.","mis":"K3-2-u3-X19"},{"t":"세준: 앞뒤 관계를 드러낼 때 알맞은 말을 골라 써.","mis":"K3-2-u3-X16"}],"explanation":["문장마다 넣는다고 좋은 글이 되지 않아요.","앞뒤 관계를 드러낼 필요가 있을 때 알맞은 말을 골라요.","앞뒤가 자연스럽게 이어지는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#20','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C15',3,'mc','auto','「한지 제기 만드는 방법」에서 「연필로 구멍을 뚫는다」는 단계를 빼고 설명했어요. 어떤 일이 생길까요?',ARRAY['K3-2-u3-X35','K3-2-u3-X01']::text[],false,'{"seq":20,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"「한지 제기 만드는 방법」에서 「연필로 구멍을 뚫는다」는 단계를 빼고 설명했어요. 어떤 일이 생길까요?","options":[{"t":"한지의 양 끝을 넣을 구멍이 없어 고정할 수 없다","correct":true},{"t":"빼도 제기는 그대로 만들어진다","mis":"K3-2-u3-X35"},{"t":"글이 짧아져 더 좋은 글이 된다","mis":"K3-2-u3-X01"}],"explanation":["네 번째 단계에서 구멍에 한지의 양 끝을 넣어요.","구멍을 뚫는 단계가 없으면 다음 단계를 할 수 없어요.","앞 단계가 다음 단계를 위한 준비일 때가 많아요."],"asset":{"type":"passage","lines":["㉠ 연필로 고리 중심 부분에 한지와 함께 구멍을 뚫는다.","㉡ 한지 네다섯 장, 금속 연결 고리 한 개, 연필 하나를 준비한다.","㉢ 구멍에 한지의 양 끝을 넣어 고정하고, 끝을 잘게 찢는다.","㉣ 한지 가운데 아래쪽에 고리를 놓고 한지와 함께 돌돌 만다."],"title":"「한지 제기 만드는 방법」 — 단계가 섞여 있음 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#21','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C8',3,'mc','auto','출처가 있는 자료에 내가 알고 있던 것과 다른 내용이 나왔어요. 어떻게 하면 좋을까요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13']::text[],false,'{"seq":21,"concept":"K3-2-u3-C8","difficulty":3,"kind":"mc","stem":"출처가 있는 자료에 내가 알고 있던 것과 다른 내용이 나왔어요. 어떻게 하면 좋을까요?","options":[{"t":"출처를 찾아가 확인해 보고, 왜 다른지 생각해 본다","correct":true},{"t":"출처가 있으니 내가 알던 것이 틀렸다고 바로 믿는다","mis":"K3-2-u3-X12"},{"t":"내가 알던 것과 다르니 자료가 거짓이라고 바로 정한다","mis":"K3-2-u3-X13"}],"explanation":["『국어』 117쪽 활용 질문 「알고 있던 것과 다른 내용은 없나요?」를 떠올려요.","다른 내용이 있으면 출처를 찾아 확인해 봐요.","바로 믿거나 바로 의심하지 않고 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#22','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C2',3,'mc','auto','설명하는 글을 쓰다가 아는 것만으로는 내용이 모자랐어요. 어떻게 해야 할까요?',ARRAY['K3-2-u3-X02']::text[],false,'{"seq":22,"concept":"K3-2-u3-C2","difficulty":3,"kind":"mc","stem":"설명하는 글을 쓰다가 아는 것만으로는 내용이 모자랐어요. 어떻게 해야 할까요?","options":[{"t":"책이나 누리집을 찾아보거나 잘 아는 어른께 여쭈어 확인한다","correct":true},{"t":"그럴듯하게 지어내서 쓴다","mis":"K3-2-u3-X02"},{"t":"짐작한 내용을 사실처럼 쓴다","mis":"K3-2-u3-X02"}],"explanation":["모자란 내용은 찾아보고 확인해요.","부모님께 여쭈거나 책, 누리집을 볼 수 있어요.","지어내거나 짐작해 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#23','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C19',4,'essay','teacher','『국어』 141쪽 생활 속으로처럼 가족과 함께 다녀왔던 곳을 찾아가는 방법을 친구들에게 설명하는 글을 쓰세요. 처음·가운데·끝으로 나누고 순서를 나타내는 말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u3-C19","difficulty":4,"kind":"essay","stem":"『국어』 141쪽 생활 속으로처럼 가족과 함께 다녀왔던 곳을 찾아가는 방법을 친구들에게 설명하는 글을 쓰세요. 처음·가운데·끝으로 나누고 순서를 나타내는 말을 쓰세요.","answer_guide":{"answer":"예: (처음) 우리 학교에서 도서관에 찾아가는 방법을 알려 줄게요. (가운데) 먼저, 학교 정문을 나와 오른쪽으로 걸어요. 다음으로, 횡단보도를 건너 문구점 앞에서 왼쪽으로 가요. 끝으로, 큰 나무가 있는 건물이 도서관이에요. (끝) 이 차례대로 가면 쉽게 찾을 수 있어요.","scoring_points":["처음·가운데·끝으로 나누어 썼는가","가는 차례를 순서를 나타내는 말로 드러냈는가","읽는 사람이 따라갈 수 있게 자세히 썼는가"]},"explanation":["출발하는 곳과 도착하는 곳을 먼저 정해요.","가는 차례를 빠뜨리지 않고 써요.","눈에 띄는 건물을 함께 쓰면 찾기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#24','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C7',4,'essay','teacher','『국어활동』 43쪽 글 나는 자료의 출처가 없어요. 글 나를 더 믿음이 가는 글로 고치려면 어떻게 해야 하는지 쓰고, 그렇게 고치면 좋은 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u3-C7","difficulty":4,"kind":"essay","stem":"『국어활동』 43쪽 글 나는 자료의 출처가 없어요. 글 나를 더 믿음이 가는 글로 고치려면 어떻게 해야 하는지 쓰고, 그렇게 고치면 좋은 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 걷기가 건강에 좋다는 자료를 만든 기관을 찾아 「○○에 따르면」처럼 본문 속에 밝히거나 자료 아래에 「■ 출처」를 쓴다. 그러면 읽는 사람이 자료가 믿을 만한지 확인할 수 있고, 출처에서 걷기에 대한 정보를 더 찾아볼 수 있다.","scoring_points":["출처를 밝히는 방법을 썼는가","믿을 만한지 확인할 수 있다는 점을 썼는가","정보를 더 찾아볼 수 있다는 점을 썼는가"]},"explanation":["출처가 없는 자료는 믿을 만한지 확인하기 어려워요.","자료를 만든 곳을 찾아 출처를 밝혀요.","출처가 있으면 확인도 하고 더 찾아볼 수도 있어요."],"asset":{"type":"passage","lines":["글 가 — 의견: 자신에게 필요한 만큼의 물을 충분히 마시자.","글 가 — 자료의 출처: 「한국인 영양소 섭취 기준」, 보건복지부·한국영양학회.","글 나 — 의견: 가장 안전하고 간편한 운동인 걷기를 규칙적으로 실천하자.","글 나 — 자료의 출처: (적혀 있지 않음)"],"title":"글 가와 글 나를 정리한 표 — 『국어활동』 43쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_c#25','kor',3,2,'u3','','tb_g3_2_kor_u3_review_c','unit_review','K3-2-u3-C18',4,'essay','teacher','수지가 고쳐 쓴 「전기 제품, 이렇게 쓰면 안전해요」를 『국어』 137쪽 점검 물음 네 가지로 살펴보고, 잘된 점 두 가지와 더 고치면 좋을 점 한 가지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u3-C18","difficulty":4,"kind":"essay","stem":"수지가 고쳐 쓴 「전기 제품, 이렇게 쓰면 안전해요」를 『국어』 137쪽 점검 물음 네 가지로 살펴보고, 잘된 점 두 가지와 더 고치면 좋을 점 한 가지를 쓰세요.","answer_guide":{"answer":"예: 잘된 점 — 규칙을 첫째부터 넷째까지 나누어 일의 방법이 잘 드러난다. 과열·합선 같은 어려운 낱말을 쉬운 말로 바꾸어 바르고 정확한 문장으로 썼다. 더 고칠 점 — 읽는 사람이 궁금해할 만한 까닭(왜 젖은 손으로 만지면 안 되는지)을 한 줄씩 덧붙이면 좋겠다.","scoring_points":["점검 물음에 비추어 잘된 점을 두 가지 썼는가","더 고칠 점을 한 가지 썼는가","고칠 점이 읽는 사람을 생각한 것인가"]},"explanation":["점검 물음은 순서·방법, 궁금한 내용, 바른 문장, 이어 주는 말이에요.","잘된 점과 고칠 점을 함께 찾아요.","읽는 사람이 궁금해할 내용을 생각해요."],"asset":{"type":"passage","lines":["(간추림) 처음 부분은 처음 쓴 글과 같다.","첫째, 젖은 손으로 전기 제품을 만지면 안 돼요.","둘째, 전깃줄을 뺄 때에는 줄이 아니라 꽂개를 꼭 잡고 빼야 해요.","셋째, 전기를 많이 사용하는 여러 개의 전기 제품을","모둠 전원 꽂이에 한꺼번에 꽂으면 안 돼요.","넷째, 고장 난 전기 제품은 혼자 고치지 말고 어른께 알려야 해요.","(간추림) 끝 — 가정에서 전기 제품을 어떻게 써야 안전한지 꼭 기억하자.","■ 출처: 「전기 제품을 안전하게 사용할 때 지켜야 할 약속」, 한국전기안전공사 누리집."],"title":"「전기 제품, 이렇게 쓰면 안전해요」 수지가 고쳐 쓴 글 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#1','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C3',1,'mc','auto','「올바른 손 씻기」에서 글을 쓴 사람과 그림 자료의 출처를 바르게 묶은 것은 무엇인가요?',ARRAY['K3-2-u3-X03']::text[],false,'{"seq":1,"concept":"K3-2-u3-C3","difficulty":1,"kind":"mc","stem":"「올바른 손 씻기」에서 글을 쓴 사람과 그림 자료의 출처를 바르게 묶은 것은 무엇인가요?","options":[{"t":"글쓴이 — 김이도 어린이 기자 · 출처 — 질병관리청 누리집","correct":true},{"t":"글쓴이 — 질병관리청 · 출처 — 김이도 어린이 기자","mis":"K3-2-u3-X03"},{"t":"글쓴이 — 국제연합 · 출처 — 학급 신문","mis":"K3-2-u3-X03"},{"t":"글쓴이와 출처 모두 김이도 어린이 기자","mis":"K3-2-u3-X03"}],"explanation":["김이도 어린이 기자가 학급 신문에 글을 썼어요.","그림 자료는 질병관리청 누리집에서 가져왔어요.","글쓴이와 출처를 가려서 읽어요."],"asset":{"type":"passage","lines":["국제연합에서는 2008년에 10월 15일을 ‘세계 손 씻기의 날’로 정했습니다.","(간추림) 올바른 손 씻기의 중요성을 알리고 감염병으로부터 어린이를 보호하려는 날이다.","2023년 질병관리청의 ‘올바른 손 씻기’ 안내 자료에 따르면,","흐르는 물에 비누를 사용해 30초 이상 꼼꼼하게 손을 씻어야 한다고 합니다.","(간추림) 손을 제대로 씻으려면 여섯 단계를 거쳐야 한다.","[그림] 올바른 손 씻기 6단계 — 손바닥부터 손톱 밑까지 차례대로 그린 그림","■ 출처: 「올바른 손 씻기 6단계」, 질병관리청 누리집.","[글쓴이] 김이도 어린이 기자"],"title":"「올바른 손 씻기」 — 학급 신문, 『국어』 110~111쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#2','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C4',1,'mc','auto','『국어』를 만들 때 활용한 작품과 자료의 출처는 어디에서 확인할 수 있나요?',ARRAY['K3-2-u3-X04','K3-2-u3-X09']::text[],false,'{"seq":2,"concept":"K3-2-u3-C4","difficulty":1,"kind":"mc","stem":"『국어』를 만들 때 활용한 작품과 자료의 출처는 어디에서 확인할 수 있나요?","options":[{"t":"『국어』 뒤쪽 「실린 작품」","correct":true},{"t":"『국어』 표지 그림","mis":"K3-2-u3-X04"},{"t":"각 단원의 제목","mis":"K3-2-u3-X04"},{"t":"출처가 적혀 있지 않다","mis":"K3-2-u3-X09"}],"explanation":["『국어』 144~145쪽 「실린 작품」에 출처가 있어요.","교과서를 만들 때도 다양한 자료를 활용했어요.","그 자료의 출처를 자세히 밝히고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#3','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C12',1,'blank','auto','「오늘은 할아버지 생신이다. (     ) 우리 가족은 생신 축하 떡을 나누어 먹었다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":3,"concept":"K3-2-u3-C12","difficulty":1,"kind":"blank","stem":"「오늘은 할아버지 생신이다. (     ) 우리 가족은 생신 축하 떡을 나누어 먹었다.」 빈칸에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그래서","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"}],"explanation":["할아버지 생신인 것이 떡을 나누어 먹은 이유예요.","앞이 뒤의 이유가 되니 ‘그래서’를 써요.","‘왜 떡을 먹었지?’ 하고 물어 보면 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#4','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C7',1,'ox','auto','『국어』 141쪽 표지판 ㉣ 「자료의 출처를 보면 글의 내용이 믿을 만한지 확인할 수 있다.」는 알맞은 설명이에요.',ARRAY['K3-2-u3-X10']::text[],false,'{"seq":4,"concept":"K3-2-u3-C7","difficulty":1,"kind":"ox","stem":"『국어』 141쪽 표지판 ㉣ 「자료의 출처를 보면 글의 내용이 믿을 만한지 확인할 수 있다.」는 알맞은 설명이에요.","answer":"O","reason_options":[{"t":"출처를 보면 자료를 가져온 곳을 살펴 믿을 만한지 확인할 수 있어요.","correct":true},{"t":"출처를 보면 글을 읽지 않아도 내용을 다 알 수 있어요.","mis":"K3-2-u3-X10"}],"mis":"K3-2-u3-X10","explanation":["출처를 확인하며 읽으면 좋은 점이에요.","자료가 믿을 만한지 확인할 수 있어요.","관련 있는 정보를 더 찾아볼 수도 있어요."],"asset":{"type":"passage","lines":["㉠ 설명하는 글을 쓸 때에는 어려운 낱말을 많이 써야 한다.","㉡ 이어 주는 말의 앞뒤 문장이 자연스럽게 연결되었는지 확인한다.","㉢ 설명하는 글에서는 ‘첫째’, ‘그다음에는’과 같은 말을 사용하면 이해하기 쉽다.","㉣ 자료의 출처를 보면 글의 내용이 믿을 만한지 확인할 수 있다."],"title":"스스로 확인하기 — 길에 선 표지판 넷, 『국어』 141쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#5','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C20',1,'mc','auto','「현지는 감기에 걸려 못 온대.」에서 「온대」는 어떤 말이 줄어든 말인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":5,"concept":"K3-2-u3-C20","difficulty":1,"kind":"mc","stem":"「현지는 감기에 걸려 못 온대.」에서 「온대」는 어떤 말이 줄어든 말인가요?","options":[{"t":"온다고 해","correct":true},{"t":"온 것을 내가 보았어","mis":"K3-2-u3-X29"},{"t":"오지 않았는데","mis":"K3-2-u3-X29"}],"explanation":["‘-대’는 ‘-다고 해’가 줄어든 말이에요.","「온대」는 「온다고 해」예요.","남에게 들은 말을 전할 때 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#6','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C10',1,'mc','auto','「송암 박두성 선생이 한글 점자를 만들어 반포했습니다.」에서 「반포했습니다」의 뜻은 무엇인가요?',ARRAY['K3-2-u3-X15']::text[],false,'{"seq":6,"concept":"K3-2-u3-C10","difficulty":1,"kind":"mc","stem":"「송암 박두성 선생이 한글 점자를 만들어 반포했습니다.」에서 「반포했습니다」의 뜻은 무엇인가요?","options":[{"t":"세상에 널리 퍼뜨려 모두 알게 했습니다","correct":true},{"t":"전에 없던 것을 새로 만들었습니다","mis":"K3-2-u3-X15"},{"t":"손끝으로 만져서 읽었습니다","mis":"K3-2-u3-X15"}],"explanation":["점자를 만든 뒤 사람들이 쓸 수 있게 널리 알렸어요.","그래서 「반포했습니다」는 「널리 퍼뜨려 알게 했습니다」예요.","새로 만드는 것은 「창제」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#7','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C1',1,'mc','auto','순서나 방법을 설명하는 글은 어떤 글인가요?',ARRAY['K3-2-u3-X31']::text[],false,'{"seq":7,"concept":"K3-2-u3-C1","difficulty":1,"kind":"mc","stem":"순서나 방법을 설명하는 글은 어떤 글인가요?","options":[{"t":"무엇을 하는 방법이나 차례를 읽는 사람이 따라 할 수 있게 알려 주는 글","correct":true},{"t":"내 느낌을 꾸며 쓰는 글","mis":"K3-2-u3-X31"},{"t":"꾸며 낸 이야기를 들려주는 글","mis":"K3-2-u3-X31"}],"explanation":["종이비행기 접는 방법, 사물함 정리 방법을 알려 주는 글이에요.","읽는 사람이 그대로 따라 할 수 있어야 해요.","그래서 일의 차례가 잘 드러나야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#8','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C7',1,'mc','auto','『국어』 141쪽 생활 속으로에서 「글을 읽다가 더 궁금한 점이 있으면 출처를 찾아볼 거야.」라고 했어요. 이 친구가 알게 된 출처의 좋은 점은 무엇인가요?',ARRAY['K3-2-u3-X10','K3-2-u3-X12']::text[],false,'{"seq":8,"concept":"K3-2-u3-C7","difficulty":1,"kind":"mc","stem":"『국어』 141쪽 생활 속으로에서 「글을 읽다가 더 궁금한 점이 있으면 출처를 찾아볼 거야.」라고 했어요. 이 친구가 알게 된 출처의 좋은 점은 무엇인가요?","options":[{"t":"출처에서 주제와 관련 있는 정보를 더 찾아볼 수 있다","correct":true},{"t":"출처만 보면 글을 읽지 않아도 된다","mis":"K3-2-u3-X10"},{"t":"출처가 있으면 무엇이든 맞다","mis":"K3-2-u3-X12"}],"explanation":["궁금한 점이 생기면 출처에 가서 더 알아볼 수 있어요.","출처는 더 찾아볼 곳을 알려 줘요.","이렇게 출처를 활용하면 글을 더 깊이 이해해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#9','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C6',2,'mc','auto','『국어활동』 43쪽 (1)이에요. 글 가에 나타난 자료의 출처를 바르게 쓴 것은 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":9,"concept":"K3-2-u3-C6","difficulty":2,"kind":"mc","stem":"『국어활동』 43쪽 (1)이에요. 글 가에 나타난 자료의 출처를 바르게 쓴 것은 무엇인가요?","options":[{"t":"「한국인 영양소 섭취 기준」, 보건복지부·한국영양학회","correct":true},{"t":"자신에게 필요한 만큼의 물을 충분히 마시자","mis":"K3-2-u3-X08"},{"t":"가장 안전하고 간편한 운동인 걷기","mis":"K3-2-u3-X08"}],"explanation":["「물을 충분히 마시자」는 글 가의 글쓴이의 의견이에요.","자료의 출처는 「한국인 영양소 섭취 기준」, 보건복지부·한국영양학회예요.","의견과 출처를 가려서 정리해요."],"asset":{"type":"passage","lines":["글 가 — 의견: 자신에게 필요한 만큼의 물을 충분히 마시자.","글 가 — 자료의 출처: 「한국인 영양소 섭취 기준」, 보건복지부·한국영양학회.","글 나 — 의견: 가장 안전하고 간편한 운동인 걷기를 규칙적으로 실천하자.","글 나 — 자료의 출처: (적혀 있지 않음)"],"title":"글 가와 글 나를 정리한 표 — 『국어활동』 43쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#10','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C12',2,'mc','auto','‘그리고’를 알맞게 쓴 것은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":10,"concept":"K3-2-u3-C12","difficulty":2,"kind":"mc","stem":"‘그리고’를 알맞게 쓴 것은 무엇인가요?","options":[{"t":"나는 숙제를 했다. 그리고 일기도 썼다.","correct":true},{"t":"나는 우산을 챙겼다. 그리고 우산이 없었다.","mis":"K3-2-u3-X16"},{"t":"나는 배가 고팠다. 그리고 배가 불렀다.","mis":"K3-2-u3-X16"}],"explanation":["‘그리고’는 앞과 비슷한 내용이 이어질 때 써요.","숙제를 한 일에 일기를 쓴 일이 더해졌어요.","앞뒤가 반대일 때는 ‘그러나’를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#11','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C17',2,'mc','auto','개인 사물함을 정리하는 방법을 설명하는 글의 제목으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X31']::text[],false,'{"seq":11,"concept":"K3-2-u3-C17","difficulty":2,"kind":"mc","stem":"개인 사물함을 정리하는 방법을 설명하는 글의 제목으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「개인 사물함을 정리하는 방법」","correct":true},{"t":"「나의 즐거운 하루」","mis":"K3-2-u3-X31"},{"t":"「깨끗해서 기분 좋아!」","mis":"K3-2-u3-X31"}],"explanation":["제목만 보고도 무엇을 설명하는 글인지 알 수 있어야 해요.","「개인 사물함을 정리하는 방법」이 알맞아요.","느낌을 나타낸 제목은 설명하는 글과 어울리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#12','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C11',2,'mc','auto','「자전거 안전모를 써요」를 읽은 친구가 「‘질병관리청’은 처음 들어 봐.」라고 했어요. 무엇을 하면 좋을까요?',ARRAY['K3-2-u3-X13','K3-2-u3-X14']::text[],false,'{"seq":12,"concept":"K3-2-u3-C11","difficulty":2,"kind":"mc","stem":"「자전거 안전모를 써요」를 읽은 친구가 「‘질병관리청’은 처음 들어 봐.」라고 했어요. 무엇을 하면 좋을까요?","options":[{"t":"질병관리청이 어떤 일을 하는 곳인지 알아본다","correct":true},{"t":"처음 들었으니 거짓 자료라고 여긴다","mis":"K3-2-u3-X13"},{"t":"이름이 어려우니 믿을 만하다고 여긴다","mis":"K3-2-u3-X14"}],"explanation":["출처를 처음 보면 어떤 곳인지 알아봐요.","누리집에 들어가 그곳이 하는 일을 살펴볼 수 있어요.","처음 들었다고 거짓이라고 정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#13','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C15',2,'mc','auto','차례를 나타내는 말을 순서에 맞게 늘어놓은 것은 무엇인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X16']::text[],false,'{"seq":13,"concept":"K3-2-u3-C15","difficulty":2,"kind":"mc","stem":"차례를 나타내는 말을 순서에 맞게 늘어놓은 것은 무엇인가요?","options":[{"t":"처음에 → 그다음에 → 마지막으로","correct":true},{"t":"마지막으로 → 처음에 → 그다음에","mis":"K3-2-u3-X22"},{"t":"그러나 → 그래서 → 그리고","mis":"K3-2-u3-X16"}],"explanation":["차례를 나타내는 말은 일의 순서에 맞게 써요.","처음에, 그다음에, 마지막으로 차례예요.","그러나, 그래서, 그리고는 이어 주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#14','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C16',2,'mc','auto','친구가 「찾아본 자료는 아예 글에 쓰면 안 돼.」라고 했어요. 바른 생각은 무엇인가요?',ARRAY['K3-2-u3-X07','K3-2-u3-X06']::text[],false,'{"seq":14,"concept":"K3-2-u3-C16","difficulty":2,"kind":"mc","stem":"친구가 「찾아본 자료는 아예 글에 쓰면 안 돼.」라고 했어요. 바른 생각은 무엇인가요?","options":[{"t":"출처를 밝히면 찾아본 자료도 글에 쓸 수 있다","correct":true},{"t":"찾아본 자료는 아예 빼야 한다","mis":"K3-2-u3-X07"},{"t":"출처 없이 내 것처럼 쓴다","mis":"K3-2-u3-X06"}],"explanation":["조사한 자료는 글을 정확하게 해 줘요.","가져온 곳을 밝히면 글에 쓸 수 있어요.","출처는 글의 맨 끝에 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#15','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C18',2,'mc','auto','친구는 「양말을 돌돌 말아서 정리한다.」고, 나는 「반으로 접어서 정리한다.」고 썼어요. 어떻게 생각해야 할까요?',ARRAY['K3-2-u3-X27']::text[],false,'{"seq":15,"concept":"K3-2-u3-C18","difficulty":2,"kind":"mc","stem":"친구는 「양말을 돌돌 말아서 정리한다.」고, 나는 「반으로 접어서 정리한다.」고 썼어요. 어떻게 생각해야 할까요?","options":[{"t":"둘 다 차례와 까닭이 드러나면 알맞은 글이다","correct":true},{"t":"내 방법과 다르니 친구 글은 틀렸다","mis":"K3-2-u3-X27"},{"t":"방법이 하나로 같아야 설명하는 글이다","mis":"K3-2-u3-X27"}],"explanation":["양말은 반으로 접거나 말아서 정리할 수 있어요.","같은 일도 방법이 다를 수 있어요.","차례와 까닭이 드러나면 둘 다 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#16','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C19',2,'mc','auto','기차 이용 설명서를 네 문단으로 나누어 쓰기로 했어요. 「기차를 탈 때 주의할 점」은 몇째 문단에 쓰기로 했나요?',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":16,"concept":"K3-2-u3-C19","difficulty":2,"kind":"mc","stem":"기차 이용 설명서를 네 문단으로 나누어 쓰기로 했어요. 「기차를 탈 때 주의할 점」은 몇째 문단에 쓰기로 했나요?","options":[{"t":"마지막 문단","correct":true},{"t":"첫째 문단","mis":"K3-2-u3-X25"},{"t":"셋째 문단","mis":"K3-2-u3-X25"}],"explanation":["첫째는 기차의 특징, 둘째는 타기 전에 할 일이에요.","셋째는 기차 이용 방법이에요.","주의할 점은 마지막 문단에 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나는 첫째 문단에 기차의 특징을 쓸 거야."},{"who":"친구 2","text":"나는 둘째 문단을 쓸 거야. 기차를 이용하는 차례를 생각해 볼게."},{"who":"친구 3","text":"나는 셋째 문단에 기차 이용 방법을 쓸 거야."},{"who":"친구 4","text":"나는 마지막 문단에 기차를 탈 때 주의할 점을 쓸 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#17','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C9',3,'mc','auto','평가 글 「유네스코 세종 대왕 문해상」에서 ‘문해’의 뜻과 상을 주는 날을 바르게 묶은 것은 무엇인가요?',ARRAY['K3-2-u3-X15','K3-2-u3-X08']::text[],false,'{"seq":17,"concept":"K3-2-u3-C9","difficulty":3,"kind":"mc","stem":"평가 글 「유네스코 세종 대왕 문해상」에서 ‘문해’의 뜻과 상을 주는 날을 바르게 묶은 것은 무엇인가요?","options":[{"t":"글을 읽고 이해한다는 뜻 — 9월 8일 세계 문해의 날","correct":true},{"t":"글씨를 예쁘게 쓴다는 뜻 — 10월 9일 한글날","mis":"K3-2-u3-X15"},{"t":"글을 읽고 이해한다는 뜻 — 11월 4일 한글 점자의 날","mis":"K3-2-u3-X08"}],"explanation":["「‘문해’란 글을 읽고 이해한다는 뜻이에요.」라고 했어요.","상은 세계 문해의 날인 9월 8일에 줘요.","출처만 찾지 말고 글의 내용도 함께 파악해요."],"asset":{"type":"passage","lines":["(간추림) 한국 정부가 유네스코에 제의해서 만든 ‘유네스코 세종 대왕 문해상’이 있다.","여기서 ‘문해’란 글을 읽고 이해한다는 뜻이에요.","(간추림) 글을 익히도록 도운 개인과 단체를 뽑아 세계 문해의 날(9월 8일)에 준다.","문화체육관광부의 보도 자료에 따르면, 1990년부터 2024년까지","전 세계 68개의 단체와 개인이 유네스코 세종 대왕 문해상을 받았습니다.","(간추림) 세종 대왕의 한글 창제 정신이 이 상을 통해 전 세계에 퍼지고 있다."],"title":"「유네스코 세종 대왕 문해상」 — 평가 글 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#18','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C6',3,'mc','auto','「자전거 안전모를 써요」에서 출처를 확인해야 할 자료를 모두 고르면 무엇인가요?',ARRAY['K3-2-u3-X33','K3-2-u3-X09']::text[],false,'{"seq":18,"concept":"K3-2-u3-C6","difficulty":3,"kind":"mc","stem":"「자전거 안전모를 써요」에서 출처를 확인해야 할 자료를 모두 고르면 무엇인가요?","options":[{"t":"㉮, ㉯, ㉰, ㉱ 네 가지 모두","correct":true},{"t":"㉯, ㉱ — 사진과 그림만","mis":"K3-2-u3-X33"},{"t":"㉰ 하나만","mis":"K3-2-u3-X09"}],"explanation":["사진과 그림뿐 아니라 글에 인용된 조사 결과도 자료예요.","네 자료 모두 출처가 있는지 확인해요.","확인해 보면 ㉰, ㉱는 출처가 있고 ㉮, ㉯는 없어요."],"asset":{"type":"passage","lines":["요즘 자전거를 타는 어린이는 많지만 안전모를 바르게 착용하는 어린이는 적습니다.","㉮ 한 기관의 조사에 따르면, 자전거를 탈 때 안전모를 쓰는 사람은","다섯 명 가운데 한 명밖에 되지 않는다고 합니다.","㉯ [사진] 단풍 든 길에서 자전거를 타는 두 어린이 (사진 아래에 아무 글 없음)","㉰ 2023년 질병관리청의 자료에 따르면, 자전거를 탈 때 안전모를 쓰면","두 명 가운데 한 명은 머리 다치는 것을 예방할 수 있다고 합니다.","㉱ [그림] 2-4-1 법칙 — ■ 출처: 「2-4-1 법칙」, 서울특별시 자전거 누리 소통망.","우리 모두 안전모를 착용하는 습관을 들여 안전하게 자전거를 타야 하겠습니다."],"title":"「자전거 안전모를 써요」 — 『국어』 114~115쪽 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#19','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C13',3,'mc','auto','긴 문장 「나는 감기에 걸렸는데도 학교에 갔다.」를 짧은 두 문장으로 나누어 이어 주는 말로 바르게 이은 것은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X19']::text[],false,'{"seq":19,"concept":"K3-2-u3-C13","difficulty":3,"kind":"mc","stem":"긴 문장 「나는 감기에 걸렸는데도 학교에 갔다.」를 짧은 두 문장으로 나누어 이어 주는 말로 바르게 이은 것은 무엇인가요?","options":[{"t":"나는 감기에 걸렸다. 그러나 학교에 갔다.","correct":true},{"t":"나는 감기에 걸렸다. 그래서 학교에 갔다.","mis":"K3-2-u3-X16"},{"t":"나는 감기에 걸렸다. 학교에 갔다.","mis":"K3-2-u3-X19"}],"explanation":["감기에 걸렸으면 쉴 것 같은데 학교에 갔어요.","반대되는 내용이 이어지니 ‘그러나’예요.","긴 문장을 짧게 나누면 이어 주는 말로 관계를 드러내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#20','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C15',3,'mc','auto','긴팔 윗옷을 개는 방법을 설명하면서 「소매를 중심선을 향해 모아 준다」를 빼고 바로 접으라고 했어요. 어떤 일이 생길까요?',ARRAY['K3-2-u3-X35','K3-2-u3-X01']::text[],false,'{"seq":20,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"긴팔 윗옷을 개는 방법을 설명하면서 「소매를 중심선을 향해 모아 준다」를 빼고 바로 접으라고 했어요. 어떤 일이 생길까요?","options":[{"t":"소매가 삐져나와 윗옷을 반듯하게 갤 수 없다","correct":true},{"t":"빼도 똑같이 반듯하게 갤 수 있다","mis":"K3-2-u3-X35"},{"t":"설명이 짧아져서 더 알기 쉬워진다","mis":"K3-2-u3-X01"}],"explanation":["소매를 모으는 것은 반듯하게 개기 위한 중요한 단계예요.","빠뜨리면 듣는 사람이 그대로 따라 해도 잘 갤 수 없어요.","중요한 순서는 빠뜨리지 않고 설명해요."],"asset":{"type":"passage","lines":["㉠ 위에서 3분의 1 지점을 안으로 접어 준다.","㉡ 윗옷을 반듯하게 펼쳐 놓는다.","㉢ 원하는 곳에 보관한다.","㉣ 소매를 옷의 중심선을 향해 가지런히 모아 준다.","㉤ 아래에서 3분의 1 지점을 안으로 접어 준다."],"title":"긴팔 윗옷을 개는 방법 (차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#21','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C8',3,'error','auto','출처가 있는 자료를 읽는 태도를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X13','K3-2-u3-X12']::text[],false,'{"seq":21,"concept":"K3-2-u3-C8","difficulty":3,"kind":"error","stem":"출처가 있는 자료를 읽는 태도를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가람: 출처가 있어도 다 거짓말일 수 있으니 하나도 믿지 마.","correct":true,"mis_target":"K3-2-u3-X13"},{"t":"다빈: 출처가 어떤 곳인지 살펴보면서 읽어.","mis":"K3-2-u3-X12"},{"t":"유찬: 알던 것과 다르면 출처에 가서 확인해 봐.","mis":"K3-2-u3-X13"}],"explanation":["출처가 있는 자료를 무조건 의심하는 것도 알맞지 않아요.","어떤 곳인지 살펴보고 확인하며 읽어요.","살펴보고 생각하는 것이 바른 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#22','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C16',3,'mc','auto','사진을 넣고 출처 칸에 어디서 가져왔는지 몰라서 「인터넷」이라고만 썼어요. 어떻게 고쳐야 할까요?',ARRAY['K3-2-u3-X23','K3-2-u3-X28']::text[],false,'{"seq":22,"concept":"K3-2-u3-C16","difficulty":3,"kind":"mc","stem":"사진을 넣고 출처 칸에 어디서 가져왔는지 몰라서 「인터넷」이라고만 썼어요. 어떻게 고쳐야 할까요?","options":[{"t":"어느 누리집인지 다시 찾아 확인해 그 이름을 적는다","correct":true},{"t":"「인터넷」이라고만 써도 충분하다","mis":"K3-2-u3-X23"},{"t":"사진은 출처를 쓰지 않아도 되니 지운다","mis":"K3-2-u3-X28"}],"explanation":["「인터넷」만으로는 찾아갈 곳을 알 수 없어요.","사진을 가져온 누리집을 확인해 이름을 적어요.","사진 자료도 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#23','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C16',4,'essay','teacher','『국어』 141쪽 생활 속으로처럼 수영할 때 주의해야 할 점을 설명하는 글로 쓰세요. 조사한 자료를 썼다면 출처를 어디에 어떻게 밝힐지도 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-2-u3-C16","difficulty":4,"kind":"essay","stem":"『국어』 141쪽 생활 속으로처럼 수영할 때 주의해야 할 점을 설명하는 글로 쓰세요. 조사한 자료를 썼다면 출처를 어디에 어떻게 밝힐지도 쓰세요.","answer_guide":{"answer":"예: 수영할 때 주의할 점을 알아봅시다. 첫째, 물에 들어가기 전에 준비 운동을 합니다. 둘째, 혼자 수영하지 않고 어른과 함께합니다. 셋째, 깊은 곳에는 들어가지 않습니다. 조사한 책이나 누리집이 있다면 글의 맨 끝에 「■ 출처: 자료 이름, 만든 곳.」처럼 밝힙니다.","scoring_points":["주의할 점을 차례를 나타내는 말로 정리했는가","읽는 사람이 이해하기 쉽게 썼는가","조사한 자료의 출처를 글의 맨 끝에 밝힌다고 썼는가"]},"explanation":["안전에 관한 내용은 정확하게 조사해 써요.","‘첫째, 둘째, 셋째’로 정리하면 기억하기 쉬워요.","조사한 자료는 글 끝에 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#24','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C11',4,'essay','teacher','「손끝으로 읽는 여섯 개의 점」을 읽고 더 궁금한 점이 생겼어요. 궁금한 점을 하나 쓰고, 글의 출처를 활용해 어디에서 어떻게 알아볼지, 찾은 자료를 어떻게 확인할지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u3-C11","difficulty":4,"kind":"essay","stem":"「손끝으로 읽는 여섯 개의 점」을 읽고 더 궁금한 점이 생겼어요. 궁금한 점을 하나 쓰고, 글의 출처를 활용해 어디에서 어떻게 알아볼지, 찾은 자료를 어떻게 확인할지 쓰세요.","answer_guide":{"answer":"예: 궁금한 점 — 훈맹정음이 어떻게 만들어졌는지 더 알고 싶다. 국립한글박물관 누리집에 들어가 「훈맹정음」 자료를 찾아본다. 찾은 내용이 글의 내용과 같은지, 국립한글박물관이 어떤 곳인지도 확인해 본다.","scoring_points":["궁금한 점을 썼는가","글의 출처를 활용해 찾아볼 곳을 썼는가","찾은 자료를 확인하는 방법을 썼는가"]},"explanation":["출처는 더 찾아볼 곳을 알려 줘요.","출처의 누리집에서 자세한 정보를 얻을 수 있어요.","찾은 자료도 어떤 곳의 것인지 확인하며 읽어요."],"asset":{"type":"passage","lines":["10월 9일은 한글날입니다.","그렇다면 11월 4일은 무슨 날일까요?","11월 4일은 바로 한글 점자의 날입니다.","(간추림) 1926년 11월 4일, 송암 박두성 선생이 한글 점자를 만들어 반포했다.","(간추림) 시각 장애인을 위한 이 점자는 훈민정음의 원리를 따라 만들었다.","(간추림) 그래서 시각 장애인을 뜻하는 한자를 넣어 ‘훈맹정음’이라고도 부른다.","[그림] 훈맹정음 책","■ 출처: 「훈맹정음」, 국립한글박물관 누리집."],"title":"「손끝으로 읽는 여섯 개의 점」 앞부분 — 『국어』 119쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_kor_u3_review_d#25','kor',3,2,'u3','','tb_g3_2_kor_u3_review_d','unit_review','K3-2-u3-C19',4,'essay','teacher','모둠에서 버스 이용 설명서를 만들어요. 내가 「버스를 탈 때 주의할 점」 문단을 맡았다면 어떻게 쓸지 한 문단으로 쓰세요. 중심 문장을 먼저 쓰고, 조사한 자료의 출처를 어떻게 밝힐지도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u3-C19","difficulty":4,"kind":"essay","stem":"모둠에서 버스 이용 설명서를 만들어요. 내가 「버스를 탈 때 주의할 점」 문단을 맡았다면 어떻게 쓸지 한 문단으로 쓰세요. 중심 문장을 먼저 쓰고, 조사한 자료의 출처를 어떻게 밝힐지도 쓰세요.","answer_guide":{"answer":"예: 버스를 탈 때에는 몇 가지 주의할 점이 있습니다. 첫째, 버스가 완전히 멈춘 뒤에 타고 내립니다. 둘째, 버스 안에서는 손잡이를 꼭 잡습니다. 셋째, 내릴 때에는 뒤에서 오는 자전거나 오토바이가 없는지 살핍니다. 조사한 자료의 출처는 문단 끝이나 설명서의 맨 끝에 밝힙니다.","scoring_points":["중심 문장을 먼저 썼는가","주의할 점을 차례대로 정리했는가","조사한 자료의 출처를 밝히는 방법을 썼는가"]},"explanation":["문단의 중심 문장은 모둠과 함께 정해요.","뒷받침 내용은 조사해서 차례대로 써요.","조사한 자료는 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
